INSERT INTO public.quote_methods (id, source_text, quote_text, method, best_themes, effect_prompt, meaning_prompt, level_tag, speaker_or_narrator, location_reference, plain_english_meaning, linked_motifs, linked_context, linked_interpretations, opening_stems, comparative_prompts, grade_priority, is_core_quote, b_mode_rank, exam_question_tags, recommended_for_questions, question_types, ao_priority, comparison_strength, retrieval_priority, best_used_for, source_row_key, curation_status, is_active, sort_order) VALUES ('qm_at_01', 'Atonement', 'She was one of those children possessed by a desire to have the world just so.', 'free indirect discourse', '{authorship,guilt,imagination,education}'::text[], '', '', 'top_band', 'Narrator (third-person, close to Briony)', 'Part One, Chapter 1', 'McEwan immediately signals Briony''s controlling, ordering imagination — the quality that makes her both a writer and a person capable of a devastating misreading.', '{"order vs chaos","the child''s perspective",writing}'::text[], '{"postmodernism and unreliable narration","Woolfian stream of consciousness","trauma and memory"}'::text[], '{"McEwan implicates the reader in Briony''s controlling vision","The novel questions whether fiction itself is a moral act"}'::text[], '{"McEwan''s early characterisation of Briony as one ''possessed by a desire'' frames her imagination as","The phrase ''just so'' condenses Briony''s dangerous need for","Through free indirect discourse, McEwan collapses the distance between Briony''s perspective and"}'::text[], '{"Compare how Dickens and McEwan present the dangers of an ordering, systematising imagination","Both Gradgrind and Briony impose a fixed version of reality — compare the consequences"}'::text[], 'higher', 't'::boolean, '1'::integer, '{imagination,"narrative authority","character opening"}'::text[], '{"How does McEwan present Briony?","How does McEwan explore the dangers of the imagination?"}'::text[], '{character,theme,method}'::text[], '{AO2,AO1}'::text[], 'strong', '1'::integer, '{"essay openings","AO2 on free indirect discourse","comparative essays"}'::text[], 'qm_at_01', 'strong', 't'::boolean, NULL::integer) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quote_methods (id, source_text, quote_text, method, best_themes, effect_prompt, meaning_prompt, level_tag, speaker_or_narrator, location_reference, plain_english_meaning, linked_motifs, linked_context, linked_interpretations, opening_stems, comparative_prompts, grade_priority, is_core_quote, b_mode_rank, exam_question_tags, recommended_for_questions, question_types, ao_priority, comparison_strength, retrieval_priority, best_used_for, source_row_key, curation_status, is_active, sort_order) VALUES ('qm_at_02', 'Atonement', 'She was the one who had seen him. The others had not.', 'short declarative sentences', '{authorship,class,guilt}'::text[], '', '', 'top_band', 'Narrator (Briony''s perspective)', 'Part One, Chapter 11', 'Briony falsely believes her single eyewitness account is sufficient to convict Robbie — McEwan exposes the catastrophic overconfidence of a singular, unquestioned perspective.', '{"seeing and misseeing","light and darkness","the fountain scene"}'::text[], '{"1930s class anxiety","rape and legal testimony","second World War"}'::text[], '{"Wood argues McEwan critiques the epistemological arrogance of realism itself","Kermode reads Briony as a figure for the novelist''s dangerous godlike power"}'::text[], '{"McEwan''s use of short declarative syntax — ''She was the one who had seen him'' — enacts the","The stark contrast between ''seen'' and ''had not'' presents truth as","Dramatic irony charges the line because the reader understands that ''seen'' does not equal"}'::text[], '{"Both Dickens and McEwan show how a single authoritative voice can destroy a life — compare","Compare how testimony and misreading function in Hard Times and Atonement"}'::text[], 'higher', 't'::boolean, '2'::integer, '{truth,testimony,guilt}'::text[], '{"How does McEwan present truth?","How does McEwan present guilt and responsibility?"}'::text[], '{theme,method,character}'::text[], '{AO2,AO3}'::text[], 'very strong', '2'::integer, '{"AO2 on declarative syntax","AO3 on 1930s class","comparative essays on testimony"}'::text[], 'qm_at_02', 'strong', 't'::boolean, NULL::integer) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quote_methods (id, source_text, quote_text, method, best_themes, effect_prompt, meaning_prompt, level_tag, speaker_or_narrator, location_reference, plain_english_meaning, linked_motifs, linked_context, linked_interpretations, opening_stems, comparative_prompts, grade_priority, is_core_quote, b_mode_rank, exam_question_tags, recommended_for_questions, question_types, ao_priority, comparison_strength, retrieval_priority, best_used_for, source_row_key, curation_status, is_active, sort_order) VALUES ('qm_at_03', 'Atonement', 'How can a novelist achieve atonement when, with her absolute power of deciding outcomes, she is also God?', 'rhetorical question', '{authorship,guilt,imagination}'::text[], '', '', 'top_band', 'Briony Tallis (as aged narrator)', 'Part Four (London, 1999)', 'In the epilogue, Briony directly confronts the paradox at the heart of the novel: the novelist-god who controls reality cannot genuinely atone because she can simply write a better ending. McEwan questions whether fiction is a moral act or a moral evasion.', '{"writing and authorship","God-like power","the unreliable narrator"}'::text[], '{"Postmodernist questioning of narrative authority (Barthes, ''Death of the Author'')","McEwan''s interest in moral philosophy and consequentialism","The novel''s publication (2001) and debates around literary ethics"}'::text[], '{"Wood argues this question is the most honest moment in the novel — Briony admits the inadequacy of fiction as atonement","Kermode reads the novelist-as-God metaphor as McEwan''s exploration of the ethical responsibility that comes with narrative power","Finney argues the rhetorical question is unanswerable by design — the novel refuses to resolve its own central problem"}'::text[], '{"Briony''s rhetorical question — ''How can a novelist achieve atonement?'' — exposes the paradox that","The equation of novelist with God collapses the distinction between creating fiction and","McEwan refuses to resolve the question, suggesting that the novel''s ethical project is not redemption but"}'::text[], '{"Compare how Dickens and McEwan use moments of narratorial self-consciousness to examine the novelist''s moral responsibility","Both texts raise questions about whether story-telling can repair the damage it — or its author — has caused"}'::text[], 'higher', 't'::boolean, '3'::integer, '{metafiction,atonement,"narrative authority"}'::text[], '{"How does McEwan present the idea of atonement?","How does McEwan use narrative technique?"}'::text[], '{theme,method,form}'::text[], '{AO2,AO1}'::text[], 'very strong', '3'::integer, '{"AO2 on rhetorical question and theological metaphor","AO1 on the novel''s central paradox","essay conclusions"}'::text[], 'qm_at_03', 'strong', 't'::boolean, NULL::integer) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quote_methods (id, source_text, quote_text, method, best_themes, effect_prompt, meaning_prompt, level_tag, speaker_or_narrator, location_reference, plain_english_meaning, linked_motifs, linked_context, linked_interpretations, opening_stems, comparative_prompts, grade_priority, is_core_quote, b_mode_rank, exam_question_tags, recommended_for_questions, question_types, ao_priority, comparison_strength, retrieval_priority, best_used_for, source_row_key, curation_status, is_active, sort_order) VALUES ('qm_at_04', 'Atonement', 'In my account of what happened at the library I have described Robbie''s state of mind in detail... In fact, he says nothing of the kind.', 'metafictional confession', '{authorship,guilt,imagination}'::text[], '', '', 'top_band', 'Briony Tallis (as aged narrator)', 'Part Four (London, 1999)', 'Briony admits that she has invented the interiority she attributed to Robbie — the novel has been simultaneously fictional and confessional. The revelation reframes every previous page: what we read as realism was fiction dressed as testimony.', '{"writing and authorship","the unreliable narrator",testimony}'::text[], '{"Postmodern historiographic metafiction (Linda Hutcheon)","Legal testimony and its constructedness","McEwan''s research into memory and false memory syndrome"}'::text[], '{"Finney reads this confession as the most radical moment of the novel — it retroactively destroys the realist contract","Wood argues that by admitting the invention, Briony performs a more genuine act of honesty than the earlier narrative''s false certainty"}'::text[], '{"Briony''s retrospective correction — ''In fact, he says nothing of the kind'' — performs the collapse of","The self-undermining structure of the confession forces the reader to reassess every authoritative claim made in","McEwan uses Briony''s admission to expose the gap between narrative confidence and"}'::text[], '{"Compare how both texts use retrospective revelation to unsettle the reader''s trust in what they have already read","Both Dickens and McEwan plant ironic distance between what narrators claim and what the text reveals — compare how each manages this"}'::text[], 'higher', 't'::boolean, '4'::integer, '{metafiction,confession,"unreliable narrator"}'::text[], '{"How does McEwan construct an unreliable narrator?","How does McEwan explore truth and fiction?"}'::text[], '{method,form,narrative}'::text[], '{AO2,AO1}'::text[], 'strong', '4'::integer, '{"AO2 on retrospective self-correction","AO1 on the realist contract and its collapse"}'::text[], 'qm_at_04', 'strong', 't'::boolean, NULL::integer) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quote_methods (id, source_text, quote_text, method, best_themes, effect_prompt, meaning_prompt, level_tag, speaker_or_narrator, location_reference, plain_english_meaning, linked_motifs, linked_context, linked_interpretations, opening_stems, comparative_prompts, grade_priority, is_core_quote, b_mode_rank, exam_question_tags, recommended_for_questions, question_types, ao_priority, comparison_strength, retrieval_priority, best_used_for, source_row_key, curation_status, is_active, sort_order) VALUES ('qm_at_05', 'Atonement', 'A person is, among all else, a material thing, easily torn, not easily mended.', 'aphorism', '{guilt,imagination,war}'::text[], '', '', 'top_band', 'Narrator (Briony, close third person)', 'Part Three', 'During her wartime nursing, Briony encounters the physical vulnerability of the human body and — implicitly — begins to understand the scale of what she has done to Robbie. The body as fragile material registers guilt in physical terms.', '{"the body","damage and repair","nursing as atonement"}'::text[], '{"Briony''s wartime nursing at UCH","WWII casualty treatment and triage","McEwan''s research into nursing memoirs of the period"}'::text[], '{"Finney reads this as Briony''s first genuine moral insight — the body teaches what imagination distorted","Head argues the line operates as a thesis for the whole novel: narrative, like the body, is fragile and its damage is irreversible"}'::text[], '{"The aphoristic compression of ''easily torn, not easily mended'' translates Briony''s abstract guilt into","By placing this moral insight in the context of nursing, McEwan links physical repair to the impossibility of","The material metaphor — person as thing — carries a double weight: it echoes the dehumanisation Robbie suffered and"}'::text[], '{"Compare how both texts use physical suffering — bodies broken by systems or circumstances — to register moral damage","Both Hard Times and Atonement associate repair and redemption with physical care — compare how each text treats this"}'::text[], 'higher', 't'::boolean, '5'::integer, '{guilt,"the body",atonement}'::text[], '{"How does McEwan present guilt?","How does McEwan present Briony''s atonement?"}'::text[], '{theme,method,character}'::text[], '{AO2,AO1}'::text[], 'very strong', '5'::integer, '{"AO2 on aphorism and material metaphor","AO1 on nursing as atonement","comparative essays on repair"}'::text[], 'qm_at_05', 'strong', 't'::boolean, NULL::integer) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quote_methods (id, source_text, quote_text, method, best_themes, effect_prompt, meaning_prompt, level_tag, speaker_or_narrator, location_reference, plain_english_meaning, linked_motifs, linked_context, linked_interpretations, opening_stems, comparative_prompts, grade_priority, is_core_quote, b_mode_rank, exam_question_tags, recommended_for_questions, question_types, ao_priority, comparison_strength, retrieval_priority, best_used_for, source_row_key, curation_status, is_active, sort_order) VALUES ('qm_at_06', 'Atonement', 'She was not yet old enough to understand that making a new draft would not atone for her mistake.', 'free indirect discourse', '{authorship,childhood,guilt,imagination,education}'::text[], '', '', 'top_band', 'Narrator (third person, close to Briony)', 'Part One', 'McEwan plants the novel''s central irony in Briony''s childhood understanding of writing: that a better draft repairs the damage of a bad one. The novel''s entire structure — a long act of literary atonement — is quietly accused of the same naivety.', '{"writing and authorship","the unreliable narrator"}'::text[], '{"McEwan''s career-long interest in child psychology","Piaget''s stages of moral development","The novel as a form that generates and then questions its own authority"}'::text[], '{"Wood argues this is the novel''s founding paradox stated in miniature: writing cannot undo what writing — and misreading — caused","Kermode reads ''not yet old enough'' as the narrator condemning her younger self with retrospective clarity she still doesn''t fully possess"}'::text[], '{"The gentle irony of ''not yet old enough'' frames Briony''s confusion of revision with atonement as","McEwan plants the novel''s central problem in a child''s misunderstanding: the belief that a better draft","The proleptic irony charges the line: the reader of the whole novel recognises that Briony — older, wiser — makes the same mistake at"}'::text[], '{"Compare how both texts use a character''s relationship to writing or story-telling as a measure of their moral development","Both Briony and Gradgrind believe that applying a system can repair human damage — compare how each text corrects this belief"}'::text[], 'higher', 't'::boolean, '6'::integer, '{"narrative authority",fiction,writing}'::text[], '{"How does McEwan explore the relationship between writing and atonement?"}'::text[], '{theme,method,form}'::text[], '{AO2,AO1}'::text[], 'strong', '6'::integer, '{"AO2 on proleptic irony and free indirect discourse","AO1 on the novel''s metafictional structure"}'::text[], 'qm_at_06', 'strong', 't'::boolean, NULL::integer) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quote_methods (id, source_text, quote_text, method, best_themes, effect_prompt, meaning_prompt, level_tag, speaker_or_narrator, location_reference, plain_english_meaning, linked_motifs, linked_context, linked_interpretations, opening_stems, comparative_prompts, grade_priority, is_core_quote, b_mode_rank, exam_question_tags, recommended_for_questions, question_types, ao_priority, comparison_strength, retrieval_priority, best_used_for, source_row_key, curation_status, is_active, sort_order) VALUES ('qm_at_07', 'Atonement', 'From her high window, Briony watched her sister''s humiliation.', 'free indirect discourse', '{authorship,childhood,imagination}'::text[], '', '', 'top_band', 'Narrator (close to Briony)', 'Part One, Chapter 2', 'Briony''s elevated vantage point at the window gives her visual access to the fountain scene — but the elevation is also moral and imaginative. ''Humiliation'' is Briony''s interpretation, not a fact. Her position above gives her both perspective and dangerous distance from what she sees.', '{"seeing and misseeing","the window","elevation and distance"}'::text[], '{"The Victorian sensation novel''s use of the window (Wilkie Collins)","Panopticism and the politics of observation (Foucault)","McEwan''s use of multiple perspectives across Part One"}'::text[], '{"Finney argues the window is the novel''s governing image: distance that masquerades as clarity","Head reads Briony''s elevated position as McEwan''s spatial metaphor for the novelist''s dangerous god-like overview"}'::text[], '{"Briony''s ''high window'' positions her above the scene — physically and, she believes, morally — creating a","The noun ''humiliation'' is free indirect discourse: it is Briony''s reading, not Cecilia''s experience, exposing","McEwan''s use of spatial elevation to figure narrative authority anticipates the novel''s central argument that"}'::text[], '{"Compare how both texts use spatial positioning — who can see, from where — to figure the dangers of partial perspective","Mrs Sparsit watches from a position of elevation in Hard Times; Briony from a window in Atonement — compare what each author does with this motif"}'::text[], 'higher', 't'::boolean, '7'::integer, '{Briony,perspective,"the window"}'::text[], '{"How does McEwan present Briony?","How does McEwan use perspective?"}'::text[], '{character,method,narrative}'::text[], '{AO2,AO1}'::text[], 'very strong', '7'::integer, '{"AO2 on spatial symbolism and free indirect discourse","AO1 on focalisation as narrative technique"}'::text[], 'qm_at_07', 'strong', 't'::boolean, NULL::integer) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quote_methods (id, source_text, quote_text, method, best_themes, effect_prompt, meaning_prompt, level_tag, speaker_or_narrator, location_reference, plain_english_meaning, linked_motifs, linked_context, linked_interpretations, opening_stems, comparative_prompts, grade_priority, is_core_quote, b_mode_rank, exam_question_tags, recommended_for_questions, question_types, ao_priority, comparison_strength, retrieval_priority, best_used_for, source_row_key, curation_status, is_active, sort_order) VALUES ('qm_at_08', 'Atonement', 'She knew. It was Robbie. With that certainty she could start to calculate what had to be done.', 'free indirect discourse', '{authorship,guilt,imagination,education}'::text[], '', '', 'top_band', 'Narrator (close to Briony)', 'Part One, Chapter 14', 'Briony''s misidentification of Robbie as Lola''s rapist is framed as a logical certainty — ''she knew'' — followed by calculation. McEwan reveals how the mind can dress catastrophic error in the language of rational confidence.', '{"seeing and misseeing",darkness,certainty}'::text[], '{"False memory syndrome and eyewitness unreliability (Loftus, 1979)","1930s English legal system and the weight given to child testimony","McEwan''s research into wrongful conviction cases"}'::text[], '{"Wood argues ''She knew'' is the novel''s most chilling three words — certainty without foundation produces the worst harm","Kermode reads the word ''calculate'' as Briony unconsciously aligning herself with the utilitarian error the novel critiques — substituting system for feeling"}'::text[], '{"The blunt declaration ''She knew'' performs the epistemological crisis at the heart of the novel:","McEwan''s use of the verb ''calculate'' after ''she knew'' reveals that Briony''s moral failure is not impulsive but","The dramatic irony of ''certainty'' — the reader knows Briony is wrong — transforms rational confidence into"}'::text[], '{"Compare how both texts show rational certainty leading to catastrophic error — Gradgrind''s system and Briony''s eyewitness account","Both texts present a moment of false knowledge being acted upon — compare the structural and moral consequences in each"}'::text[], 'higher', 't'::boolean, '8'::integer, '{"false accusation",certainty,Briony}'::text[], '{"How does McEwan present Briony''s false accusation?","How does McEwan explore truth and perception?"}'::text[], '{theme,character,method}'::text[], '{AO2,AO1}'::text[], 'very strong', '8'::integer, '{"AO2 on short declarative sentences and dramatic irony","AO1 on the pivotal moment of the novel"}'::text[], 'qm_at_08', 'strong', 't'::boolean, NULL::integer) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quote_methods (id, source_text, quote_text, method, best_themes, effect_prompt, meaning_prompt, level_tag, speaker_or_narrator, location_reference, plain_english_meaning, linked_motifs, linked_context, linked_interpretations, opening_stems, comparative_prompts, grade_priority, is_core_quote, b_mode_rank, exam_question_tags, recommended_for_questions, question_types, ao_priority, comparison_strength, retrieval_priority, best_used_for, source_row_key, curation_status, is_active, sort_order) VALUES ('qm_at_09', 'Atonement', 'He needed to see her, even for a moment, to know that she was real.', 'free indirect discourse', '{authorship,gender,memory,war}'::text[], '', '', 'top_band', 'Narrator (close to Robbie, Part Two)', 'Part Two — France, 1940', 'In the chaos of the Dunkirk retreat, Robbie''s love for Cecilia persists as a structuring force — she is what makes reality bearable and life worth surviving. Love functions as an epistemological anchor against the dissolution of war.', '{"the letters","the body",survival}'::text[], '{"Dunkirk evacuation (May–June 1940)","Romantic love as a structuring principle under trauma (Hemingway, A Farewell to Arms)","McEwan''s research into WWII soldier memoirs"}'::text[], '{"Head argues Robbie''s sections are McEwan''s most sympathetic — the reader is made to feel the injustice viscerally through his consciousness","Finney reads ''to know that she was real'' as McEwan''s counter to the novel''s postmodernism: love insists on reality when narrative deconstructs it"}'::text[], '{"Robbie''s need to confirm Cecilia''s reality positions love as an ontological necessity under the dissolution of","The simplicity of ''to know that she was real'' sets the novel''s emotional anchor against its postmodern questioning of","McEwan shifts to Robbie''s perspective in Part Two to ensure the reader experiences the injustice as"}'::text[], '{"Compare how love functions as a structuring principle for characters in both texts — what it enables, and what it cannot protect against","Both Robbie and Louisa hold an interior emotional life that the systems around them cannot account for — compare"}'::text[], 'higher', 'f'::boolean, '9'::integer, '{Robbie,war,love}'::text[], '{"How does McEwan present Robbie?","How does McEwan present love and war?"}'::text[], '{character,theme,setting}'::text[], '{AO2,AO3}'::text[], 'moderate', '9'::integer, '{"AO2 on free indirect discourse","AO3 on Dunkirk","comparative essays on love under pressure"}'::text[], 'qm_at_09', 'strong', 't'::boolean, NULL::integer) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quote_methods (id, source_text, quote_text, method, best_themes, effect_prompt, meaning_prompt, level_tag, speaker_or_narrator, location_reference, plain_english_meaning, linked_motifs, linked_context, linked_interpretations, opening_stems, comparative_prompts, grade_priority, is_core_quote, b_mode_rank, exam_question_tags, recommended_for_questions, question_types, ao_priority, comparison_strength, retrieval_priority, best_used_for, source_row_key, curation_status, is_active, sort_order) VALUES ('qm_at_10', 'Atonement', 'There was nothing she could do about it, and they would never meet again.', 'flat declarative statement', '{authorship,guilt,war}'::text[], '', '', 'top_band', 'Briony (aged narrator, Part Four)', 'Part Four (London, 1999)', 'In the epilogue, the aged Briony confirms that the novel''s happy ending — Cecilia and Robbie''s reunion — is fiction. They both died before the end of the war. The line strips away the consolation of the narrative and forces the reader to confront the irreversibility of the original harm.', '{irreversibility,"the gap between fiction and reality"}'::text[], '{"The Blitz and civilian casualties (September 1940 onwards)","McEwan''s structural decision to withhold the truth until the final pages","Tragic irony in the classical tradition"}'::text[], '{"Wood argues this is McEwan''s most devastating narrative decision — the comfort of the reunion is retrospectively destroyed","Kermode reads the flatness of the prose — ''nothing she could do'', ''never meet again'' — as the novel''s most honest register: grief without ornament"}'::text[], '{"The flat certainty of ''they would never meet again'' demolishes the reunion McEwan has just narrated, insisting that","McEwan''s bathos — the devastating content in the plainest possible syntax — performs the absence of consolation:","By confirming Cecilia and Robbie''s deaths only after narrating their reunion, McEwan implicates the reader in Briony''s act of"}'::text[], '{"Compare how both texts handle endings — do Dickens and McEwan permit consolation or withhold it?","Both texts end with a truth that revises everything that precedes it — compare the structural and emotional effect"}'::text[], 'higher', 't'::boolean, '10'::integer, '{ending,truth,irreversibility}'::text[], '{"How does McEwan end the novel?","How does McEwan explore truth and fiction?"}'::text[], '{theme,method,ending}'::text[], '{AO2,AO1}'::text[], 'very strong', '10'::integer, '{"AO2 on flat declarative prose and bathos","AO1 on the novel''s double ending"}'::text[], 'qm_at_10', 'strong', 't'::boolean, NULL::integer) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quote_methods (id, source_text, quote_text, method, best_themes, effect_prompt, meaning_prompt, level_tag, speaker_or_narrator, location_reference, plain_english_meaning, linked_motifs, linked_context, linked_interpretations, opening_stems, comparative_prompts, grade_priority, is_core_quote, b_mode_rank, exam_question_tags, recommended_for_questions, question_types, ao_priority, comparison_strength, retrieval_priority, best_used_for, source_row_key, curation_status, is_active, sort_order) VALUES ('qm_at_11', 'Atonement', 'I gave them happiness, but I was not so self-serving as to let them forgive me.', 'self-correction mid-sentence', '{authorship,guilt,imagination}'::text[], '', '', 'top_band', 'Briony Tallis (aged narrator)', 'Part Four (London, 1999)', 'Briony claims credit for giving Cecilia and Robbie a happy ending in the novel-within-the-novel, but denies herself the comfort of their fictional forgiveness. This is her bid for moral credit — but McEwan leaves open whether it is genuine atonement or one final act of narrative control.', '{"writing and authorship",forgiveness,"the novelist-as-God"}'::text[], '{"Christian discourse of contrition (distinguishing between guilt and absolution)","Postmodern self-consciousness about literary ethics","McEwan''s stated interest in the limits of secular atonement"}'::text[], '{"Finney reads the line as genuinely ambiguous — is refusing forgiveness noble self-denial or a subtler form of self-glorification?","Wood argues ''not so self-serving'' is the most self-serving thing Briony says — the disclaimer is its own form of pride"}'::text[], '{"Briony''s disclaimer — ''I was not so self-serving as to let them forgive me'' — enacts the very self-consciousness it claims to transcend:","The irony that McEwan builds into ''I gave them happiness'' is that the gift is entirely within Briony''s gift — the novelist cannot","By refusing fictional forgiveness while claiming moral credit, Briony occupies a position that is simultaneously"}'::text[], '{"Compare how both texts present the limits of individual atonement — can Gradgrind or Briony genuinely make amends?","Both texts turn on the question of what counts as genuine moral reform versus self-justification — compare"}'::text[], 'higher', 't'::boolean, '11'::integer, '{atonement,self-deception,"narrative authority"}'::text[], '{"How does McEwan present atonement?","How does McEwan present Briony''s moral development?"}'::text[], '{theme,character,method}'::text[], '{AO2,AO1}'::text[], 'very strong', '11'::integer, '{"AO2 on irony and self-correction","AO1 on the limits of narrative atonement"}'::text[], 'qm_at_11', 'strong', 't'::boolean, NULL::integer) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quote_methods (id, source_text, quote_text, method, best_themes, effect_prompt, meaning_prompt, level_tag, speaker_or_narrator, location_reference, plain_english_meaning, linked_motifs, linked_context, linked_interpretations, opening_stems, comparative_prompts, grade_priority, is_core_quote, b_mode_rank, exam_question_tags, recommended_for_questions, question_types, ao_priority, comparison_strength, retrieval_priority, best_used_for, source_row_key, curation_status, is_active, sort_order) VALUES ('qm_at_12', 'Atonement', 'The vase fell and broke with a sound that rang out in the silence like a pistol shot.', 'simile', '{authorship,class,gender,war}'::text[], '', '', 'top_band', 'Narrator (Cecilia''s perspective)', 'Part One, Chapter 3 — the fountain scene', 'The breaking of the Meissen vase at the fountain initiates the chain of events leading to Robbie''s false accusation. The simile of a pistol shot foreshadows war, violence, and the irreversibility of what is about to begin — from a domestic accident, catastrophe follows.', '{"the vase","the fountain","fragility and damage"}'::text[], '{"The Meissen vase as class and colonial inheritance (pre-war upper-class English life)","Chekhov''s gun principle — objects introduced must eventually discharge","Freudian accident as expression of unconscious desire"}'::text[], '{"Head reads the pistol-shot simile as McEwan''s most compressed piece of structural foreshadowing","Finney argues the breaking vase is the novel''s ur-event: the moment when the irreversible begins"}'::text[], '{"The simile of a pistol shot transforms a domestic accident into a portent of","McEwan''s proleptic imagery — the vase breaking ''like a pistol shot'' — charges the fountain scene with","The Meissen vase carries class, history, and desire in a single object — its breaking signals that"}'::text[], '{"Compare how both texts use a single symbolic object or moment to crystallise the novel''s central themes","Both texts feature a pivotal scene that sets catastrophe in motion — compare how Dickens and McEwan construct these turning points"}'::text[], 'higher', 'f'::boolean, '12'::integer, '{"the vase",foreshadowing,"the fountain scene"}'::text[], '{"How does McEwan use symbolism?","How does McEwan structure the novel?"}'::text[], '{method,symbol,structure}'::text[], '{AO2,AO1}'::text[], 'strong', '12'::integer, '{"AO2 on simile and proleptic imagery","AO1 on structural foreshadowing"}'::text[], 'qm_at_12', 'strong', 't'::boolean, NULL::integer) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quote_methods (id, source_text, quote_text, method, best_themes, effect_prompt, meaning_prompt, level_tag, speaker_or_narrator, location_reference, plain_english_meaning, linked_motifs, linked_context, linked_interpretations, opening_stems, comparative_prompts, grade_priority, is_core_quote, b_mode_rank, exam_question_tags, recommended_for_questions, question_types, ao_priority, comparison_strength, retrieval_priority, best_used_for, source_row_key, curation_status, is_active, sort_order) VALUES ('qm_at_13', 'Atonement', 'It was not in her interest to see Robbie clearly.', 'free indirect discourse', '{authorship,class,imagination,education}'::text[], '', '', 'top_band', 'Narrator (Briony''s perspective)', 'Part One', 'McEwan explicitly names Briony''s motivated misreading: she does not want to see Robbie clearly because clarity would disrupt her own narrative. Perception is revealed as interest-driven, not objective — a lesson the novel applies to all narrators.', '{"seeing and misseeing","the unreliable narrator"}'::text[], '{"Psychoanalytic theory of motivated perception (Freud, Lacan)","Class prejudice and the 1930s English class system","McEwan''s interest in the cognitive science of misperception"}'::text[], '{"Wood reads ''not in her interest'' as McEwan''s most direct statement of the novel''s thesis about narrative bias","Kermode argues the line reveals that all perspective is interested — and therefore that all fiction, including McEwan''s, must be read sceptically"}'::text[], '{"McEwan''s blunt formulation — ''not in her interest to see clearly'' — exposes perception as an act of","The phrase ''not in her interest'' introduces an economic logic to vision: Briony sees what it costs her least to","By naming Briony''s motivated misreading so explicitly, McEwan extends the indictment beyond one character to"}'::text[], '{"Compare how both texts present perception as shaped by interest, desire, or ideology rather than neutral observation","Both Mrs Sparsit''s staircase fantasy and Briony''s misreading of Robbie are interest-driven — compare how each author signals this"}'::text[], 'higher', 't'::boolean, '13'::integer, '{perception,Briony,"motivated misreading"}'::text[], '{"How does McEwan present Briony?","How does McEwan explore truth and perception?"}'::text[], '{character,theme,method}'::text[], '{AO2,AO1}'::text[], 'very strong', '13'::integer, '{"AO2 on free indirect discourse and dramatic irony","AO1 on interested perception as the novel''s thesis"}'::text[], 'qm_at_13', 'strong', 't'::boolean, NULL::integer) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quote_methods (id, source_text, quote_text, method, best_themes, effect_prompt, meaning_prompt, level_tag, speaker_or_narrator, location_reference, plain_english_meaning, linked_motifs, linked_context, linked_interpretations, opening_stems, comparative_prompts, grade_priority, is_core_quote, b_mode_rank, exam_question_tags, recommended_for_questions, question_types, ao_priority, comparison_strength, retrieval_priority, best_used_for, source_row_key, curation_status, is_active, sort_order) VALUES ('qm_at_14', 'Atonement', 'Come back. Come back to me.', 'imperative mood', '{authorship,gender,war}'::text[], '', '', 'top_band', 'Cecilia (her letter to Robbie, read in Part Two)', 'Part Two — Robbie reads Cecilia''s letter in France', 'Cecilia''s letter, read by Robbie during the Dunkirk retreat, functions as an emotional lifeline. The repeated imperative is both love letter and survival instruction — the simplest possible language carrying the novel''s most complex emotional stakes.', '{"the letters",survival,"the body"}'::text[], '{"Wartime correspondence and its role in maintaining civilian identity","The love letter as a literary form (Richardson, Clarissa)","Cecilia''s own act of narrative — her letters are her only remaining agency"}'::text[], '{"Head argues the repeated imperative is the most emotionally direct moment in a novel of elaborate indirection","Finney reads Cecilia''s letters as the only unmediated voice in the text — the one perspective Briony cannot appropriate"}'::text[], '{"The repetition of ''Come back'' strips away the novel''s elaborate narrative machinery to reveal","Cecilia''s imperative operates simultaneously as love and survival command — McEwan uses the simplest syntax to","The epistolary form gives Cecilia a direct voice that the novel''s narrative structure otherwise denies her:"}'::text[], '{"Compare how both texts present love as a structuring or sustaining force against systems that destroy it","Both Louisa''s fire imagery and Cecilia''s letters represent suppressed emotional lives that find expression in brief, charged moments"}'::text[], 'higher', 't'::boolean, '14'::integer, '{Cecilia,love,"the letters"}'::text[], '{"How does McEwan present Cecilia?","How does McEwan present love?"}'::text[], '{character,theme,method}'::text[], '{AO2,AO1}'::text[], 'strong', '14'::integer, '{"AO2 on imperative mood and epistolary form","AO1 on Cecilia as unmediated voice"}'::text[], 'qm_at_14', 'strong', 't'::boolean, NULL::integer) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quote_methods (id, source_text, quote_text, method, best_themes, effect_prompt, meaning_prompt, level_tag, speaker_or_narrator, location_reference, plain_english_meaning, linked_motifs, linked_context, linked_interpretations, opening_stems, comparative_prompts, grade_priority, is_core_quote, b_mode_rank, exam_question_tags, recommended_for_questions, question_types, ao_priority, comparison_strength, retrieval_priority, best_used_for, source_row_key, curation_status, is_active, sort_order) VALUES ('qm_at_15', 'Atonement', 'The problem these fifty-nine years has been this: how can a novelist achieve atonement when, with her absolute power of deciding outcomes, she is also God?', 'direct address', '{authorship,endings,guilt}'::text[], '', '', 'top_band', 'Briony Tallis (aged narrator, 1999)', 'Part Four (London, 1999)', 'Briony''s full articulation of the novel''s central paradox, now weighted with the specific duration of her guilt — fifty-nine years since 1940. The novel''s entire length is re-framed as an act of attempted atonement that may be impossible.', '{"writing and authorship","the novelist-as-God",time}'::text[], '{"The gap between 1940 and 1999 — Briony''s entire adult life given to atonement","McEwan''s own age at writing (b. 1948) — the fifty-nine years is also a comment on the novelist''s own career","Postmodern historiographic metafiction"}'::text[], '{"Wood argues the fifty-nine years gives the abstract paradox a human weight that pure theory cannot carry","Kermode reads the specificity of 1999 as McEwan situating the novel''s questions at the end of a century of literary self-consciousness"}'::text[], '{"The temporal precision — ''these fifty-nine years'' — transforms an abstract question about fiction into","McEwan''s retroactive framing of the entire novel as an answer to the question posed in its final pages creates","By placing the central paradox in the final section, McEwan ensures the reader must retrospectively re-evaluate"}'::text[], '{"Both Hard Times and Atonement are structured around a central question — about whether systems or stories can repair damage — compare","Compare how both texts use their closing pages to reconfigure the reader''s understanding of everything that came before"}'::text[], 'higher', 't'::boolean, '15'::integer, '{metafiction,"fifty-nine years","central paradox"}'::text[], '{"How does McEwan structure the novel?","How does McEwan explore narrative authority?"}'::text[], '{form,theme,method}'::text[], '{AO2,AO1}'::text[], 'very strong', '15'::integer, '{"AO2 on temporal specificity and rhetorical question","AO1 on the novel as a whole"}'::text[], 'qm_at_15', 'strong', 't'::boolean, NULL::integer) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quote_methods (id, source_text, quote_text, method, best_themes, effect_prompt, meaning_prompt, level_tag, speaker_or_narrator, location_reference, plain_english_meaning, linked_motifs, linked_context, linked_interpretations, opening_stems, comparative_prompts, grade_priority, is_core_quote, b_mode_rank, exam_question_tags, recommended_for_questions, question_types, ao_priority, comparison_strength, retrieval_priority, best_used_for, source_row_key, curation_status, is_active, sort_order) VALUES ('qm_at_16', 'Atonement', 'Briony had always been a child who could construct a scene with a few telling details.', 'free indirect discourse', '{authorship,childhood,guilt,imagination,education}'::text[], '', '', 'top_band', 'Narrator', 'Part One, Chapter 1', 'McEwan establishes Briony''s gift for story-making as the quality that will make her both an artist and a criminal: the same imaginative faculty that constructs a compelling scene will construct a false accusation.', '{"writing and authorship","the child''s perspective"}'::text[], '{"Dickens''s own childhood imaginative life and its relationship to his fiction","Child development and the theory of mind","McEwan''s engagement with cognitive literary theory"}'::text[], '{"Finney reads ''telling details'' as McEwan''s double irony — the novelist''s craft that is also a weapon","Wood argues the line introduces the novel''s key question: is imaginative gift morally neutral, or does its power carry ethical responsibility?"}'::text[], '{"The double meaning of ''telling'' — to reveal and to narrate — condenses the novel''s central concern:","McEwan introduces Briony''s imaginative gift and its danger simultaneously, suggesting that","The proleptic irony of ''construct a scene'' is devastating: the reader who finishes the novel understands that"}'::text[], '{"Compare how both texts present imagination as simultaneously a gift and a dangerous capacity","Both Briony''s fiction-making and Gradgrind''s fact-system impose a constructed reality onto others — compare the moral consequences"}'::text[], 'higher', 'f'::boolean, '16'::integer, '{Briony,imagination,narrative}'::text[], '{"How does McEwan present Briony''s imagination?"}'::text[], '{character,theme,method}'::text[], '{AO2,AO1}'::text[], 'strong', '16'::integer, '{"AO2 on dramatic irony and prolepsis","AO1 on imagination as gift and danger"}'::text[], 'qm_at_16', 'strong', 't'::boolean, NULL::integer) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quote_methods (id, source_text, quote_text, method, best_themes, effect_prompt, meaning_prompt, level_tag, speaker_or_narrator, location_reference, plain_english_meaning, linked_motifs, linked_context, linked_interpretations, opening_stems, comparative_prompts, grade_priority, is_core_quote, b_mode_rank, exam_question_tags, recommended_for_questions, question_types, ao_priority, comparison_strength, retrieval_priority, best_used_for, source_row_key, curation_status, is_active, sort_order) VALUES ('qm_at_17', 'Atonement', 'She had in mind a more rounded, less deliberate, more childlike approach to the truth.', 'free indirect discourse', '{authorship,childhood,imagination,education}'::text[], '', '', 'top_band', 'Narrator (Briony''s perspective)', 'Part One, Chapter 1', 'Briony reflects on her evolving approach to writing — moving away from the mechanical plotting of her early plays toward something more ''childlike''. McEwan''s irony is that ''childlike'' is precisely what goes wrong: Briony''s childlike certainty will destroy Robbie.', '{"writing and authorship","the child''s perspective"}'::text[], '{"Henry James''s prefaces on the novel''s organic form","McEwan''s own development as a novelist","Romantic valorisation of childhood perception (Blake, Wordsworth)"}'::text[], '{"Kermode reads this passage as McEwan''s most self-aware joke: the ''childlike approach to the truth'' is the approach that most distorts it","Wood argues the irony is structural as well as local — the whole novel is a childlike approach to truth masquerading as mature reflection"}'::text[], '{"McEwan''s irony is most precise here: a ''childlike approach to the truth'' is presented as artistic growth but will prove","The evaluative chain — ''more rounded, less deliberate, more childlike'' — values spontaneity over craft just as Briony''s spontaneous certainty is about to","By framing Briony''s developing aesthetic as aspiration toward the childlike, McEwan implicates the very quality she celebrates as"}'::text[], '{"Compare how both texts interrogate the relationship between imaginative spontaneity and moral harm","Both Briony and Gradgrind believe their approach to truth is superior — compare how each text dismantles this belief"}'::text[], 'higher', 'f'::boolean, '17'::integer, '{narrative,truth,"Briony''s aesthetic"}'::text[], '{"How does McEwan present Briony''s development as a writer?"}'::text[], '{character,method,form}'::text[], '{AO2,AO1}'::text[], 'moderate', '17'::integer, '{"AO2 on evaluative adjectives and proleptic irony","AO1 on the childlike as dangerous aesthetic"}'::text[], 'qm_at_17', 'strong', 't'::boolean, NULL::integer) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quote_methods (id, source_text, quote_text, method, best_themes, effect_prompt, meaning_prompt, level_tag, speaker_or_narrator, location_reference, plain_english_meaning, linked_motifs, linked_context, linked_interpretations, opening_stems, comparative_prompts, grade_priority, is_core_quote, b_mode_rank, exam_question_tags, recommended_for_questions, question_types, ao_priority, comparison_strength, retrieval_priority, best_used_for, source_row_key, curation_status, is_active, sort_order) VALUES ('qm_at_18', 'Atonement', 'Older, harsher experience confirmed what the girl had merely intuited.', 'temporal contrast', '{endings,guilt,imagination,war}'::text[], '', '', 'top_band', 'Narrator (Briony''s perspective, Part Three)', 'Part Three', 'In her wartime nursing, Briony finds that the suffering she witnesses confirms what she had begun to understand about the irreversibility of damage. The gap between ''intuited'' (childlike, instinctive) and ''confirmed'' (proven through suffering) tracks her moral development.', '{"nursing as atonement","the body","knowledge and its cost"}'::text[], '{"Wartime nursing as moral education (Vera Brittain, Testament of Youth)","The distinction between theoretical and experiential knowledge in moral philosophy","McEwan''s research into nursing memoirs"}'::text[], '{"Finney argues Part Three is the moral centre of the novel — where Briony begins to genuinely understand rather than simply feel guilty","Head reads ''confirmed'' as the key word: war removes the luxury of intuition and replaces it with irreversible evidence"}'::text[], '{"The opposition of ''intuited'' and ''confirmed'' tracks Briony''s movement from childlike imagination to","McEwan''s passive construction — ''confirmed what the girl had merely intuited'' — frames moral knowledge as something imposed by","The adjectives ''older, harsher'' position experience as an education that the imagination cannot substitute for:"}'::text[], '{"Compare how both texts present the gap between intuitive and experiential moral knowledge","Both Gradgrind and Briony arrive at moral insight through painful experience rather than reason — compare how each text stages this"}'::text[], 'higher', 'f'::boolean, '18'::integer, '{Briony,nursing,"moral development"}'::text[], '{"How does McEwan present Briony''s atonement?","How does McEwan use Part Three?"}'::text[], '{character,theme,structure}'::text[], '{AO2,AO3}'::text[], 'moderate', '18'::integer, '{"AO2 on passive construction and temporal contrast","AO3 on wartime nursing"}'::text[], 'qm_at_18', 'strong', 't'::boolean, NULL::integer) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quote_methods (id, source_text, quote_text, method, best_themes, effect_prompt, meaning_prompt, level_tag, speaker_or_narrator, location_reference, plain_english_meaning, linked_motifs, linked_context, linked_interpretations, opening_stems, comparative_prompts, grade_priority, is_core_quote, b_mode_rank, exam_question_tags, recommended_for_questions, question_types, ao_priority, comparison_strength, retrieval_priority, best_used_for, source_row_key, curation_status, is_active, sort_order) VALUES ('qm_at_19', 'Atonement', 'She would never be able to undo what she had done and she knew it. Nevertheless, she had to try.', 'adversative conjunction', '{authorship,endings,guilt}'::text[], '', '', 'top_band', 'Narrator (Briony''s perspective, Part Three)', 'Part Three', 'Briony articulates the paradox of atonement that the novel builds toward: she knows repair is impossible, but the impossibility does not release her from the obligation to attempt it. McEwan presents guilt as a permanent ethical condition rather than something that can be resolved.', '{irreversibility,"nursing as atonement"}'::text[], '{"Kantian duty ethics — the obligation to act rightly regardless of outcome","Secular atonement without the Christian mechanism of absolution","McEwan''s career-long interest in moral philosophy (Saturday, The Children Act)"}'::text[], '{"Wood reads the sentence as the novel''s clearest ethical statement: atonement is not a transaction but an ongoing condition","Finney argues ''she had to try'' is the most honest thing Briony says — not claiming success, only necessity"}'::text[], '{"The adversative ''Nevertheless'' carries the novel''s ethical weight: the impossibility of repair does not cancel the","McEwan''s pairing of ''never be able to undo'' with ''she had to try'' frames atonement as a Sisyphean obligation rather than","The two short declarative sentences enact the paradox they describe: certainty of failure followed by certainty of"}'::text[], '{"Compare how both texts treat the relationship between impossibility and moral obligation — does knowing you cannot fix something release you from trying?","Both Gradgrind and Briony face the impossibility of full repair — compare how each text handles this"}'::text[], 'higher', 't'::boolean, '19'::integer, '{atonement,impossibility,obligation}'::text[], '{"How does McEwan present the idea of atonement?","How does McEwan explore guilt?"}'::text[], '{theme,method,form}'::text[], '{AO2,AO1}'::text[], 'very strong', '19'::integer, '{"AO2 on adversative conjunction and paradox","AO1 on atonement as ongoing condition rather than resolution"}'::text[], 'qm_at_19', 'strong', 't'::boolean, NULL::integer) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quote_methods (id, source_text, quote_text, method, best_themes, effect_prompt, meaning_prompt, level_tag, speaker_or_narrator, location_reference, plain_english_meaning, linked_motifs, linked_context, linked_interpretations, opening_stems, comparative_prompts, grade_priority, is_core_quote, b_mode_rank, exam_question_tags, recommended_for_questions, question_types, ao_priority, comparison_strength, retrieval_priority, best_used_for, source_row_key, curation_status, is_active, sort_order) VALUES ('qm_at_20', 'Atonement', 'I like to think that it isn''t weakness or evasion, but a final act of kindness, a stand against oblivion and despair.', 'qualified assertion', '{authorship,guilt,imagination}'::text[], '', '', 'top_band', 'Briony Tallis (aged narrator, Part Four)', 'Part Four (London, 1999)', 'Briony defends her decision to give Cecilia and Robbie a fictional happy ending, framing it as generosity rather than evasion. McEwan makes this defence deeply ambiguous: ''I like to think'' signals uncertainty, and ''stand against oblivion'' sounds more heroic than Briony has earned the right to be.', '{"writing and authorship","the novelist-as-God","oblivion and memory"}'::text[], '{"The novel''s double ending: the fictional reunion and the historical truth","McEwan''s interest in secular consolation and its limits","The tradition of the Victorian consolatory ending (Dickens''s own disputed use of it)"}'::text[], '{"Wood argues ''I like to think'' is McEwan''s most carefully chosen phrase — the modal verb confesses the uncertainty the elevated language obscures","Kermode reads ''stand against oblivion'' as Briony''s most self-aggrandising formulation — she frames her evasion as heroism"}'::text[], '{"The modal ''I like to think'' undermines the confident claim that follows, exposing the gap between","Briony''s elevated framing — ''a stand against oblivion and despair'' — translates a possibly self-serving act into","McEwan''s irony is that the reader is invited to decide whether Briony''s defence is ''weakness or evasion'' — the question she explicitly raises but cannot"}'::text[], '{"Both Hard Times and Atonement end with an act of qualified consolation — compare what each text implies about whether consolation is deserved","Compare how both authors use their endings to leave open rather than resolve the moral questions they have raised"}'::text[], 'higher', 't'::boolean, '20'::integer, '{ending,self-justification,consolation}'::text[], '{"How does McEwan end the novel?","How does McEwan present Briony''s atonement?"}'::text[], '{theme,method,ending}'::text[], '{AO2,AO1}'::text[], 'very strong', '20'::integer, '{"AO2 on modal verb and irony","AO1 on ambiguous consolation","essay conclusions"}'::text[], 'qm_at_20', 'strong', 't'::boolean, NULL::integer) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quote_methods (id, source_text, quote_text, method, best_themes, effect_prompt, meaning_prompt, level_tag, speaker_or_narrator, location_reference, plain_english_meaning, linked_motifs, linked_context, linked_interpretations, opening_stems, comparative_prompts, grade_priority, is_core_quote, b_mode_rank, exam_question_tags, recommended_for_questions, question_types, ao_priority, comparison_strength, retrieval_priority, best_used_for, source_row_key, curation_status, is_active, sort_order) VALUES ('qm_ht_01', 'Hard Times', 'Now, what I want is, Facts.', 'direct speech', '{education,war}'::text[], '', '', 'top_band', 'Gradgrind', 'Book 1, Chapter 1', 'Gradgrind opens the novel by demanding pure factual knowledge, rejecting imagination and feeling entirely.', '{"fact vs fancy",machinery,naming}'::text[], '{"Victorian utilitarianism","Benthamite philosophy",industrialisation}'::text[], '{"Dickens satirises the reduction of human beings to economic units","Gradgrind as embodiment of laissez-faire capitalism"}'::text[], '{"Dickens opens the novel with Gradgrind''s blunt declaration that","The imperative ''want'' positions Gradgrind as a man who","Through the capitalised ''Facts'', Dickens signals that"}'::text[], '{"Compare Gradgrind''s instrumentalism with Briony''s narrative control in Atonement","Both texts open with figures who impose their version of reality — explore"}'::text[], 'higher', 't'::boolean, '1'::integer, '{utilitarianism,education,opening}'::text[], '{"How does Dickens present education?","How does Dickens present power?"}'::text[], '{character,theme,method}'::text[], '{AO2,AO3}'::text[], 'strong', '1'::integer, '{"essay openings","AO3 context on utilitarianism","AO2 on imperative mood"}'::text[], 'qm_ht_01', 'strong', 't'::boolean, NULL::integer) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quote_methods (id, source_text, quote_text, method, best_themes, effect_prompt, meaning_prompt, level_tag, speaker_or_narrator, location_reference, plain_english_meaning, linked_motifs, linked_context, linked_interpretations, opening_stems, comparative_prompts, grade_priority, is_core_quote, b_mode_rank, exam_question_tags, recommended_for_questions, question_types, ao_priority, comparison_strength, retrieval_priority, best_used_for, source_row_key, curation_status, is_active, sort_order) VALUES ('qm_ht_02', 'Hard Times', 'There is a wisdom of the Head, and a wisdom of the Heart.', 'antithesis', '{class,imagination}'::text[], '', '', 'top_band', 'Narrator / Sissy', 'Book 2, Chapter 1', 'Sissy implicitly embodies an emotional intelligence Gradgrind''s system cannot quantify — this line marks the novel''s moral alternative to utilitarianism.', '{"fact vs fancy",circus,"fire imagery"}'::text[], '{Romanticism,"Dickens''s defence of the imagination","Evangelical Christianity"}'::text[], '{"Leavis reads this as Dickens''s moral centre","Dickens privileges feeling over system"}'::text[], '{"The antithesis of ''Head'' and ''Heart'' encapsulates Dickens''s central argument that","Dickens uses capitalisation to elevate emotional wisdom to the same status as","This line functions as a thesis statement for the novel''s critique of"}'::text[], '{"Both Hard Times and Atonement explore the failure of intellectual systems to account for human feeling","Compare how Dickens and McEwan use narrators who misread emotional truth"}'::text[], 'higher', 't'::boolean, '2'::integer, '{imagination,emotion,"moral framework"}'::text[], '{"How does Dickens present the imagination?","How does Dickens create a moral framework?"}'::text[], '{theme,method,character}'::text[], '{AO2,AO1}'::text[], 'strong', '2'::integer, '{"thesis-level claims","AO2 on antithesis","AO3 on Romanticism"}'::text[], 'qm_ht_02', 'strong', 't'::boolean, NULL::integer) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quote_methods (id, source_text, quote_text, method, best_themes, effect_prompt, meaning_prompt, level_tag, speaker_or_narrator, location_reference, plain_english_meaning, linked_motifs, linked_context, linked_interpretations, opening_stems, comparative_prompts, grade_priority, is_core_quote, b_mode_rank, exam_question_tags, recommended_for_questions, question_types, ao_priority, comparison_strength, retrieval_priority, best_used_for, source_row_key, curation_status, is_active, sort_order) VALUES ('qm_ht_03', 'Hard Times', 'Quadruped. Graminivorous. Forty teeth, namely twenty-four grinders, four eye-teeth, and twelve incisive.', 'listing', '{education,imagination,war}'::text[], '', '', 'top_band', 'Bitzer', 'Book 1, Chapter 2', 'Bitzer recites a textbook definition of a horse, demonstrating the product of Gradgrind''s system: factual recall without feeling, imagination, or lived understanding.', '{"fact vs fancy",naming,animals}'::text[], '{"Gradgrind modelled on utilitarian philosopher Jeremy Bentham","Rote-learning in Victorian board schools","Dickens''s critique of the monitorial system"}'::text[], '{"Leavis argues Bitzer is the novel''s most chilling product — systemically emptied of humanity","House reads Bitzer as Gradgrind''s ideological mirror, not his opposite"}'::text[], '{"Bitzer''s clinical enumeration — ''Quadruped. Graminivorous'' — reduces a living creature to","The fragmented syntax of Bitzer''s definition performs the system it describes: knowledge broken into","Dickens juxtaposes Bitzer''s mechanical recitation with Sissy''s silence to show that"}'::text[], '{"Compare how Dickens and McEwan use characters who impose a systematised, reductive framework onto experience","Both Bitzer and Briony mistake a partial view for the whole truth — compare the consequences"}'::text[], 'higher', 't'::boolean, '3'::integer, '{education,utilitarianism,bitzer}'::text[], '{"How does Dickens present the education system?","How does Dickens use characterisation to criticise utilitarianism?"}'::text[], '{character,theme,method}'::text[], '{AO2,AO3}'::text[], 'strong', '3'::integer, '{"AO2 on listing and technical register","AO3 on Bentham","contrast with Sissy"}'::text[], 'qm_ht_03', 'strong', 't'::boolean, NULL::integer) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quote_methods (id, source_text, quote_text, method, best_themes, effect_prompt, meaning_prompt, level_tag, speaker_or_narrator, location_reference, plain_english_meaning, linked_motifs, linked_context, linked_interpretations, opening_stems, comparative_prompts, grade_priority, is_core_quote, b_mode_rank, exam_question_tags, recommended_for_questions, question_types, ao_priority, comparison_strength, retrieval_priority, best_used_for, source_row_key, curation_status, is_active, sort_order) VALUES ('qm_ht_04', 'Hard Times', 'It was a town of red brick, or of brick that would have been red if the smoke and ashes had allowed it.', 'conditional syntax', '{class,imagination,war}'::text[], '', '', 'top_band', 'Narrator', 'Book 1, Chapter 5', 'Dickens''s opening description of Coketown establishes the industrial town as a place where nature and colour have been suffocated by industrial production — even the material of the buildings has been stripped of its natural identity.', '{machinery,"fire and smoke","colour and its absence"}'::text[], '{"Manchester and Preston as models for Coketown","Victorian urban expansion and pollution","Engels''s The Condition of the Working Class in England (1845)"}'::text[], '{"Williams argues Coketown is not a place but a symbol of what capitalism does to human life","Schwarzbach reads the town description as Dickens''s most sustained piece of social indictment"}'::text[], '{"The conditional ''would have been red if'' strips Coketown of natural colour, suggesting that","Dickens''s use of the impersonal narrator in the Coketown description positions the reader as","The smoke and ashes that deny the brick its redness function as a metaphor for"}'::text[], '{"Compare how Dickens and McEwan use setting to externalise psychological or social damage","Both Hard Times and Atonement open with spaces that constrain their inhabitants — compare"}'::text[], 'higher', 't'::boolean, '4'::integer, '{industrialisation,setting,class}'::text[], '{"How does Dickens present Coketown?","How does Dickens use setting?"}'::text[], '{theme,method,setting}'::text[], '{AO2,AO3}'::text[], 'strong', '4'::integer, '{"AO2 on colour and conditional syntax","AO3 on industrial Manchester","comparative setting essays"}'::text[], 'qm_ht_04', 'strong', 't'::boolean, NULL::integer) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quote_methods (id, source_text, quote_text, method, best_themes, effect_prompt, meaning_prompt, level_tag, speaker_or_narrator, location_reference, plain_english_meaning, linked_motifs, linked_context, linked_interpretations, opening_stems, comparative_prompts, grade_priority, is_core_quote, b_mode_rank, exam_question_tags, recommended_for_questions, question_types, ao_priority, comparison_strength, retrieval_priority, best_used_for, source_row_key, curation_status, is_active, sort_order) VALUES ('qm_ht_05', 'Hard Times', 'They were not in a state to bear it. They were tired, they were exhausted, they were sick of all the facts and figures with which they were overloaded.', 'anaphora', '{class,education,war}'::text[], '', '', 'top_band', 'Narrator', 'Book 1, Chapter 5', 'Dickens describes the factory workers'' mental and physical exhaustion, presenting them as victims of the same system of overload that Gradgrind applies to children — facts and figures become instruments of oppression.', '{"the Hands",machinery,exhaustion}'::text[], '{"Ten Hours Act 1847","Factory Reform Movement",Chartism}'::text[], '{"Eagleton reads this passage as Dickens''s most explicitly political — the system designed for profit literally breaks people","Ingham argues the workers'' exhaustion mirrors the children''s in the schoolroom — Dickens collapses the distinction between child and worker"}'::text[], '{"The tripartite anaphora — ''They were tired, they were exhausted, they were sick'' — enacts the","Dickens''s syntax accumulates like the facts it describes, overloading the sentence to perform","By linking the workers'' exhaustion to ''facts and figures'', Dickens extends Gradgrind''s system beyond education into"}'::text[], '{"Both Dickens and McEwan present systems — utilitarian education, narrative control — that damage those subjected to them","Compare how structural repetition is used in both texts to convey oppression or entrapment"}'::text[], 'higher', 'f'::boolean, '5'::integer, '{class,dehumanisation,"the Hands"}'::text[], '{"How does Dickens present the working class?","How does Dickens present dehumanisation?"}'::text[], '{theme,method,class}'::text[], '{AO2,AO3}'::text[], 'moderate', '5'::integer, '{"AO2 on anaphora and tricolon","AO3 on Factory Reform Movement"}'::text[], 'qm_ht_05', 'strong', 't'::boolean, NULL::integer) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quote_methods (id, source_text, quote_text, method, best_themes, effect_prompt, meaning_prompt, level_tag, speaker_or_narrator, location_reference, plain_english_meaning, linked_motifs, linked_context, linked_interpretations, opening_stems, comparative_prompts, grade_priority, is_core_quote, b_mode_rank, exam_question_tags, recommended_for_questions, question_types, ao_priority, comparison_strength, retrieval_priority, best_used_for, source_row_key, curation_status, is_active, sort_order) VALUES ('qm_ht_06', 'Hard Times', 'There seems to be nothing there but languid and monotonous smoke. Yet when the night comes, Fire bursts out.', 'juxtaposition', '{education,gender,imagination}'::text[], '', '', 'top_band', 'Louisa', 'Book 1, Chapter 15', 'Louisa describes the factory chimneys — but she is really describing herself: the suppression of feeling under Gradgrind''s system, and the dangerous emotional intensity that remains beneath. The fire is both literal and psychological.', '{"fire and smoke","fact vs fancy","Louisa''s interiority"}'::text[], '{"Victorian women''s emotional repression","Coventry Patmore''s ''The Angel in the House''","Industrial fire as both creative and destructive force"}'::text[], '{"Bodenheimer argues the fire imagery tracks Louisa''s suppressed desire across the novel","Tambling reads the capital ''F'' in Fire as Dickens marking this as the novel''s psychological centre"}'::text[], '{"Louisa''s description of the chimneys collapses the industrial and psychological — ''Fire bursts out'' suggests","The juxtaposition of ''languid and monotonous smoke'' with the capitalised ''Fire'' enacts the tension between","Dickens uses Louisa''s gaze on the factory as a moment of dramatic irony: what she describes as external is really"}'::text[], '{"Compare how Dickens and McEwan use moments of perception — looking at something — to reveal a character''s psychological interior","Both Louisa and Briony are defined by suppression and eruption — compare how this psychological pattern is rendered"}'::text[], 'higher', 't'::boolean, '6'::integer, '{Louisa,repression,imagery}'::text[], '{"How does Dickens present Louisa?","How does Dickens use imagery?"}'::text[], '{character,theme,method}'::text[], '{AO2,AO1}'::text[], 'very strong', '6'::integer, '{"AO2 on fire symbolism","AO1 on Louisa''s interiority","comparative essays on repression"}'::text[], 'qm_ht_06', 'strong', 't'::boolean, NULL::integer) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quote_methods (id, source_text, quote_text, method, best_themes, effect_prompt, meaning_prompt, level_tag, speaker_or_narrator, location_reference, plain_english_meaning, linked_motifs, linked_context, linked_interpretations, opening_stems, comparative_prompts, grade_priority, is_core_quote, b_mode_rank, exam_question_tags, recommended_for_questions, question_types, ao_priority, comparison_strength, retrieval_priority, best_used_for, source_row_key, curation_status, is_active, sort_order) VALUES ('qm_ht_07', 'Hard Times', 'It''s a muddle. Aw a muddle!', 'dialect', '{class,justice,war}'::text[], '', '', 'top_band', 'Stephen Blackpool', 'Book 2, Chapter 5', 'Stephen''s repeated phrase ''muddle'' becomes his defining verdict on industrial capitalism, class inequality, and the failure of any system — Gradgrind''s utilitarianism included — to account for the complexity of working-class life.', '{"the Hands",machinery,"working-class voice"}'::text[], '{"Dickens''s ambivalence toward trade unionism","Chartist demands for parliamentary reform","Victorian working-class speech and representation"}'::text[], '{"Shaw famously criticised Dickens for giving Stephen no political solution — ''muddle'' is resignation not resistance","Ingham reads ''muddle'' as Dickens''s honest admission that the novel''s own solutions are inadequate"}'::text[], '{"Stephen''s dialectal ''muddle'' is the novel''s most honest verdict on industrialism because it refuses","The repetition of ''Aw a muddle'' strips away any pretence that the novel offers a coherent solution to","Dickens gives Stephen the clearest moral voice in the novel but denies him agency — the dialect marks him as"}'::text[], '{"Both Dickens and McEwan present figures who see clearly but cannot act — compare Stephen and Robbie","Compare how both authors use a character''s characteristic phrase or verbal habit to define their position in the novel''s moral world"}'::text[], 'higher', 't'::boolean, '7'::integer, '{Stephen,"working class","social critique"}'::text[], '{"How does Dickens present the working class?","How does Dickens present social injustice?"}'::text[], '{character,theme,method}'::text[], '{AO2,AO3}'::text[], 'strong', '7'::integer, '{"AO2 on dialect and repetition","AO3 on Chartism","AO1 on Stephen as moral voice"}'::text[], 'qm_ht_07', 'strong', 't'::boolean, NULL::integer) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quote_methods (id, source_text, quote_text, method, best_themes, effect_prompt, meaning_prompt, level_tag, speaker_or_narrator, location_reference, plain_english_meaning, linked_motifs, linked_context, linked_interpretations, opening_stems, comparative_prompts, grade_priority, is_core_quote, b_mode_rank, exam_question_tags, recommended_for_questions, question_types, ao_priority, comparison_strength, retrieval_priority, best_used_for, source_row_key, curation_status, is_active, sort_order) VALUES ('qm_ht_08', 'Hard Times', 'I am Josiah Bounderby of Coketown.', 'repetition', '{class,education,war}'::text[], '', '', 'top_band', 'Bounderby', 'Book 1, Chapter 4', 'Bounderby''s constant self-proclamation — always with full name and location — is Dickens''s satire of the Victorian self-made man myth. The repetition reveals his identity as entirely constructed through rhetoric, not reality.', '{naming,"self-made man myth"}'::text[], '{"Samuel Smiles''s Self-Help (1859)","Victorian mythology of social mobility","Dickens''s critique of laissez-faire capitalism"}'::text[], '{"Collins argues Bounderby is Dickens''s most sustained satirical portrait — a lie that exposes the lie at the heart of Victorian capitalism","Eagleton reads Bounderby as utilitarianism''s ugly id: what Gradgrind''s philosophy produces when stripped of academic pretension"}'::text[], '{"Bounderby''s habitual self-naming — always ''Josiah Bounderby of Coketown'' — performs an identity that is entirely","Dickens uses Bounderby''s repetitive self-proclamation as satire: the louder he asserts his origins, the more","The formula ''I am Josiah Bounderby of Coketown'' functions as a lie Bounderby tells himself because"}'::text[], '{"Compare how Dickens and McEwan present characters who construct false narratives about themselves","Both Bounderby and Briony are self-mythologisers — compare how self-deception causes harm to others in both texts"}'::text[], 'higher', 't'::boolean, '8'::integer, '{Bounderby,class,"self-made man"}'::text[], '{"How does Dickens present class?","How does Dickens present Bounderby?"}'::text[], '{character,theme,satire}'::text[], '{AO2,AO3}'::text[], 'strong', '8'::integer, '{"AO2 on repetition and irony","AO3 on Samuel Smiles and self-help ideology"}'::text[], 'qm_ht_08', 'strong', 't'::boolean, NULL::integer) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quote_methods (id, source_text, quote_text, method, best_themes, effect_prompt, meaning_prompt, level_tag, speaker_or_narrator, location_reference, plain_english_meaning, linked_motifs, linked_context, linked_interpretations, opening_stems, comparative_prompts, grade_priority, is_core_quote, b_mode_rank, exam_question_tags, recommended_for_questions, question_types, ao_priority, comparison_strength, retrieval_priority, best_used_for, source_row_key, curation_status, is_active, sort_order) VALUES ('qm_ht_09', 'Hard Times', 'You have been so careful of me, that I never had a child''s heart. You have trained me so well, that I never dreamed a child''s dream.', 'anaphora', '{childhood,education}'::text[], '', '', 'top_band', 'Louisa', 'Book 3, Chapter 1', 'In her breakdown before her father, Louisa articulates the damage his system has done: by removing imagination and feeling from childhood, Gradgrind has left her unable to navigate adult emotional life.', '{"fact vs fancy","Louisa''s interiority","fire and smoke"}'::text[], '{"Romantic valorisation of childhood imagination (Wordsworth)","Victorian women''s legal and emotional subjugation in marriage","Dickens''s own unhappy childhood"}'::text[], '{"Bodenheimer argues this is the emotional climax of the novel — the system''s human cost fully named","Leavis reads Louisa''s speech as Dickens''s indictment not of a villain but of a well-intentioned philosophical error"}'::text[], '{"The anaphoric ''You have'' places culpability entirely with Gradgrind, framing education as a form of","Louisa''s juxtaposition of ''so careful'' with the damage it caused exposes the central paradox of utilitarian parenting:","The parallel structure — ''never had a child''s heart... never dreamed a child''s dream'' — enacts what it describes: a mind trained to"}'::text[], '{"Compare how both texts present the damage done by those who believe they are acting well","Both Gradgrind and Briony cause harm through a failure of imagination — compare how Dickens and McEwan stage this recognition"}'::text[], 'higher', 't'::boolean, '9'::integer, '{Louisa,education,breakdown}'::text[], '{"How does Dickens present the damage of the education system?","How does Dickens present Louisa?"}'::text[], '{character,theme,method}'::text[], '{AO2,AO1}'::text[], 'very strong', '9'::integer, '{"AO2 on anaphora and parallel structure","AO1 on emotional climax","thesis-level claims"}'::text[], 'qm_ht_09', 'strong', 't'::boolean, NULL::integer) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quote_methods (id, source_text, quote_text, method, best_themes, effect_prompt, meaning_prompt, level_tag, speaker_or_narrator, location_reference, plain_english_meaning, linked_motifs, linked_context, linked_interpretations, opening_stems, comparative_prompts, grade_priority, is_core_quote, b_mode_rank, exam_question_tags, recommended_for_questions, question_types, ao_priority, comparison_strength, retrieval_priority, best_used_for, source_row_key, curation_status, is_active, sort_order) VALUES ('qm_ht_10', 'Hard Times', 'How could you give me life, and take from me all the inappreciable things that raise it from the state of conscious death?', 'rhetorical question', '{education,war}'::text[], '', '', 'top_band', 'Louisa', 'Book 3, Chapter 1', 'Louisa confronts her father with the paradox of a life that is biologically alive but experientially empty — the utilitarian system has produced a ''conscious death'', a person without interiority.', '{"fact vs fancy","Louisa''s interiority"}'::text[], '{"Keats''s negative capability and the Romantic critique of pure reason","Victorian debates on the soul and materialism","Mill''s own crisis of feeling documented in Autobiography (1873)"}'::text[], '{"House reads ''conscious death'' as Dickens''s sharpest formulation of what utilitarianism produces — a person who exists but cannot live","Tambling argues the rhetorical question implicates the reader: we, too, have watched and done nothing"}'::text[], '{"The oxymoron ''conscious death'' is Dickens''s most compressed verdict on the utilitarian project:","Louisa''s rhetorical question — ''How could you give me life'' — demands an answer Gradgrind cannot supply because","The Latinate ''inappreciable'' elevates feeling to the status of a philosophical category, positioning the imagination as"}'::text[], '{"Compare how Dickens and McEwan present a character''s moment of recognition — the point at which the damage done becomes visible","Both texts turn on a scene of accusation and reckoning — compare how each author stages the confrontation between harm done and harm caused"}'::text[], 'higher', 't'::boolean, '10'::integer, '{Louisa,utilitarianism,dehumanisation}'::text[], '{"How does Dickens present the consequences of utilitarianism?","How does Dickens present Louisa''s suffering?"}'::text[], '{theme,method,character}'::text[], '{AO2,AO1}'::text[], 'very strong', '10'::integer, '{"AO2 on oxymoron and rhetorical question","AO1 on thesis-level argument about utilitarianism''s cost"}'::text[], 'qm_ht_10', 'strong', 't'::boolean, NULL::integer) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quote_methods (id, source_text, quote_text, method, best_themes, effect_prompt, meaning_prompt, level_tag, speaker_or_narrator, location_reference, plain_english_meaning, linked_motifs, linked_context, linked_interpretations, opening_stems, comparative_prompts, grade_priority, is_core_quote, b_mode_rank, exam_question_tags, recommended_for_questions, question_types, ao_priority, comparison_strength, retrieval_priority, best_used_for, source_row_key, curation_status, is_active, sort_order) VALUES ('qm_ht_11', 'Hard Times', 'Mrs Sparsit... had formed a curious fancy... of a mighty Staircase, with a dark pit of shame and ruin at the bottom.', 'free indirect discourse', '{class,gender}'::text[], '', '', 'top_band', 'Narrator', 'Book 2, Chapter 10', 'Mrs Sparsit''s mental staircase — down which she imagines Louisa descending toward ruin with Harthouse — reveals her prurient, voyeuristic pleasure in Louisa''s fall. It also exposes the social policing of women by other women.', '{"the staircase","darkness and shame"}'::text[], '{"Victorian ideology of female respectability","Sensation fiction conventions (Wilkie Collins)","Women''s social policing and gossip as a tool of class control"}'::text[], '{"Ingham argues Mrs Sparsit is Dickens''s most satirically precise portrait of class snobbery masquerading as moral concern","Bodenheimer reads the staircase as a projection of Mrs Sparsit''s own frustrated desire"}'::text[], '{"The ''dark pit of shame and ruin'' at the staircase''s base reveals more about Mrs Sparsit than about Louisa:","Dickens''s use of free indirect discourse to render Mrs Sparsit''s fantasy implicates the reader in a","The extended metaphor of the staircase externalises a fantasy of female destruction, exposing how"}'::text[], '{"Compare how Dickens and McEwan use a secondary character''s misreading of a central character to drive the plot toward catastrophe","Both Mrs Sparsit and Briony watch and misinterpret a woman''s desire — compare the narrative and moral consequences"}'::text[], 'higher', 'f'::boolean, '11'::integer, '{"Mrs Sparsit",gender,surveillance}'::text[], '{"How does Dickens present gender?","How does Dickens use irony?"}'::text[], '{character,theme,method}'::text[], '{AO2,AO3}'::text[], 'moderate', '11'::integer, '{"AO2 on extended metaphor","AO3 on Victorian female respectability"}'::text[], 'qm_ht_11', 'strong', 't'::boolean, NULL::integer) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quote_methods (id, source_text, quote_text, method, best_themes, effect_prompt, meaning_prompt, level_tag, speaker_or_narrator, location_reference, plain_english_meaning, linked_motifs, linked_context, linked_interpretations, opening_stems, comparative_prompts, grade_priority, is_core_quote, b_mode_rank, exam_question_tags, recommended_for_questions, question_types, ao_priority, comparison_strength, retrieval_priority, best_used_for, source_row_key, curation_status, is_active, sort_order) VALUES ('qm_ht_12', 'Hard Times', 'I have been bent and broken, but — I hope — into a better shape.', 'metalepsis', '{education,imagination}'::text[], '', '', 'top_band', 'Gradgrind', 'Book 3, Chapter 9', 'In the novel''s conclusion, Gradgrind — chastened by Louisa''s collapse and Tom''s crimes — concedes that suffering has reshaped him. Dickens leaves open whether the system itself can be reformed, or whether only individuals can change.', '{machinery,"fact vs fancy"}'::text[], '{"Victorian faith in individual moral reform over systemic change","Dickens''s political conservatism vs his social radicalism","Christian discourse of suffering and redemption"}'::text[], '{"Ingham argues the ending is deliberately ambiguous — Gradgrind''s conversion is personal, not political, and the system continues","Shaw reads the dash — ''I hope'' — as Dickens''s own uncertainty about whether the novel''s solutions hold"}'::text[], '{"The passive construction ''bent and broken'' removes Gradgrind''s agency — it is experience, not reason, that has reformed him:","The hesitation of the dash before ''I hope'' signals that Dickens cannot commit to a full redemption narrative because","By having Gradgrind adopt the language of feeling — ''hope'', ''better shape'' — Dickens traces the cost of conversion: it requires"}'::text[], '{"Compare how both texts treat the possibility of redemption and whether it is available to those who have caused harm","Both Gradgrind and Briony attempt a form of atonement — compare what each text suggests about whether this is possible"}'::text[], 'higher', 't'::boolean, '12'::integer, '{Gradgrind,redemption,ending}'::text[], '{"How does Dickens present redemption?","How does Dickens end the novel?"}'::text[], '{character,theme,ending}'::text[], '{AO2,AO1}'::text[], 'very strong', '12'::integer, '{"AO2 on passive voice and hesitating dash","AO1 on ambiguous endings","comparative essays on atonement"}'::text[], 'qm_ht_12', 'strong', 't'::boolean, NULL::integer) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quote_methods (id, source_text, quote_text, method, best_themes, effect_prompt, meaning_prompt, level_tag, speaker_or_narrator, location_reference, plain_english_meaning, linked_motifs, linked_context, linked_interpretations, opening_stems, comparative_prompts, grade_priority, is_core_quote, b_mode_rank, exam_question_tags, recommended_for_questions, question_types, ao_priority, comparison_strength, retrieval_priority, best_used_for, source_row_key, curation_status, is_active, sort_order) VALUES ('qm_ht_13', 'Hard Times', 'You don''t know what you''re talking about when you talk about Fancy.', 'dramatic irony', '{childhood,education,imagination}'::text[], '', '', 'top_band', 'Gradgrind', 'Book 1, Chapter 8', 'Gradgrind dismisses imagination as meaningless — but the irony is that his certainty about what Fancy is not demonstrates that he cannot engage with it at all. He polices the boundary between fact and fancy without understanding either.', '{"fact vs fancy",naming}'::text[], '{"Benthamite utilitarianism''s hostility to the arts","Victorian debates on fiction and moral utility","Plato''s Republic and the banishment of the poets"}'::text[], '{"Leavis reads this line as Dickens''s most precise irony: Gradgrind condemns what he cannot name","Eagleton argues the line exposes the epistemological limit of utilitarian reason"}'::text[], '{"The self-defeating logic of Gradgrind''s dismissal — ''you don''t know what you''re talking about'' — applies equally to","Dickens''s dramatic irony is sharpest here: Gradgrind''s certainty about Fancy proves that","The negation ''don''t know'' polices the boundary of knowledge in a way that reveals"}'::text[], '{"Compare how both texts expose the limits of characters who believe their knowledge is complete","Both Gradgrind and Briony speak with certainty about things they fundamentally misunderstand — compare how each author signals this irony"}'::text[], 'higher', 'f'::boolean, '13'::integer, '{"fact vs fancy",education,Gradgrind}'::text[], '{"How does Dickens present fact vs fancy?","How does Dickens use irony?"}'::text[], '{theme,method,irony}'::text[], '{AO2,AO1}'::text[], 'strong', '13'::integer, '{"AO2 on dramatic irony","AO1 on fact/fancy binary as structural device"}'::text[], 'qm_ht_13', 'strong', 't'::boolean, NULL::integer) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quote_methods (id, source_text, quote_text, method, best_themes, effect_prompt, meaning_prompt, level_tag, speaker_or_narrator, location_reference, plain_english_meaning, linked_motifs, linked_context, linked_interpretations, opening_stems, comparative_prompts, grade_priority, is_core_quote, b_mode_rank, exam_question_tags, recommended_for_questions, question_types, ao_priority, comparison_strength, retrieval_priority, best_used_for, source_row_key, curation_status, is_active, sort_order) VALUES ('qm_ht_14', 'Hard Times', 'People mutht be amuthed. They can''t be alwayth a learning, nor yet they can''t be alwayth a working, they must be amuthed.', 'phonetic spelling of dialect/lisp', '{class,education,imagination}'::text[], '', '', 'top_band', 'Sleary', 'Book 3, Chapter 8', 'Sleary — lisp and all — delivers the novel''s moral antidote to Gradgrind in plain terms: humans require pleasure and imagination, not only work and learning. The circus, and its impresario, become the novel''s unlikely moral centre.', '{circus,"fact vs fancy","entertainment and pleasure"}'::text[], '{"Victorian popular entertainment and the music hall","Dickens''s own love of performance and the theatre","Wordsworth''s Prelude on the educative power of pleasure"}'::text[], '{"Leavis makes Sleary''s philosophy the novel''s moral touchstone — a counter-utilitarian humanism expressed in broken speech","House is more sceptical: Sleary''s circus is commercialised pleasure, not pure imagination"}'::text[], '{"Sleary''s lisped declaration — ''People mutht be amuthed'' — enacts what it argues: Dickens embeds warmth and comedy in the very phonetics of","The repetition of ''amuthed'' across the sentence insists on pleasure as a structural human need, not a luxury:","Dickens entrusts the novel''s counter-argument to a circus-master with a lisp, signalling that the imagination does not require"}'::text[], '{"Compare how both Dickens and McEwan present figures who offer moral wisdom outside the novel''s dominant intellectual framework","Both texts create an alternative moral world alongside the dominant one — compare what that world looks like in each"}'::text[], 'higher', 't'::boolean, '14'::integer, '{Sleary,circus,imagination}'::text[], '{"How does Dickens present the imagination?","How does Dickens use the circus?"}'::text[], '{theme,character,method}'::text[], '{AO2,AO3}'::text[], 'strong', '14'::integer, '{"AO2 on phonetic spelling and repetition","AO3 on Victorian popular entertainment","AO1 on the circus as moral counterworld"}'::text[], 'qm_ht_14', 'strong', 't'::boolean, NULL::integer) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quote_methods (id, source_text, quote_text, method, best_themes, effect_prompt, meaning_prompt, level_tag, speaker_or_narrator, location_reference, plain_english_meaning, linked_motifs, linked_context, linked_interpretations, opening_stems, comparative_prompts, grade_priority, is_core_quote, b_mode_rank, exam_question_tags, recommended_for_questions, question_types, ao_priority, comparison_strength, retrieval_priority, best_used_for, source_row_key, curation_status, is_active, sort_order) VALUES ('qm_ht_15', 'Hard Times', 'I have been associated with you so long, and have studied you so well, that I have observed the struggle within you now.', 'epistrophe', '{class,gender,war}'::text[], '', '', 'top_band', 'Harthouse', 'Book 2, Chapter 7', 'Harthouse tells Louisa he has read her inner conflict — deploying the rhetoric of intimacy and insight to manipulate a woman whose emotional education has left her defenceless against sophisticated feeling.', '{"seeing and misreading","Louisa''s interiority"}'::text[], '{"Victorian seduction narratives (Sensation fiction)","Women''s legal absence in marriage — coverture","Dickens''s critique of the idle, consuming class"}'::text[], '{"Ingham reads Harthouse as the novel''s most dangerous product of Gradgrind''s system: a man who has acquired emotional intelligence without moral purpose","Tambling argues Louisa''s vulnerability to Harthouse is the direct consequence of an education that gave her no tools for emotional self-defence"}'::text[], '{"Harthouse''s claim to have ''studied'' Louisa turns observation into predation — the language of knowledge becomes","The epistrophe — ''associated with you so long... studied you so well'' — mimics the rhetoric of love while performing","Dickens''s irony is that Harthouse reads Louisa''s struggle correctly but exploits rather than heals it, showing that"}'::text[], '{"Compare how both texts use a character''s misuse of perception — the ability to read others — as a source of harm","Both Harthouse and Briony weaponise their ability to interpret others — compare how Dickens and McEwan expose this"}'::text[], 'higher', 'f'::boolean, '15'::integer, '{Harthouse,manipulation,Louisa}'::text[], '{"How does Dickens present manipulation?","How does Dickens present gender?"}'::text[], '{character,theme,method}'::text[], '{AO2,AO3}'::text[], 'moderate', '15'::integer, '{"AO2 on epistrophe and predatory language","AO3 on Victorian seduction narratives"}'::text[], 'qm_ht_15', 'strong', 't'::boolean, NULL::integer) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quote_methods (id, source_text, quote_text, method, best_themes, effect_prompt, meaning_prompt, level_tag, speaker_or_narrator, location_reference, plain_english_meaning, linked_motifs, linked_context, linked_interpretations, opening_stems, comparative_prompts, grade_priority, is_core_quote, b_mode_rank, exam_question_tags, recommended_for_questions, question_types, ao_priority, comparison_strength, retrieval_priority, best_used_for, source_row_key, curation_status, is_active, sort_order) VALUES ('qm_ht_16', 'Hard Times', 'Father, I have often thought that life is very short. This is the first time I have thought, that life may be long.', 'parallelism', '{education,gender,war}'::text[], '', '', 'top_band', 'Louisa', 'Book 1, Chapter 15', 'Facing marriage to Bounderby, Louisa expresses a terrifying insight: the prospect of a life without love stretches before her as something long and unbearable, not mercifully short. Her passivity in accepting the marriage reveals how utterly Gradgrind''s system has deprived her of agency.', '{"Louisa''s interiority","time and endurance"}'::text[], '{"Victorian women''s legal position in marriage","Coverture doctrine — women as legal non-persons","Dickens''s own unhappy marriage to Catherine Hogarth"}'::text[], '{"Bodenheimer reads this as Louisa''s most explicit statement of emotional death-in-life","Ingham argues the line''s quietness is its most damning quality — trained passivity makes even protest impossible"}'::text[], '{"Louisa''s reversal — ''life may be long'' — reframes the prospect of marriage as a form of","The parallelism of ''often thought'' and ''first time'' frames the moment as a threshold Louisa cannot uncross:","Dickens''s dramatic irony is devastating here: Gradgrind hears a philosophical observation where the reader hears"}'::text[], '{"Compare how both texts use a female character''s relationship to time — waiting, enduring, hoping — to reveal systemic constraint","Both Louisa and Cecilia face choices made under structural conditions that limit genuine agency — compare"}'::text[], 'higher', 'f'::boolean, '16'::integer, '{Louisa,marriage,time}'::text[], '{"How does Dickens present Louisa''s marriage?","How does Dickens present gender?"}'::text[], '{character,theme,method}'::text[], '{AO2,AO1}'::text[], 'moderate', '16'::integer, '{"AO2 on parallelism and reversal","AO1 on Louisa''s passivity"}'::text[], 'qm_ht_16', 'strong', 't'::boolean, NULL::integer) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quote_methods (id, source_text, quote_text, method, best_themes, effect_prompt, meaning_prompt, level_tag, speaker_or_narrator, location_reference, plain_english_meaning, linked_motifs, linked_context, linked_interpretations, opening_stems, comparative_prompts, grade_priority, is_core_quote, b_mode_rank, exam_question_tags, recommended_for_questions, question_types, ao_priority, comparison_strength, retrieval_priority, best_used_for, source_row_key, curation_status, is_active, sort_order) VALUES ('qm_ht_17', 'Hard Times', 'Girl number twenty unable to define a horse!', 'exclamatory syntax', '{education,imagination,war}'::text[], '', '', 'top_band', 'Gradgrind', 'Book 1, Chapter 2', 'Gradgrind reduces Sissy — a girl who has lived among horses her whole life — to a number, and defines her by her failure to produce a textbook definition. The dehumanising numbering system and the absurdity of the test encapsulate the novel''s central critique.', '{naming,"fact vs fancy",animals}'::text[], '{"Kay-Shuttleworth''s Revised Code and payment-by-results schooling","Monitorial system in Victorian board schools","Dickens''s journalism on education reform"}'::text[], '{"Leavis reads the numbering as Dickens''s most concise image of what the system does: it strips the human name before it strips humanity","House argues the irony is precise — the girl who knows horses best is the one the system marks as ignorant"}'::text[], '{"By reducing Sissy to ''Girl number twenty'', Gradgrind performs the system''s logic before he articulates it:","The exclamatory syntax of ''unable to define a horse'' inverts the real ignorance — it is the system, not Sissy, that","Dickens''s irony is precise: the child with the deepest knowledge of horses is penalised because her knowledge is"}'::text[], '{"Compare how both texts use a moment of false classification — a wrong judgement of someone — to reveal the limitations of the classifying system","Both Gradgrind''s schoolroom and Briony''s act of false witness destroy a person''s identity through a single authoritative judgement"}'::text[], 'higher', 't'::boolean, '17'::integer, '{education,dehumanisation,Sissy}'::text[], '{"How does Dickens present the education system?","How does Dickens present dehumanisation?"}'::text[], '{theme,method,character}'::text[], '{AO2,AO3}'::text[], 'very strong', '17'::integer, '{"AO2 on numbering and exclamatory syntax","AO3 on payment-by-results schooling","essay openings"}'::text[], 'qm_ht_17', 'strong', 't'::boolean, NULL::integer) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quote_methods (id, source_text, quote_text, method, best_themes, effect_prompt, meaning_prompt, level_tag, speaker_or_narrator, location_reference, plain_english_meaning, linked_motifs, linked_context, linked_interpretations, opening_stems, comparative_prompts, grade_priority, is_core_quote, b_mode_rank, exam_question_tags, recommended_for_questions, question_types, ao_priority, comparison_strength, retrieval_priority, best_used_for, source_row_key, curation_status, is_active, sort_order) VALUES ('qm_ht_18', 'Hard Times', 'Let us strike the key-note, Coketown, before pursuing our tune.', 'narratorial intrusion', '{authorship,imagination,war}'::text[], '', '', 'top_band', 'Narrator', 'Book 1, Chapter 5', 'Dickens''s narrator uses an explicit musical metaphor to announce the Coketown description, drawing attention to the novel''s constructed, performative nature. The ''key-note'' signals that everything that follows will be variation on a theme of industrial oppression.', '{"music and performance","Coketown as symbol"}'::text[], '{"Dickens''s background in serial journalism","Victorian debates on the novel''s social function","Dickens as public performer and reader"}'::text[], '{"Tambling argues this is Dickens at his most self-conscious — the narrator as conductor drawing attention to the novel''s own artifice","Williams reads the musical metaphor as Dickens claiming the novelist''s role as social diagnostician"}'::text[], '{"Dickens''s musical metaphor — ''key-note... tune'' — frames the social novel as a composed, deliberate form:","The narrator''s direct address ''Let us'' implicates the reader in the act of","By announcing the Coketown description as a ''key-note'', Dickens signals that place will function not as backdrop but as"}'::text[], '{"Compare how Dickens and McEwan use moments of narratorial self-consciousness to comment on the act of writing fiction","Both texts contain moments where the narrative voice draws attention to itself — compare what this achieves in each"}'::text[], 'higher', 'f'::boolean, '18'::integer, '{"narrative form","Dickens''s method",metafiction}'::text[], '{"How does Dickens use narrative technique?","How does Dickens construct the novel?"}'::text[], '{method,narrative,form}'::text[], '{AO2,AO1}'::text[], 'moderate', '18'::integer, '{"AO2 on narratorial intrusion","AO1 on form and structure"}'::text[], 'qm_ht_18', 'strong', 't'::boolean, NULL::integer) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quote_methods (id, source_text, quote_text, method, best_themes, effect_prompt, meaning_prompt, level_tag, speaker_or_narrator, location_reference, plain_english_meaning, linked_motifs, linked_context, linked_interpretations, opening_stems, comparative_prompts, grade_priority, is_core_quote, b_mode_rank, exam_question_tags, recommended_for_questions, question_types, ao_priority, comparison_strength, retrieval_priority, best_used_for, source_row_key, curation_status, is_active, sort_order) VALUES ('qm_ht_19', 'Hard Times', 'I have been ruthless in the matter of pounds, shillings, and pence — but I can change.', 'financial register', '{class,education,imagination}'::text[], '', '', 'top_band', 'Gradgrind', 'Book 3, Chapter 9', 'Gradgrind acknowledges that his entire system of value has been monetary and rational, and tentatively asserts the possibility of reform. The financial register — pounds, shillings, pence — frames his former self in the language of Bounderby, not of the imagination.', '{"fact vs fancy",machinery}'::text[], '{"Victorian mercantile values and the language of accounting","Gradgrind as a model of individual moral reform over systemic change","Dickens''s political ambivalence about whether capitalism can reform itself"}'::text[], '{"Ingham argues the financial vocabulary of the self-accusation reveals that Gradgrind still thinks in the system''s terms even as he repudiates it","Eagleton reads the line as Dickens''s most honest admission: individual reform is possible; systemic reform is not addressed"}'::text[], '{"The financial register of ''pounds, shillings, and pence'' frames Gradgrind''s self-accusation in the very terms of the system he critiques:","The adversative ''but I can change'' is the novel''s most qualified redemptive claim — the modal ''can'' signals","Dickens gives Gradgrind the vocabulary of the marketplace to confess his failure, suggesting that even repentance remains"}'::text[], '{"Compare how both texts present individual moral reform against the backdrop of a system that continues unchanged","Both Gradgrind and Briony frame their atonement in the limited language available to them — compare what this reveals"}'::text[], 'higher', 'f'::boolean, '19'::integer, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], '', '19'::integer, '{"PLACEHOLDER — replace HT19.json with a corrected quote before import"}'::text[], 'qm_ht_19', 'strong', 't'::boolean, NULL::integer) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quote_methods (id, source_text, quote_text, method, best_themes, effect_prompt, meaning_prompt, level_tag, speaker_or_narrator, location_reference, plain_english_meaning, linked_motifs, linked_context, linked_interpretations, opening_stems, comparative_prompts, grade_priority, is_core_quote, b_mode_rank, exam_question_tags, recommended_for_questions, question_types, ao_priority, comparison_strength, retrieval_priority, best_used_for, source_row_key, curation_status, is_active, sort_order) VALUES ('qm_ht_20', 'Hard Times', 'Dear father, you are tired. You have been so tender to me. You have done so much.', 'tricolon', '{education,family}'::text[], '', '', 'top_band', 'Louisa', 'Book 3, Chapter 9', 'In the novel''s closing movement, Louisa addresses her chastened father with forgiveness and tenderness, suggesting that individuals — if not systems — can reform. But Dickens undercuts this: Louisa''s care for Gradgrind contrasts with the absence of anyone to care for her.', '{"Louisa''s interiority","fact vs fancy"}'::text[], '{"Victorian ideology of filial duty","Dickens''s own complex relationship with his father","Christian discourse of forgiveness"}'::text[], '{"Ingham reads Louisa''s tenderness as ambiguous — generosity or the final expression of trained self-suppression?","Bodenheimer argues the ending is quietly devastating: Louisa''s arc ends in care for her father rather than freedom for herself"}'::text[], '{"Louisa''s simple tricolon — ''you are tired... so tender... so much'' — performs the emotional register the novel has argued for:","The dramatic irony of Louisa comforting her father — when she is the one who has suffered — raises the question of whether","Dickens ends not with Louisa''s liberation but her generosity, suggesting that the system''s damage is"}'::text[], '{"Compare how both texts end — do Dickens and McEwan allow their most damaged characters resolution?","Both Louisa and Briony attempt reconciliation with those who have harmed them — compare what each text implies about the possibility of forgiveness"}'::text[], 'higher', 'f'::boolean, '20'::integer, '{Louisa,ending,forgiveness}'::text[], '{"How does Dickens end the novel?","How does Dickens present Louisa''s development?"}'::text[], '{character,theme,ending}'::text[], '{AO2,AO1}'::text[], 'moderate', '20'::integer, '{"AO2 on tricolon and understatement","AO1 on ambiguous closure","comparative essays on endings"}'::text[], 'qm_ht_20', 'strong', 't'::boolean, NULL::integer) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.comparative_matrix (id, axis, hard_times, atonement, divergence, themes, level_band, is_active, sort_order, ao2, ao3, ao4, thesis, "character", narrative, structure, exam_fit) VALUES ('cm-change-01', 'Changing relationships', 'Gradgrind–Louisa — from authoritarian parent/child to a more remorseful, near-equal relationship', 'Briony–Cecilia — from adored older sister dynamic to permanent estrangement after the accusation', 'Both function to show how ideological systems or false stories can permanently reconfigure family bonds, though one allows partial reconciliation and the other does not', '{authorship,family,guilt}'::text[], 'secure', 't'::boolean, '11'::integer, 'Dickens uses the parental-confrontation set-piece — the Stone Lodge scene in Book Two Chapter 12 where Louisa returns to her father and articulates the cost of his pedagogy ("Father, I have often thought…") — as the structural pivot. The father is rendered through speechless recognition, the daughter through articulate accusation: inversion of their habitual registers. McEwan uses multi-decade structural separation — Briony and Cecilia not meeting in Parts Two or Three; the deferred reunion in Part Three (which Part Four reveals to be fiction); the unanswered letters — to dramatise estrangement as durational rather than scenic.', 'Dickens: Victorian father-daughter relationships within the doctrine of separate spheres (the father as moral authority; the breakdown of that authority as Victorian crisis); the 1857 Matrimonial Causes Act as legal context for Louisa''s later return. McEwan: interwar sister-pair fictions (Virginia Woolf''s The Years); post-Freudian sibling psychology; the WWII separation of families and the post-war reunion narrative (or its impossibility).', 'Both function to show how belief in "facts" or stories can permanently reconfigure family bonds. Dickens uses Gradgrind / Louisa to dramatise partial reconciliation through the parent''s recognition of error — the relationship survives, qualified, into Book the Third. McEwan uses Briony / Cecilia to dramatise irreparable damage through the sister''s refusal to forgive — the relationship is permanently broken in the historical timeline and only fictively repaired in the literary one.', 'Both novels track relationships transformed by the protagonist''s confrontation with their own epistemic error — Gradgrind''s late recognition of what Fact has cost Louisa permits partial reconciliation; Briony''s lifelong recognition of what her story cost Cecilia permits no reconciliation at all. Dickens allows the parent the dignity of belated correction; McEwan denies the perpetrator that dignity, and exposes the fictional offering of it as itself part of the moral problem.', 'Gradgrind''s arc — from "Embodiment of utilitarian rationalism" through "Ideological certainty -> Moral collapse -> Partial reform" (WP2). Briony''s arc — from authorial child through wartime nurse to old writer; her relationship to Cecilia is the moral instrument by which we judge the arc.', 'Dickens uses intrusive narratorial commentary to mark the relational shift — the narrator tells us Gradgrind has changed. McEwan uses Briony''s own retrospective narration to mark the relational shift — Briony tells us she has tried to repair, and the reader judges whether the trying is enough.', 'The Gradgrind / Louisa arc occupies the "Reaping" and "Garnering" books — the relational change tracks the structural movement from consequence to recognition. The Briony / Cecilia arc is the novel''s structural premise — the relationship''s break in Part One and its non-repair across Parts Two through Four is what produces the novel as an act of reparation that cannot succeed.', '2019 Q2 (Changing relationships) — direct fit, Pair 1. Also: 2017 Q1 (Difficult circumstances — Louisa and Briony''s parallel inner damage); 2020 Q1 (Role models — Gradgrind as belated model; Briony as compromised model); 2023 Q1 (Important choices — Gradgrind''s choice to reform; Briony''s choice to write).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.comparative_matrix (id, axis, hard_times, atonement, divergence, themes, level_band, is_active, sort_order, ao2, ao3, ao4, thesis, "character", narrative, structure, exam_fit) VALUES ('cm-change-02', 'Changing relationships', 'Louisa–Bounderby — marriage moves from social arrangement to moral collapse and separation', 'Cecilia''s detachment from her Tallis family following the false accusation', 'Both function as relationships that break under the strain of social hypocrisy and moral betrayal', '{authorship,class,family,gender}'::text[], 'secure', 't'::boolean, '12'::integer, 'Dickens uses the proposal scene (Book One Chapter 15 — "What do you recommend, father?") and the marriage''s structural unravelling through Mrs Sparsit''s surveillance staircase (Book Two Chapter 10 — the literalised metaphor of moral fall) to mark the marriage''s collapse as both private feeling and public ideology failing simultaneously. McEwan uses Cecilia''s letters from London (epistolary fragments rather than scenes), her physical distance from the Tallis house, and the deferred reunion with Robbie as the medium by which her separation from family is enacted — distance and silence as the methods of estrangement.', 'Dickens: Victorian marriage as economic and class contract; the doctrine of coverture (a married woman''s legal absorption into her husband); the public-private distinction policed by figures like Mrs Sparsit. McEwan: interwar nursing as one of the few class-permitted exits for upper-middle-class women; wartime separation as historical solvent of family bonds; the post-Cambridge generational migration to London.', 'Both function as relationships that break under the strain of social and moral hypocrisy. Dickens uses Louisa''s marriage to Bounderby to dramatise the rupture of a relationship that was never anything but a class transaction; McEwan uses Cecilia''s withdrawal from the Tallis family to dramatise the rupture of a relationship whose hypocrisy was concealed under domestic ritual until Briony''s testimony made it visible.', 'Both novels track relationships that collapse because the social structures sustaining them are themselves morally bankrupt — Louisa''s marriage cannot survive once she recognises Bounderby''s self-fashioning as fraud; Cecilia''s family cannot survive once she recognises that the Tallises'' protection of Marshall is the same class instinct that produced Robbie''s conviction. In both cases the breakdown is the recognition of structural hypocrisy, not the failure of individual feeling.', 'Louisa as "victim of repression" whose marriage exposes utilitarianism''s human cost. Cecilia as the Tallis daughter who breaks with the family — the structural counterpart to Briony who remains entangled in it. The two sisters'' opposite movements (Cecilia outward, Briony inward) are themselves a comparative structure within the novel.', 'Dickens narrates Louisa''s marriage through omniscience that withholds her interiority strategically — we see what others see (Mrs Sparsit''s surveillance) and only enter Louisa''s interior at the breaking-point. McEwan narrates Cecilia''s separation through her absence — she is not focalised through after Part One except indirectly via Robbie and Briony, so the relationship''s change is registered through what we are not shown.', 'Louisa''s marriage occupies Book Two (the "Reaping" of Book One''s pedagogical sowing); its collapse is the structural midpoint of the novel. Cecilia''s separation from the Tallis family is structurally enacted through her absence from Parts Two and Three — her physical absence from the narrative space is the formal sign of relational change.', '2019 Q2 (Changing relationships) — direct fit, Pair 2. Also: 2020 Q2 (Love — Louisa''s loveless marriage; Cecilia''s thwarted love); 2022 Q1 (Marriage — Louisa-Bounderby as central case; Cecilia-Robbie as unrealised parallel); 2024 Q1 (Relationships between female characters — Cecilia and Briony as the broken sister-pair).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.comparative_matrix (id, axis, hard_times, atonement, divergence, themes, level_band, is_active, sort_order, ao2, ao3, ao4, thesis, "character", narrative, structure, exam_fit) VALUES ('cm-child-01', 'Roles of children', 'Gradgrind children and classroom children — show the damage of fact-based education on feeling and imagination', 'Briony, the twins and Lola — show how children misread or are harmed by adult worlds they cannot fully interpret', 'Both function as lenses through which to judge adult ideologies — utilitarianism for Dickens; class and sexual violence for McEwan', '{childhood,class,education}'::text[], 'secure', 't'::boolean, '27'::integer, 'Dickens uses the classroom scene, numbering, definition-drills, and grotesque educational dialogue to turn children into evidence of an adult system''s violence: "girl number twenty" and Bitzer''s factual horse-definition show childhood stripped of personality and wonder. McEwan uses child focalisation, misrecognition, and withheld adult knowledge to show how children both misread and are harmed by adult worlds; Briony''s genre-trained certainty, the twins'' vulnerability, and Lola''s victimisation all expose the danger of partial understanding.', 'Dickens: Victorian education reform, utilitarian pedagogy, debates over rote learning, and the industrial desire to produce disciplined, useful subjects. McEwan: inter-war childhood within upper-middle-class households, the cultural authority of children''s literature and melodrama, assumptions about innocence, and the failures of adults and institutions to protect children from sexual and social violence.', 'Both function as lenses through which to judge adult ideologies — utilitarianism for Dickens; class and sexual violence for McEwan. Dickens uses children to show the damage caused when adults impose Fact as a complete moral system. McEwan uses children to show how adult secrecy, class power, and literary simplification produce disastrous misreadings and unprotected vulnerability.', 'Both novels use children less as sentimental innocents than as diagnostic instruments. In Hard Times, children reveal what utilitarian adults want society to become; in Atonement, children reveal what adult society refuses to acknowledge clearly. Dickens condemns a system that deforms children; McEwan condemns a world in which children''s limited perception can be weaponised by adult power.', 'Louisa and Tom are the long-term products of Gradgrind''s childhood regime; Sissy and Bitzer operate as contrasting outcomes of humane imagination and factual reduction. Briony is both child and future narrator, making childhood perception morally consequential. Lola and the twins expose the vulnerability of children inside a household more concerned with class appearance than clear protection.', 'Dickens''s narrator stands outside the classroom and satirises its absurdity, guiding the reader to reject the adult ideology imposed on children. McEwan moves closer to child consciousness, making Briony''s mistake psychologically plausible before judging it retrospectively. Dickens exposes adult error from above; McEwan lets the reader inhabit the mechanism of error before condemning its effects.', 'The classroom opening plants the educational premise from which the rest of Hard Times grows: damaged children become damaged adults. Atonement places childhood misreading at the structural origin of the whole plot: Part One''s child perspective determines Part Two''s punishment and Part Four''s lifelong reckoning. Both novels make childhood the beginning of consequence.', '2023 Q2 (Roles of children) — direct fit, Pair 1. Also: 2018 Q2 (Education — formal and informal formation); 2023 Q1 (Important choices — Briony''s accusation and Gradgrind''s schooling); 2017 Q1 (Difficult circumstances — children shaped by hostile environments); 2018 Q1 (Criticising society — adult systems judged through children).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.comparative_matrix (id, axis, hard_times, atonement, divergence, themes, level_band, is_active, sort_order, ao2, ao3, ao4, thesis, "character", narrative, structure, exam_fit) VALUES ('cm-child-02', 'Roles of children', 'Sissy Jupe as child then young woman — development shaped by circus warmth and imaginative nurture', 'Briony across all ages — development shaped by literary ambition, guilt and belated self-knowledge', 'Both function as figures whose development exposes the long-term effects of childhood environment and the stories through which the self is formed', '{childhood,endings,guilt,imagination}'::text[], 'secure', 't'::boolean, '28'::integer, 'Dickens presents Sissy''s development through continuity of warmth, affective language, and symbolic contrast: even when she enters Stone Lodge, her circus formation remains an alternative grammar of care. McEwan presents Briony across ages through structural time-shifts, retrospective narration, and metafictional self-revision; the child who misreads becomes the adult who writes, but the writing never fully escapes the original damage. Both writers make development a test of whether childhood formation can be transformed.', 'Dickens: Victorian beliefs in moral nurture, the ideal of feminine compassion, and the contrast between domestic/circus community and mechanised schooling. McEwan: twentieth-century developmental psychology, the modernist interest in consciousness and memory, wartime moral education, and late-century scepticism about autobiographical confession as sufficient atonement.', 'Both function as figures whose development exposes the long-term effects of childhood environment and the stories through which the self is formed. Dickens uses Sissy to show that humane childhood nurture can preserve moral clarity. McEwan uses Briony to show that childhood fantasy can harden into lifelong guilt, and that adult self-knowledge may arrive too late to repair the lives affected.', 'Both novels ask what childhood makes possible in later life. Sissy''s childhood, though materially insecure, equips her with the sympathy Gradgrind''s system lacks; Briony''s privileged childhood equips her with imaginative confidence before moral understanding. Dickens imagines development as the preservation of goodness; McEwan imagines it as a lifetime of compromised revision.', 'Sissy moves from abandoned circus child to moral centre without losing the values of her first community, making her development a stabilising arc. Briony moves from precocious child-author to nurse and elderly novelist, but each stage is haunted by the first. Sissy is formed by care and gives care; Briony is formed by story and must confront story''s damage.', 'Dickens''s narrator consistently endorses Sissy, so her development is presented as reliable moral growth. McEwan makes Briony''s development narratively unstable because the older Briony controls the account of the younger Briony; growth is inseparable from self-narration, selection, and possible self-defence.', 'Sissy''s development is structurally continuous: she enters early, remains present, and helps enable the novel''s partial moral repair. Briony''s development is structurally staged across 1935, wartime nursing, and 1999; each temporal layer revises the last. Dickens structures childhood as lasting moral resource; McEwan structures it as lasting moral wound.', '2023 Q2 (Roles of children) — direct fit, Pair 2. Also: 2021 Q1 (Hope — Sissy''s optimism and Briony''s attempted repair); 2020 Q1 (Role models — Sissy and older Briony); 2018 Q2 (Education — alternative formation and later re-education); 2023 Q1 (Important choices — child formation leading to adult action).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.comparative_matrix (id, axis, hard_times, atonement, divergence, themes, level_band, is_active, sort_order, ao2, ao3, ao4, thesis, "character", narrative, structure, exam_fit) VALUES ('cm-choice-01', 'Important choices', 'Gradgrind choosing to raise his children on Facts; Louisa consenting to marry Bounderby under ideological pressure', 'Briony choosing to accuse Robbie; then choosing to nurse and eventually to write Atonement', 'Both function as choices that set entire plots and lives on their course, illustrating how personal decisions intersect with ideology and historical context', '{authorship,childhood,education,guilt}'::text[], 'secure', 't'::boolean, '25'::integer, 'Dickens presents important choices through structural causality and repeated abstract diction: Gradgrind''s choice to raise children on Fact becomes the "Sowing" from which Louisa''s later consent to Bounderby is reaped. Louisa''s choice is written as depleted agency, marked by passivity and emotional blankness. McEwan presents Briony''s choices through focalisation, genre-misreading, and metafiction: the accusation is shaped by a child''s narrative certainty, while nursing and authorship are later attempts to choose responsibility after irreversible harm.', 'Dickens: utilitarian pedagogy, patriarchal authority, Victorian marriage economics, and the moral logic of the social-problem novel, where private choices reveal public ideology. McEwan: 1930s class/gender assumptions, child witness testimony, wartime nursing as disciplined service, and late-twentieth-century ethical fiction concerned with responsibility, memory, and the insufficiency of confession.', 'Both function as choices that set entire plots and lives on their course, illustrating how personal decisions intersect with ideology and historical context. Dickens makes Gradgrind''s educational choice and Louisa''s coerced marital consent the originating errors of domestic collapse. McEwan makes Briony''s accusation the central destructive choice, then complicates it through later choices to nurse and to write.', 'Both novels resist the idea that important choices are purely individual. Gradgrind and Louisa choose inside an ideology that has already narrowed feeling into calculation; Briony chooses inside a classed and literary imagination that has already trained her to mistake narrative pattern for truth. The tragedy in both is that choices are personal enough to incur guilt but social enough to expose a system.', 'Gradgrind is the chooser who mistakes doctrine for parental care; Louisa is the child of that choice, so her consent to Bounderby is both decision and symptom. Briony is the child-author whose first catastrophic choice becomes the origin of her adult identity. Older Briony, unlike Louisa, turns later life into an extended attempt to choose acknowledgement, though the novel questions its adequacy.', 'Dickens uses narrator-led moral sequencing to make choices legible as cause and effect; the tripartite structure itself judges the original decisions. McEwan uses retrospective narration to make choice unstable: Briony''s adult narrative re-enters the scene of childhood decision, but can never fully separate memory, guilt, and self-exculpating artistry.', 'Hard Times is built around consequences: educational Sowing, marital and emotional Reaping, then partial Garnering. Atonement is built around one decisive misrecognition, followed by decades of attempted reparation. Dickens distributes choice across system and family; McEwan concentrates choice in Briony''s accusation and then expands its aftermath across the whole novel.', '2023 Q1 (Important choices) — direct fit, Pair 1. Also: 2018 Q2 (Education — Gradgrind''s educational choice and Briony''s literary formation); 2022 Q1 (Marriage — Louisa''s consent); 2017 Q1 (Difficult circumstances — choices under ideological pressure); 2021 Q1 (Hope — later choices toward reparation).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.comparative_matrix (id, axis, hard_times, atonement, divergence, themes, level_band, is_active, sort_order, ao2, ao3, ao4, thesis, "character", narrative, structure, exam_fit) VALUES ('cm-choice-02', 'Important choices', 'Stephen leaving Coketown and walking the railway to seek justice — integrity over survival', 'Robbie returning to war after prison — choosing duty and dignity over safety', 'Both function as costly but principled choices that place moral integrity above personal safety', '{class,justice,morality}'::text[], 'secure', 't'::boolean, '26'::integer, 'Dickens presents Stephen''s choice to leave Coketown through movement imagery, pathos, and fatal irony: the railway walk appears to offer a route towards justice but leads him towards the landscape in which he will be lost and misread. McEwan presents Robbie''s return to war through fragmented memory, bodily exhaustion, and disciplined forward movement during the Dunkirk retreat; his choice to serve after prison carries dignity but no real freedom. Both writers make principled movement structurally tragic.', 'Dickens: working-class precarity, industrial suspicion, and the narrow routes available to a worker seeking justice against employers and social gossip. McEwan: wartime service after penal release, the British Expeditionary Force''s retreat to Dunkirk, class mobility interrupted by national crisis, and the soldier''s duty narrative complicated by personal injustice.', 'Both function as costly but principled choices that place moral integrity above personal safety. Stephen leaves Coketown because staying would mean remaining trapped in false accusation and industrial hostility. Robbie returns to military duty because survival, service, and the hope of Cecilia become the only remaining forms of dignity after wrongful conviction.', 'Both texts show that morally serious choices do not guarantee morally just outcomes. Stephen and Robbie choose movement, duty, and integrity, yet each is destroyed by the conditions through which he moves. Dickens makes the road out of Coketown an ironic path to death; McEwan makes the road to Dunkirk a historical corridor in which private hope is almost extinguished.', 'Stephen''s choice confirms his integrity and isolation: he will not lie, submit, or retaliate, but he also lacks the protection that would make integrity survivable. Robbie''s choice confirms his disciplined intelligence and emotional loyalty: he carries Cecilia''s love as a future to move towards. Both men are morally active even when structurally powerless.', 'Dickens''s narration surrounds Stephen''s choice with sympathy and ominous irony, allowing the reader to feel the injustice before society corrects its judgement too late. McEwan''s narration embeds Robbie''s choice within embodied wartime focalisation, so that memory and physical suffering merge. The reader experiences choice as endurance under historical pressure.', 'Stephen''s departure becomes the hinge between accusation and fatal discovery at the Old Hell Shaft. Robbie''s return to war structures Part Two as a movement towards evacuation, memory, and death, though Part Four later reveals the full extent of that denial. In both, the plot turns a principled choice into a terminal journey.', '2023 Q1 (Important choices) — direct fit, Pair 2. Also: 2017 Q1 (Difficult circumstances — constrained choices under pressure); 2018 Q1 (Criticising society — institutions that punish integrity); 2019 Q2 (Independence — moral/professional self-direction); 2021 Q1 (Hope — movement sustained by future belief).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.comparative_matrix (id, axis, hard_times, atonement, divergence, themes, level_band, is_active, sort_order, ao2, ao3, ao4, thesis, "character", narrative, structure, exam_fit) VALUES ('cm-conflict-01', 'Conflict', 'Workers vs masters — Stephen vs Bounderby, the union conflict; individual decency against systemic power', 'Robbie vs the Tallis family and class system following the false accusation', 'Both function as individual-versus-system conflicts that reveal structural injustice operating under the guise of order', '{class,justice,morality}'::text[], 'secure', 't'::boolean, '19'::integer, 'Dickens dramatises conflict through public confrontation, dialect contrast, and institutional setting: Stephen''s plain, restrained idiom is set against Bounderby''s bombastic self-mythologising, while the union meeting turns collective grievance into coercive crowd pressure. McEwan dramatises Robbie''s conflict with the Tallis family through focalised misreading, evidential objects, and legal silence: the letter, the fountain, the library scene, and Briony''s testimony are structurally converted into a case against him. In both texts, conflict is not merely interpersonal but produced through narrative framing and social language.', 'Dickens: mid-Victorian industrial relations, anxieties about trade unionism, factory capitalism, and the doctrine of self-help that Bounderby parodies. The novel reflects the difficulty of representing working-class grievance without turning either masters or unions into simple heroes. McEwan: 1930s class deference, the authority granted to upper-middle-class testimony, inter-war assumptions about sexuality and servant-class masculinity, and the pre-war legal culture that can absorb prejudice as evidence.', 'Both function as individual-versus-system conflicts that reveal structural injustice operating under the guise of order. Dickens uses Stephen''s conflict with Bounderby and the union to expose a worker trapped between capitalist power and collective rigidity. McEwan uses Robbie''s conflict with the Tallis household and class system to show how social order can manufacture guilt before law has properly judged it.', 'Both novels present conflict as the moment when a supposedly orderly society exposes its coercive machinery: Stephen is crushed because neither employer nor union can recognise moral individuality, while Robbie is destroyed because the Tallis world reads class difference as criminality. The comparison is sharp because Dickens makes conflict socially visible, whereas McEwan makes it epistemological — a battle over what others think they have seen.', 'Stephen functions as the morally isolated worker whose decency has no institutional protection; Bounderby functions as the capitalist voice that turns conflict into evidence of working-class ingratitude. Robbie functions as the vulnerable outsider-insider — educated enough to cross class boundaries but dependent enough to be punished for doing so. Briony and the Tallises become agents of system conflict because their class assumptions convert misreading into accusation.', 'Dickens uses omniscient narration and satirical naming to make the conflict legible as social critique; the reader is positioned to see the unfairness even when characters misrecognise it. McEwan uses restricted focalisation and delayed revelation so that conflict emerges through corrupted perception; the reader experiences the danger of partial knowledge before the full injustice is confirmed.', 'Stephen''s conflict develops through the industrial plot: refusal, exclusion, departure from Coketown, and fatal return through the Old Hell Shaft. Robbie''s conflict is structurally triggered in Part One, punished between Parts One and Two, and reprocessed through memory, war, and Briony''s late confession. Dickens structures conflict as social entrapment; McEwan structures it as an accusation whose consequences radiate across the whole novel.', 'Conflict — direct fit, Pair 1. Also: 2017 Q1 (Difficult circumstances — Stephen and Robbie as system-crushed men); 2018 Q1 (Criticising aspects of society — employer/class/legal power); 2023 Q1 (Important choices — Stephen''s refusal and Briony''s accusation); 2024 Q2 (Relationships between female characters — Briony''s testimony as conflict catalyst).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.comparative_matrix (id, axis, hard_times, atonement, divergence, themes, level_band, is_active, sort_order, ao2, ao3, ao4, thesis, "character", narrative, structure, exam_fit) VALUES ('cm-conflict-02', 'Conflict', 'Imagination vs "Facts" — Sissy vs Gradgrind''s philosophy; the battle for how to know the world', 'Art / story vs truth — Briony''s writing vs historical reality; can fiction restore what it helped destroy?', 'Both function as ideological conflicts about how human beings should know and represent the world, and what authority narrative holds over truth', '{authorship,education,imagination}'::text[], 'top_band', 't'::boolean, '20'::integer, 'Dickens stages the conflict between imagination and Fact through antithetical imagery, caricatured pedagogical dialogue, and symbolic spaces: the square, hard geometry of Gradgrind''s school is set against the colour and movement of Sleary''s circus. McEwan stages the conflict between art and truth through metafiction, multiple focalisations, and recursive acts of narration: Briony''s play-writing, genre expectations, and final authorship expose how fiction can both distort and attempt repair. In both texts, method makes the conflict formal as well as thematic.', 'Dickens: Victorian utilitarian education, industrial rationalism, the reaction against Benthamite measurement, and the social-purpose novel''s defence of imaginative sympathy. McEwan: late-twentieth-century metafiction, postmodern scepticism about narrative authority, modernist inheritance through Woolf-like focalisation, and post-war ethical anxiety about whether art can represent suffering without falsifying it.', 'Both function as ideological conflicts about how human beings should know and represent the world, and what authority narrative holds over truth. Dickens opposes Gradgrindian Fact with Sissy''s imaginative sympathy, finally privileging moral imagination. McEwan complicates the equivalent opposition because Briony''s imagination first falsifies truth and later tries to repair it through art.', 'Both texts turn conflict into a contest between systems of knowledge: Dickens attacks a culture that knows by measurement and therefore fails to understand feeling, while McEwan attacks a literary imagination that knows by pattern and therefore risks imposing false coherence on reality. Dickens largely vindicates imagination; McEwan both needs and indicts it.', 'Sissy embodies humane imagination without intellectual vanity, while Gradgrind embodies fact-based abstraction until his late collapse. Briony embodies the more dangerous version of imagination: her creative intelligence is powerful enough to invent motives before she understands people. Older Briony becomes the conflicted figure who tries to turn the same faculty that caused harm into a belated ethical instrument.', 'Dickens''s narrator argues openly against Fact through satire, repetition, and moral commentary, teaching the reader how to judge Gradgrind''s philosophy. McEwan''s narration withholds that security: the novel allows Briony''s story-making to seem artistically persuasive before disclosing its ethical cost. The narrative contrast is therefore didactic certainty against metafictional instability.', 'Hard Times is structured as the consequence of a false philosophy — Sowing, Reaping, Garnering — so the conflict moves from educational premise to moral harvest. Atonement is structured as the consequence of a false story — Part One''s misreading, Part Two''s historical punishment, Part Three''s attempted reparation, and Part Four''s exposure. In both, the opening method of knowing determines the ending.', 'Conflict — direct fit, Pair 2. Also: 2018 Q2 (Education — dangerous formation and corrective education); 2021 Q1 (Hope — imagination as possible repair); 2023 Q2 (Roles of children — child perception and adult damage); 2019 Q1 (Settings — school/circus and Tallis house as ideological spaces).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.comparative_matrix (id, axis, hard_times, atonement, divergence, themes, level_band, is_active, sort_order, ao2, ao3, ao4, thesis, "character", narrative, structure, exam_fit) VALUES ('cm-diff-01', 'Difficult circumstances', 'Stephen Blackpool — working-class man crushed by industrial conditions and an inescapable marriage; embodies structural hardship of Victorian industry', 'Robbie Turner — working-class man crushed by class prejudice, wrongful conviction and war; embodies structural hardship of 20th-century Britain', 'Both function as morally decent individuals destroyed by large modern systems, exposing how "difficult circumstances" are socially manufactured rather than self-inflicted', '{class,justice,morality,war}'::text[], 'secure', 't'::boolean, '1'::integer, 'Dickens uses dialect marking ("muddle") and the tripartite biblical structure (Sowing / Reaping / Garnering) to position Stephen outside the discourse able to redeem him — his suffering is structurally enacted as moral harvest. McEwan uses delayed focalisation and the rewritten letter as legal evidence to make Robbie''s exclusion epistemic before it becomes physical — Robbie is convicted in narrative summary, never in scene.', 'Dickens: 1840s factory-reform debates (Carlyle''s "Mammonism" in Past and Present, 1843); the figure of the "hand" as industrial synecdoche; Victorian didactic literature and social-reform tradition. McEwan: pre-1948 absence of appellate protection for wrongful conviction; the Dunkirk myth''s class-blind heroism contradicted by Robbie''s transit as criminal-soldier; post-WWII disillusionment with British class settlement.', 'Both function as morally decent individuals destroyed by large modern systems, exposing how far "difficult circumstances" are socially manufactured rather than self-inflicted. Dickens externalises the system as visible industrial architecture; McEwan internalises it as the inherited reflex of class perception that decides a man''s fate before he can speak.', 'Both Dickens and McEwan present systemic injustice as more lethal than any individual antagonist, but Dickens externalises the system as visible architecture (factory, schoolroom, marriage law) while McEwan internalises it as the inherited reflex of class perception.', 'Stephen and Robbie function as moral-witness figures — present in the narrative without authoring it — whose decency exposes the system that destroys them. Both are characterised through silence under interrogation (Stephen at Bounderby''s inquiry; Robbie before the tribunal). Stephen = "virtue crushed by systemic injustice"; Robbie = innocence destroyed by false perception.', 'Dickens grants Stephen direct dialect speech but withholds narrative authority — Stephen is described, never narrates; the omniscient narrator retains moral control. McEwan grants Robbie focalised consciousness in Part Two but withholds the power to revise the verdict on him — Briony retains authorship, making narrative authority itself part of the critique.', 'Stephen''s death closes the industrial-tragedy plot of Book the Third, fulfilling the "Reaping" logic — Dickens permits qualified moral closure through structural completion. Robbie''s death is structurally withheld until the 1999 coda, where it retroactively exposes the earlier reunion as fiction — McEwan denies catharsis by exposing the means of closure as authored.', '2017 Q1 (Difficult circumstances) — direct fit, Pair 1. Also: 2018 Q1 (Criticising society — Stephen and Robbie both indict the systems that destroy them); 2021 Q2 (Conflict — individual vs system); 2023 Q1 (Important choices — Stephen leaving Coketown, Robbie enlisting).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.comparative_matrix (id, axis, hard_times, atonement, divergence, themes, level_band, is_active, sort_order, ao2, ao3, ao4, thesis, "character", narrative, structure, exam_fit) VALUES ('cm-diff-02', 'Difficult circumstances', 'Louisa Gradgrind — emotionally stunted by utilitarian upbringing and loveless marriage; her crisis shows the psychological cost of a fact-driven system', 'Briony Tallis (older) — psychologically burdened by her adolescent crime; her lifelong guilt shows the cost of imaginative power used irresponsibly', 'Both function as figures whose inner suffering reveals the long-term damage done by their social or intellectual environments', '{childhood,education,guilt,morality}'::text[], 'secure', 't'::boolean, '2'::integer, 'Dickens uses the recurrent figure of fire (Louisa as "a fire with nothing to burn") and free indirect discourse to render the cost of repression — interior life made audible through Dickensian narratorial intrusion. McEwan uses retrospective narration and the metafictional rhetorical question ("How can a novelist achieve atonement when, with her absolute power of deciding outcomes, she is also God?") to dramatise authorship-as-guilt.', 'Dickens: Victorian utilitarian pedagogy (Bentham, James Mill); the doctrine of separate spheres which renders Louisa''s interior life socially inaudible; Victorian didactic-reform tradition. McEwan: post-Freudian psychological realism; trauma studies (latency of traumatic knowledge); postmodern uncertainty about narrative reparation; the Bloomsbury inheritance of authorial moral confidence.', 'Both function as figures whose inner suffering reveals the long-term damage done by their social and intellectual environments. Dickens shows damage produced by the absence of imagination; McEwan shows damage produced by its excess. The two novels in dialogue produce one of the sharpest ideological oppositions on the syllabus.', 'Both texts diagnose damage produced by formative environments, but Dickens locates the damage in what was withheld from the child while McEwan locates it in what was exercised by the child — fancy as moral oxygen denied (Louisa), fancy as moral authority misused (Briony).', 'Louisa and Briony are both characters whose inner damage exceeds the events shown to cause it. Both arrive at moral self-knowledge too late for repair — Louisa at her father''s hearth (Book Three), Briony at the 1999 coda — and both writers use that lateness to suggest knowledge without redress is the form moral seriousness actually takes.', 'Dickens uses third-person omniscience with intrusive moral commentary, so Louisa is judged for us — narration as didactic instrument. McEwan uses Briony''s own retrospective consciousness, so Briony judges herself — and asks us whether we should accept her judgement. Dickens uses narration to teach; McEwan uses narration to undermine certainty.', 'Louisa''s crisis arrives at the structural midpoint of Book the Second ("Reaping") where ideological cause becomes psychological consequence — Dickens''s "Problem -> Consequence -> Recognition -> Partial Redemption" cycle. Briony''s crisis is the structure — the entire novel is her retrospective act of reparation, with Part Four revealing the reparation has been the novel itself.', '2017 Q1 (Difficult circumstances) — direct fit, Pair 2. Also: 2019 Q2 (Changing relationships — Gradgrind/Louisa; Briony/Cecilia); 2020 Q1 (Role models — Sissy as alternative; older Briony as problematic role model trying to correct earlier errors); 2023 Q2 (Roles of children — Louisa and Briony as damaged children whose development exposes long-term effects of childhood environment).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.comparative_matrix (id, axis, hard_times, atonement, divergence, themes, level_band, is_active, sort_order, ao2, ao3, ao4, thesis, "character", narrative, structure, exam_fit) VALUES ('cm-edu-01', 'Education (formal / informal)', 'Gradgrind''s school — formal, fact-based education that represses imagination and empathy, producing moral hollowness', 'Briony''s childhood reading and play-writing — informal literary education that feeds a dangerously simplistic view of motive and genre', 'Both function as dangerous forms of education that produce misreadings of human behaviour — Louisa''s emotional confusion; Briony''s false accusation', '{childhood,education,imagination}'::text[], 'secure', 't'::boolean, '7'::integer, 'Dickens uses the classroom scene in Book One Chapter 2 — the catechism format ("Bitzer; your definition of a horse") and the depersonalisation of children into "girl number twenty" / "quadruped. Graminivorous" — to render formal education as ideological violence. McEwan uses Briony''s juvenile play-text The Trials of Arabella as the source-document of her ideology — the play is its own AO2 evidence, with its melodramatic genre conventions and moral certainty mapping directly onto her later misreading of the fountain scene and the letter.', 'Dickens: Victorian utilitarian pedagogy (Bentham''s Chrestomathia, 1816; James Mill on infant education); the 1862 Revised Code''s "payment by results" debate; the working-class school as factory-prep. McEwan: interwar literary reading culture (Briony''s nursery library — Henty, melodrama, fairy tale); the question of genre as moral training; the Bloomsbury and Modernist inheritance of fiction-as-moral-instrument.', 'Both function as dangerous forms of education that produce misreadings of human behaviour. Dickens uses Gradgrind''s school to show how the absence of imagination produces emotional disability — Louisa cannot interpret her own feelings because her education denied her the genre conventions to do so. McEwan uses Briony''s reading to show how the excess of imagination produces moral disability — Briony cannot interpret what she sees because her education gave her too many genre conventions, and she selects the wrong one.', 'Both Dickens and McEwan present education as the principal mechanism by which children misread the world they enter, but Dickens locates the damage in the rationalist suppression of imaginative resources while McEwan locates it in the literary over-supply of imaginative resources — both producing protagonists who cannot read their own situations.', 'Gradgrind''s children (Tom, Louisa, and the unnamed classroom child who cannot define a horse) are products of Gradgrind''s pedagogy. Briony is the product of her own self-education through reading — the writer-as-child. Tom shows that "intellect without morality becomes manipulation"; Briony''s parallel is imagination without ethical training becoming accusation.', 'Dickens uses the schoolroom set-piece scene as didactic exemplum — the narrator''s intrusion ("Thus, and much more, Bitzer") makes the lesson explicit. McEwan uses Briony''s juvenile prose as embedded evidence — the play-text is presented as itself, the narrator does not gloss it, the reader is made to do the interpretive work Briony herself fails to do.', 'Gradgrind''s pedagogy is foundational to Book One ("Sowing") — Books Two and Three then exhibit its consequences. Briony''s reading is foundational to Part One — Parts Two through Four then exhibit its consequences. Structurally homologous: ideological foundation -> epistemic damage -> late recognition.', '2018 Q2 (Education — formal / informal) — direct fit, Pair 1. Also: 2017 Q1 (Difficult circumstances — Louisa''s education as the source of her hardship); 2023 Q1 (Important choices — Gradgrind''s choice to raise children on Facts; Briony''s choice to interpret the fountain scene through her play-text''s conventions).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.comparative_matrix (id, axis, hard_times, atonement, divergence, themes, level_band, is_active, sort_order, ao2, ao3, ao4, thesis, "character", narrative, structure, exam_fit) VALUES ('cm-edu-02', 'Education (formal / informal)', 'Sissy''s alternative education through circus life and family — imagination, compassion, and emotional literacy', 'Briony''s wartime nursing — harsh practical education in suffering and responsibility that corrects earlier distortions', 'Both function as counter-educations that move characters towards moral insight by supplying what earlier formation denied', '{education,imagination,morality}'::text[], 'secure', 't'::boolean, '8'::integer, 'Dickens uses Sissy''s circus inheritance — her father''s failure to define a horse, her loyalty to a father who has abandoned her, the "Nine Oils" — to dramatise an alternative pedagogy of attachment and imagination against Gradgrind''s catechism. McEwan uses the nursing chapters'' practical apprenticeship (Briony learning hospital corners, learning the names of equipment, learning to clean a man''s wound) to show education through bodily labour rather than through reading.', 'Dickens: the circus as anti-utilitarian community (Astley''s Amphitheatre as Dickens''s real-world referent; working-class entertainment culture); the "Condition of England" debate about whether feeling can correct fact. McEwan: wartime nursing as moral re-education (Vera Brittain; the matron tradition); the post-Cambridge "university of life" trope; the question of whether bodily labour can constitute reparation for intellectual sin.', 'Both function as counter-educations that correct earlier distortions and move characters towards moral insight. Dickens uses Sissy''s circus inheritance to embody the alternative pedagogy that Gradgrindian Fact suppressed; McEwan uses Briony''s wartime nursing to enact the harsher counter-education of practical responsibility. In both cases the counter-education is bodily, social, and resistant to text — the opposite of what the protagonist''s first education trained them to value.', 'Both texts present a second, harder education that arrives to correct the damage of the first — but Dickens stages this through Sissy''s stable presence as alternative model from Book One onwards, while McEwan stages it through Briony''s hard apprenticeship in suffering only after her crime has become irrevocable.', 'Sissy is the "alternative educational / human model" who "succeeds precisely because she resists Gradgrind ideology". Older Briony''s wartime self is a corrective version of younger Briony — the same character explicitly re-educated; the only A-Level prose character whose moral arc is the novel''s structural premise.', 'Dickens uses third-person omniscience to validate Sissy''s pedagogy explicitly — the narrator endorses her. McEwan uses Briony''s own retrospective narration to enact the re-education — the reader watches Briony judge her younger self, so the corrective education is performed by the narrative voice itself.', 'Sissy is structurally present throughout — Book One introduces her, Book the Third completes her function as moral witness at Louisa''s recovery. Briony''s nursing occupies the bulk of Part Three (the longest single phase of practical re-education in either novel); Part Four reveals that Part Three was itself a literary act, complicating whether the counter-education succeeded or was merely written.', '2018 Q2 (Education) — direct fit, Pair 2. Also: 2020 Q1 (Role models — Sissy as alternative model; older Briony as corrective self); 2023 Q1 (Important choices — Briony''s choice to nurse, to write Atonement).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.comparative_matrix (id, axis, hard_times, atonement, divergence, themes, level_band, is_active, sort_order, ao2, ao3, ao4, thesis, "character", narrative, structure, exam_fit) VALUES ('cm-female-01', 'Relationships between female characters', 'Louisa–Sissy — mixture of rivalry, gratitude and rescue; one woman''s imagination alters another''s fate', 'Briony–Cecilia — love, envy, then irreparable fracture; one woman''s imagination destroys another''s life', 'Both function as sister-like relationships where one woman''s perspective and imaginative power profoundly alters another''s fate', '{family,gender,guilt,imagination}'::text[], 'secure', 't'::boolean, '29'::integer, 'Dickens presents Louisa and Sissy through contrastive characterisation, fire imagery, and emotional dialogue: Sissy''s warmth exposes Louisa''s repression, while their gradual intimacy turns female relationship into moral education. McEwan presents Briony and Cecilia through focalised misunderstanding, sibling distance, and retrospective guilt: Briony''s perception of Cecilia is charged by envy, fascination, and genre-misreading, and the sisterly bond becomes permanently fractured by the accusation. Both writers make female perception transformative, but in opposite directions.', 'Dickens: Victorian ideology of female moral influence, domestic femininity, and the possibility that women''s emotional labour might repair damage caused by masculine systems. McEwan: 1930s upper-middle-class sisterhood, female sexuality policed by family/class expectation, and late-twentieth-century feminist interest in how women''s voices can be silenced, misread, or mediated by another woman''s narrative.', 'Both function as sister-like relationships where one woman''s perspective and imaginative power profoundly alters another''s fate. Dickens uses Sissy''s perception and care to help Louisa recover from the emotional damage of Fact. McEwan uses Briony''s perception and imagination to destroy Cecilia''s future with Robbie, then to reconstruct that future fictionally without being able to restore it.', 'Both novels present relationships between female characters as routes through which imagination enters another woman''s life. Sissy''s imaginative sympathy rescues Louisa from emotional starvation; Briony''s imaginative certainty ruins Cecilia by converting adult desire into melodramatic threat. Dickens makes female influence redemptive; McEwan makes it both destructive and belatedly reparative.', 'Louisa is initially emotionally closed, while Sissy embodies the affective vocabulary Louisa has been denied. Their relationship turns difference into rescue. Cecilia is independent, desiring, and socially lucid; Briony is imaginative but immature, reading Cecilia''s adulthood through childish plot categories. The female relationship in Atonement is therefore not merely familial but epistemological: one sister fails to know the other.', 'Dickens''s omniscient narrator validates Sissy''s influence and frames Louisa''s response as moral awakening. McEwan filters Cecilia through Briony''s misreading and later through Briony''s authorial reconstruction, so the female relationship is always mediated by the very consciousness that damaged it. Narrative control becomes part of the ethical problem.', 'Louisa and Sissy''s relationship grows across the novel, moving from contrast to dependence and helping enable Book Three''s limited repair. Briony and Cecilia''s relationship moves from childhood admiration and adolescent tension to permanent rupture after Part One; Part Three appears to offer confrontation, while Part Four reveals that even this was authored. Dickens develops repair; McEwan exposes irreparability.', '2024 Q1 (Relationships between female characters) — direct fit, Pair 1. Also: 2017 Q2 (Friendship — Sissy/Louisa and female bonds); 2019 Q2 (Changing relationships — repair versus estrangement); 2023 Q2 (Roles of children — Briony''s child perspective affecting Cecilia); 2021 Q1 (Hope — repair imagined or denied).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.comparative_matrix (id, axis, hard_times, atonement, divergence, themes, level_band, is_active, sort_order, ao2, ao3, ao4, thesis, "character", narrative, structure, exam_fit) VALUES ('cm-female-02', 'Relationships between female characters', 'Mrs Sparsit vs Louisa — older woman surveilling and judging younger; class-driven spite masquerading as moral authority', 'Emily Tallis vs Cecilia / Briony — distant mother failing to intervene; class snobbery enabling injustice', 'Both function as female relationships shaped by class and generational power, showing women upholding or failing to challenge patriarchal structures', '{class,family,gender}'::text[], 'top_band', 't'::boolean, '30'::integer, 'Dickens presents Mrs Sparsit and Louisa through surveillance imagery, grotesque comedy, and the staircase fantasy: the older woman''s apparently genteel concern becomes voyeuristic judgement, exposing class resentment disguised as morality. McEwan presents Emily Tallis''s relationships with Cecilia and Briony through distant focalisation, bodily withdrawal, and domestic inertia: her migraines, bedroom perspective, and reliance on class instinct make maternal authority passive but damaging. Both writers use older women to show how female power can reproduce social control.', 'Dickens: Victorian class hierarchy, fallen gentility, conduct-book morality, and the role of older women as guardians of respectability within patriarchal households. McEwan: upper-middle-class inter-war domestic structures, maternal distance in large houses staffed by servants, class snobbery, and gendered silence around sexuality and violence. Both contexts show women operating inside systems they did not create but may help preserve.', 'Both function as female relationships shaped by class and generational power, showing women upholding or failing to challenge patriarchal structures. Dickens uses Mrs Sparsit''s surveillance of Louisa to satirise moral policing and class spite. McEwan uses Emily Tallis''s failure to intervene clearly with Cecilia, Briony, and Lola to expose maternal absence and class prejudice as enabling conditions of injustice.', 'Both novels complicate any simple view of female solidarity. Mrs Sparsit and Emily Tallis show that women may become enforcers, spectators, or negligent custodians of the very structures that harm younger women. Dickens makes this dynamic satirically visible through Sparsit''s active surveillance; McEwan makes it morally chilling through Emily''s passivity and class-shaped assumptions.', 'Mrs Sparsit is a displaced gentlewoman whose relationship with Louisa is driven by envy, class resentment, and appetite for scandal; Louisa becomes the younger woman she wishes to see fall. Emily Tallis is not malicious in the same theatrical sense, but her maternal detachment and snobbery leave Cecilia misunderstood and Briony unchecked. Both older women fail the younger women under their gaze.', 'Dickens uses comic-satirical narration to expose Mrs Sparsit''s inner melodrama, turning her judgement of Louisa into self-incriminating spectacle. McEwan uses limited access to Emily''s bodily and domestic consciousness to show how passivity can be ethically active: not seeing, not asking, and not challenging become narrative forms of complicity.', 'Mrs Sparsit''s relationship with Louisa intensifies through Book Two and peaks in the imagined staircase descent, helping dramatise the public misreading of Louisa''s private crisis. Emily Tallis''s failure is structurally earlier and quieter: her absence from decisive moral action in Part One allows the accusation to consolidate. Dickens makes surveillance an episode; McEwan makes absence a condition.', '2024 Q1 (Relationships between female characters) — direct fit, Pair 2. Also: 2018 Q1 (Criticising aspects of society — class and respectability policed by women); 2020 Q2 (Love — Louisa''s marriage and Cecilia''s relationship judged by others); 2019 Q2 (Changing relationships — family breakdown and social surveillance); 2023 Q2 (Roles of children — adult female failure around Briony/Lola).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.comparative_matrix (id, axis, hard_times, atonement, divergence, themes, level_band, is_active, sort_order, ao2, ao3, ao4, thesis, "character", narrative, structure, exam_fit) VALUES ('cm-friend-01', 'Friendship', 'Sissy–Louisa — Sissy''s warmth and imagination support Louisa, challenging Gradgrind''s system from within', 'Nurse friendships / Briony with other nurses — shared wartime labour and trauma offer Briony a new moral perspective', 'Both function as female friendships that provide an alternative ethical vision to their societies'' dominant values', '{class,gender,morality}'::text[], 'secure', 't'::boolean, '3'::integer, 'Dickens uses proxemic juxtaposition (Sissy as displaced child / Louisa as repressed daughter in the same Stone Lodge interiors) and lexical contrast ("warm" / "fanciful" against "fact" / "figures") to dramatise Sissy as moral correction within the household she has been imported into. McEwan uses paratactic prose rhythm in the Part Three nursing chapters — short clauses tracking practical tasks — and shared physical labour as the medium of friendship; speech is minimal because action is sufficient.', 'Dickens: Victorian doctrine of female "moral influence" (Sarah Stickney Ellis, The Women of England, 1839); the Gaskell-Eliot tradition of working-class female friendship as moral instrument; circus community as alternative to Coketown labour discipline. McEwan: post-1939 women''s wartime workforce; the matron-trainee dynamic as class-levelling institution; Vera Brittain''s Testament of Youth as inter-war antecedent.', 'Both function as female friendships that provide an alternative ethical vision to their societies'' dominant values. Dickens uses Sissy''s compassion to challenge Gradgrindian Fact from within the household; McEwan uses the nurses'' shared labour to give Briony access, in the narrative present, to a moral framework that the Tallis class formation never offered her.', 'Both novels position female friendship as the locus of an alternative ethical vision to the dominant values of their respective societies — Dickens stages Sissy''s warmth as moral correction within the Gradgrind household; McEwan stages the nurses'' shared labour as Briony''s only access, in the present, to a form of community her class formation never provided.', 'Sissy and the nurses function as morally restorative communities — characters whose value lies in their effect on others rather than in personal narrative arcs. Sissy is the "alternative educational/human model" who "succeeds precisely because she resists Gradgrind ideology"; the senior nurses operate as professional, disciplined models shaping Briony''s wartime ethics.', 'Dickens grants Sissy the narrator''s explicit moral approval through intrusion — the omniscient narrator endorses her against the Gradgrind system. McEwan filters the nurses through Briony''s retrospective focalisation, so the friendships are visible to us only through Briony''s later guilt about whether they constituted genuine reparation. Same function, opposite narrative epistemology.', 'Sissy''s friendship structurally bookends Louisa''s collapse — present at Stone Lodge in Book One, present at the recovery in Book the Third. The nurse friendships are compressed into Part Three, then exposed by Part Four''s metafictional reveal as written under conditions different from those depicted — making the friendship itself part of the moral problem the novel sets out.', '2017 Q2 (Friendship) — direct fit, Pair 1. Also: 2020 Q1 (Role models — Sissy / senior nurses as alternative models); 2024 Q1 (Relationships between female characters — Louisa-Sissy named explicitly in the MATRIX entry).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.comparative_matrix (id, axis, hard_times, atonement, divergence, themes, level_band, is_active, sort_order, ao2, ao3, ao4, thesis, "character", narrative, structure, exam_fit) VALUES ('cm-friend-02', 'Friendship', 'Stephen–Rachael — tender, restrained friendship and love that offers moral support amid industrial misery', 'Robbie''s friendships with fellow soldiers — comradeship provides dignity and shared endurance during the Dunkirk retreat', 'Both function as solidarity relationships that humanise suffering men within hostile, dehumanising environments', '{class,morality,war}'::text[], 'secure', 't'::boolean, '4'::integer, 'Dickens uses conditional grammar and elliptical syntax around Stephen and Rachael ("If I had but knowed...") to render restraint as a linguistic condition — the unsayable produces the moral weight. McEwan uses military-procedural lexis around Robbie''s BEF retreat and breathless parataxis through the Bray Dunes chapters; as Robbie''s septicaemia advances, focalisation becomes delirious — the prose rhythm itself enacts comradeship dissolving into hallucination.', 'Dickens: Victorian marriage law — the 1857 Matrimonial Causes Act post-dated Hard Times by three years, making Stephen''s legal impossibility historically exact; Wesleyan ethic of emotional fidelity. McEwan: WWII Dunkirk retreat (May-June 1940); soldier-fraternity narratives (Frederic Manning''s Her Privates We, Keith Douglas''s Alamein to Zem Zem — texts McEwan researched); the BEF''s class composition as the levelling condition of comradeship.', 'Both function as solidarity relationships that humanise suffering men within hostile environments. In Dickens this solidarity is constrained by Victorian marriage law; in McEwan by wartime emergency. In both, the relationship outlasts the speech that would make it explicit.', 'Both writers position friendship as solidarity that humanises suffering men within hostile environments, but Dickens locates the hostility in Victorian marriage law and industrial discipline while McEwan locates it in wartime emergency and class prejudice — and in both, the friendship is sustained by what cannot be said.', 'Rachael and the soldier-companions function as moral co-witnesses to the protagonist''s destruction. Both are present at deaths the protagonist cannot prevent — Rachael at Stephen''s collapse in the Old Hell Shaft; Mace and Nettle structurally adjacent to Robbie''s death at Bray Dunes. Stephen as "moral conscience of the novel"; the soldier-friendships authenticate Robbie''s parallel function in Atonement.', 'Dickens narrates Stephen and Rachael''s scenes through restrained free indirect — the narrator withholds intrusion as the characters withhold speech. McEwan narrates Robbie''s soldier scenes through delirious focalisation as the septicaemia advances — the prose rhythm itself shows the soldiers'' presence dissolving into hallucination.', 'Rachael''s structural function is to outlive Stephen and inherit moral memory of him — the final book gives her his moral inheritance. The soldier-friendships'' structural function is to be the last consciousness Robbie holds before death — Bray Dunes as the threshold scene that authenticates his destruction.', '2017 Q2 (Friendship) — direct fit, Pair 2. Also: 2020 Q2 (Love — Stephen/Rachael as restrained, ethical love); 2021 Q2 (Conflict — friendships sustained under conflict); 2022 Q1 (Marriage — Stephen''s existing marriage as the legal constraint on his bond with Rachael).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.comparative_matrix (id, axis, hard_times, atonement, divergence, themes, level_band, is_active, sort_order, ao2, ao3, ao4, thesis, "character", narrative, structure, exam_fit) VALUES ('cm-hope-01', 'Hope', 'Sissy''s persistent optimism in Gradgrind''s family — imagination as a thread of possibility within the utilitarian system', 'Robbie and Cecilia''s planned reunion and love letters from prison — fragile future projected against historical darkness', 'Both function as fragile threads of hope that resist overwhelming social or historical darkness', '{endings,imagination,morality}'::text[], 'secure', 't'::boolean, '17'::integer, 'Dickens uses Sissy''s optimistic dialogue (her conviction that Louisa will be repaired in time) and the recurrent fire imagery transferred from Louisa to Sissy as the carrier of imagined future — methods of characterisation through tonal contrast against the prevailing satirical voice. McEwan uses the wartime letters (Part Two) as documents of future-orientation — Robbie''s repeated invocation of the cottage, Cecilia''s "Come back. Come back to me" — and the Part Three reunion scene''s tentative realism, before Part Four exposes the entire reunion as fiction.', 'Dickens: Victorian faith in moral reform (Carlyle''s "natural supernaturalism"; the social-purpose novel''s commitment to amelioration); the doctrine of grace and the redemptive ending. McEwan: post-WWII disillusionment with optimistic narrative resolution (Adorno; the Holocaust''s effect on the consolatory power of fiction); the wartime letter as historical document (the published correspondence of WWII soldiers); the metafictional novel''s interrogation of consolation.', 'Both function as fragile threads of hope that resist overwhelming social and historical darkness. Dickens uses Sissy''s persistent optimism about the Gradgrind family — her belief in repair even after damage — as the hope sustained against utilitarian determinism. McEwan uses Robbie and Cecilia''s planned reunion — their epistolary exchanges, the imagined cottage, the future-oriented passages — as the hope sustained against wartime statistical likelihood, only for Part Four to expose that hope as authorial projection.', 'Both writers stage hope as the human capacity to sustain a future-image against current evidence — but Dickens permits the hope to be qualifiedly fulfilled (Sissy''s optimism vindicated in the partial reform of Book the Third), while McEwan permits the hope to be fully imagined and then exposes the imagining as the novel''s central act of authorial dishonesty.', 'Sissy as the carrier of imagination and empathy whose function is precisely to sustain the hope no one else has the resources to hold (WP2). Robbie and Cecilia as the lovers whose hope is constituted by their separation — what they hope for IS the proof that the system has prevented it.', 'Dickens narrates Sissy''s optimism through endorsed dialogue — the narrator does not undercut her hope. McEwan narrates Robbie and Cecilia''s hope through their own focalised consciousness in Part Two (Robbie''s memory) and through Part Three''s reunion scene, then retracts both through Part Four''s coda — the narrator does undercut the hope, and the undercutting is the point.', 'Sissy''s hope is structurally distributed — sustained across all three books, vindicated qualifiedly in Book the Third. The lovers'' hope is structurally concentrated — Parts Two and Three carry it; Part Four destroys it. Dickens permits hope a structural payoff; McEwan permits it a structural retraction.', '2021 Q1 (Hope) — direct fit, Pair 1. Also: 2017 Q2 (Friendship — Sissy as friend-as-hope; the lovers as bond-as-hope); 2019 Q2 (Changing relationships — Sissy''s effect on the Gradgrinds; the lovers'' impossible reconciliation); 2023 Q1 (Important choices — Sissy''s choice to stay; Robbie''s choice to enlist for Cecilia).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.comparative_matrix (id, axis, hard_times, atonement, divergence, themes, level_band, is_active, sort_order, ao2, ao3, ao4, thesis, "character", narrative, structure, exam_fit) VALUES ('cm-hope-02', 'Hope', 'Gradgrind''s change and Louisa''s possible future influence on children — ending gesture toward reform', 'Briony''s fictional happy ending for Robbie and Cecilia — imaginative projection of a better future', 'Both function as imaginative projections of a better future, though Atonement exposes its own hope as invented and ethically compromised', '{authorship,endings,guilt,imagination}'::text[], 'top_band', 't'::boolean, '18'::integer, 'Dickens uses the final-chapter narratorial address ("Dear Reader!") and the conditional future tense to render the "Garnering" ending as moral projection — what may yet be, on conditions. McEwan uses the metafictional first-person of Part Four — Briony''s direct address to the reader, the explicit confession that the reunion was written, the rhetorical question about whether the novelist who is also God can achieve atonement — to render the ending as authorial act being judged in real time.', 'Dickens: Victorian belief in the social-purpose novel''s improving function (Ruskin, Carlyle, Dickens''s own journalism); the closing chapter as moral testament. McEwan: post-WWII scepticism about the consolatory novel; postmodern metafiction''s tradition of self-implicating endings (John Fowles''s The French Lieutenant''s Woman as direct antecedent); the "author as God" trope from Genesis through Sartre to McEwan.', 'Both function as imaginative projections of a better future, though Atonement exposes its own hope as invented and ethically compromised. Dickens uses Gradgrind''s reformed self and Louisa''s projected influence on future children to imagine moral improvement extending beyond the novel''s frame. McEwan uses Briony''s fictional reunion of Robbie and Cecilia to imagine the same kind of moral improvement, and then uses Part Four''s metafictional revelation to expose the imagining as itself the act being judged.', 'Both novels close on imaginative projections of moral repair, but Dickens uses the projection to extend his didactic purpose beyond the novel''s frame while McEwan uses the projection to interrogate whether such repair can ever be more than authorial wish. The structural difference is decisive: Dickens''s hope is offered; McEwan''s hope is offered and then withdrawn, with the withdrawal as the novel''s moral act.', 'Gradgrind''s reformed self as the projected future of his earlier ideology — the role-model arc completed in narrative time. Older Briony as the projected future of her younger self — but the projection is shown to be the act of projection itself, not its completion.', 'Dickens''s narrator directly addresses the reader in the closing chapter, asserting moral continuity beyond the text. McEwan''s narrator (Briony) directly addresses the reader in the closing pages, asserting the limits of moral continuity — the reunion she wrote is the only one that exists.', 'Dickens''s hope-ending is structurally consequent — the "Garnering" distributes the consequences of "Sowing" and "Reaping"; the moral projection is structurally earned. McEwan''s hope-ending is structurally retracted — Part Four undoes Part Three; the moral projection is structurally exposed as authorial wish.', '2021 Q1 (Hope) — direct fit, Pair 2. Also: 2020 Q1 (Role models — Gradgrind''s reform; older Briony''s confession); 2019 Q2 (Changing relationships — qualified vs impossible reconciliation); 2023 Q1 (Important choices — Gradgrind''s choice to reform; Briony''s choice to write the alternative).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.comparative_matrix (id, axis, hard_times, atonement, divergence, themes, level_band, is_active, sort_order, ao2, ao3, ao4, thesis, "character", narrative, structure, exam_fit) VALUES ('cm-indep-01', 'Independence', 'Louisa leaving Bounderby and confronting Gradgrind with his system''s failures', 'Cecilia leaving her family and choosing to stand by Robbie against class pressure', 'Both function as acts of female independence against family and class expectations, though with very different outcomes', '{class,gender,morality}'::text[], 'secure', 't'::boolean, '23'::integer, 'Dickens presents Louisa''s independence through crisis dialogue, direct confrontation, and symbolic movement away from Bounderby''s house back to Stone Lodge, where she exposes the failure of Gradgrind''s system in language more emotional than anything her education allowed. McEwan presents Cecilia''s independence through decisive focalisation, social defiance, and epistolary commitment: she rejects family loyalty, chooses Robbie, and writes against the version of events her class wants to preserve. Both writers make female independence a break in the grammar of obedience.', 'Dickens: Victorian gender ideology, filial obedience, patriarchal marriage, and the limited acceptable forms of female self-assertion. Louisa''s leaving is radical emotionally even if socially contained. McEwan: 1930s upper-middle-class family hierarchy, class endogamy, and the social cost of a woman choosing a lower-status man against family testimony; Cecilia''s independence is sharpened by pre-war respectability codes.', 'Both function as acts of female independence against family and class expectations, though with very different outcomes. Dickens allows Louisa''s rebellion to correct Gradgrind and separate her from Bounderby, but not to give her romantic fulfilment. McEwan allows Cecilia''s independence to be morally lucid yet historically futile, because standing by Robbie cannot undo conviction, separation, and death.', 'Both novels treat female independence as ethically necessary but structurally constrained. Louisa''s leaving is the first truthful act produced by a damaged education; Cecilia''s departure is the first fully moral act inside a corrupt family system. Yet neither text offers simple liberation: Dickens domesticates independence into chastened reform, while McEwan turns it into loyalty without rescue.', 'Louisa becomes independent when she stops performing the emotional vacancy her father created and names the damage done to her. Cecilia becomes independent when she chooses moral perception over family allegiance, making herself the anti-Briony: she sees Robbie truly while Briony misreads him. Both women gain ethical clarity by refusing the household scripts assigned to them.', 'Dickens uses omniscient moral pressure and a climactic father-daughter scene to make Louisa''s independence pedagogic: her speech educates Gradgrind. McEwan uses Cecilia''s focalisation and Briony''s retrospective reconstruction to make independence precarious: Cecilia''s truth reaches us through a narrative controlled by the sister who once destroyed it.', 'Louisa''s departure from Bounderby marks the collapse of Book Two''s social arrangements and opens Book Three''s limited reparation. Cecilia''s break from the Tallis family occurs after the accusation and becomes structurally permanent, shaping the absent reconciliation that Briony later invents. Dickens uses independence as a turning point; McEwan uses it as an irreversible fracture.', '2019 Q2 (Independence) — direct fit, Pair 1. Also: 2024 Q1 (Relationships between female characters — female bonds and ruptures); 2019 Q2/Changing relationships where applicable — family fracture and partial repair; 2022 Q1 (Marriage — refusal of coercive or class-sanctioned structures); 2018 Q1 (Criticising society — female resistance to class/patriarchal systems).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.comparative_matrix (id, axis, hard_times, atonement, divergence, themes, level_band, is_active, sort_order, ao2, ao3, ao4, thesis, "character", narrative, structure, exam_fit) VALUES ('cm-indep-02', 'Independence', 'Stephen''s refusal to join the union — moral integrity over collective safety', 'Robbie''s determination to study medicine and rebuild his life after wrongful imprisonment', 'Both function as attempts at moral or professional independence that collide with larger forces — industry, war, class', '{class,justice,morality}'::text[], 'secure', 't'::boolean, '24'::integer, 'Dickens presents Stephen''s independence through moral plainness, dialect, and isolation: his refusal to join the union is linguistically modest but structurally costly, separating him from both workers and masters. McEwan presents Robbie''s independence through aspirational memory, medical imagery, and disciplined interiority: his ambition to study medicine and rebuild his life after prison survives as a future-image during the retreat to Dunkirk. Both writers use restrained language to make independence a form of endurance rather than display.', 'Dickens: Victorian debates around trade unionism, individual conscience, working-class respectability, and the limits of liberal individualism in an industrial economy. McEwan: inter-war meritocracy, grammar-school mobility, medicine as professional respectability, wartime conscription, and the way class barriers can frustrate educational promise even before war intervenes.', 'Both function as attempts at moral or professional independence that collide with larger forces — industry, war, and class. Stephen refuses collective pressure because his conscience will not fit institutional slogans. Robbie attempts to claim a professional future beyond servant-class dependency, but class prejudice and war repeatedly seize control of his life.', 'Both texts expose the fragility of independence when moral will meets structural power. Stephen''s independence is ethically admirable but socially disastrous because Coketown has no space for isolated conscience. Robbie''s independence is aspirational and educated, but the Tallis accusation and war reveal how easily class systems repossess a self-made future.', 'Stephen is defined by negative independence: he refuses what he cannot morally endorse, even when refusal leaves him vulnerable. Robbie is defined by prospective independence: he imagines medicine, Cecilia, and a repaired future as forms of self-authorship. Both characters are decent, self-disciplined men whose independence makes them more exposed, not more protected.', 'Dickens frames Stephen''s independence through sympathetic omniscience, but also through the public misreadings of Coketown, so that moral integrity is visible to the reader and illegible to society. McEwan frames Robbie''s independence through focalised consciousness during war, making his hopes intensely present while the novel''s later structure reveals their historical impossibility.', 'Stephen''s refusal triggers exclusion, suspicion, and eventual death, so independence becomes a plot mechanism of isolation. Robbie''s professional ambition is established before the accusation, suspended by prison, and almost extinguished by war; its survival in memory becomes part of the novel''s tragic counterfactual. Dickens makes independence fatal in the social present; McEwan makes it a future denied.', '2019 Q2 (Independence) — direct fit, Pair 2. Also: 2017 Q1 (Difficult circumstances — principled men under pressure); 2018 Q1 (Criticising aspects of society — union, class, legal and military systems); 2023 Q1 (Important choices — refusal, duty, self-definition); 2021 Q1 (Hope — future-oriented independence).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.comparative_matrix (id, axis, hard_times, atonement, divergence, themes, level_band, is_active, sort_order, ao2, ao3, ao4, thesis, "character", narrative, structure, exam_fit) VALUES ('cm-love-01', 'Love', 'Stephen–Rachael — restrained, ethical love that cannot fully flourish under Victorian marriage law and class', 'Robbie–Cecilia — passionate love thwarted by class prejudice, false accusation, conviction and war', 'Both function as morally "right" loves blocked by external forces, intensifying the critique of the societies that deny them', '{class,endings,gender,morality}'::text[], 'secure', 't'::boolean, '15'::integer, 'Dickens uses restrained idiom and conditional grammar around Stephen and Rachael ("if I had but knowed it") — the love registered through what is not said. The chapter "No Way Out" (Book One Chapter 11) externalises the legal impossibility. McEwan uses extended descriptive prose around the library scene (Part One Chapter 11) — sustained sensory detail, the eroticism of withheld speech, then explicit physical encounter as the suspension of class register. The fountain scene as misread visual, the letter as material misdirection, the library as eventual fulfilment, then the war as structural interruption.', 'Dickens: Victorian marriage law (the 1857 Matrimonial Causes Act post-dating Hard Times by three years); coverture and the impossibility of working-class divorce; the Wesleyan tradition of "moral marriage" that gives Stephen / Rachael their ethical legitimacy. McEwan: 1930s class-coded romance (Forster''s Howards End and A Room with a View as antecedents); the wartime separation of lovers as a literary structure (Vera Brittain''s Testament of Youth; Sebastian Faulks''s Birdsong); post-Lawrentian explicitness in the literary representation of sex.', 'Both function as "right" loves blocked by external forces, intensifying the critique of the societies that deny them. Dickens uses Stephen and Rachael to dramatise love thwarted by Victorian marriage law and class — a moral relationship rendered impossible by legal and economic structures. McEwan uses Robbie and Cecilia to dramatise love thwarted by class prejudice, wrongful conviction, and war — a fully realised relationship rendered briefly possible and then violently terminated by external history.', 'Both writers stage "right" love as the love that the social structures of their period make impossible — Stephen and Rachael by Victorian marriage law, Robbie and Cecilia by class prejudice and wartime catastrophe. In both cases the love''s rightness is registered precisely through its inability to be socially completed, making the obstruction the proof of value.', 'Rachael as Stephen''s moral co-witness (treated under Friendship Theme 2) — here the woman whose love is constituted by what it cannot become. Cecilia as the Tallis daughter whose love crosses the class she was born into — the breaking-with-family is the love''s enabling condition, the structural inverse of Briony who remains within the family.', 'Dickens narrates Stephen / Rachael through restrained free indirect — the narrator withholds intrusion as the characters withhold speech, modelling the relationship''s discipline at the level of style. McEwan narrates Robbie / Cecilia through alternating focalisation in Part One (his consciousness, her consciousness, the moments of misreading between them) and through Robbie''s wartime memory in Part Two (the recollected library scene as sustaining vision).', 'Stephen / Rachael''s love is structurally constant but unconsummated — present throughout all three books; the relationship''s structural function is to outlive Stephen and pass his moral inheritance to Rachael. Robbie / Cecilia''s love is structurally fragmented — Part One sets it up, Part Two destroys it through wartime separation, Part Three offers fictional reunion, Part Four reveals the fiction. The fragmentation is the love story.', '2020 Q2 (Love) — direct fit, Pair 1. Also: 2017 Q2 (Friendship — Stephen/Rachael as restrained love/friendship; the MATRIX explicitly cites this pair); 2022 Q1 (Marriage — Stephen''s existing marriage as legal constraint; Robbie/Cecilia''s unrealised marriage as the structural counter-fact); 2017 Q1 (Difficult circumstances — both relationships destroyed by the systems they exist within).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.comparative_matrix (id, axis, hard_times, atonement, divergence, themes, level_band, is_active, sort_order, ao2, ao3, ao4, thesis, "character", narrative, structure, exam_fit) VALUES ('cm-love-02', 'Love', 'Louisa''s loveless marriage to Bounderby — transactional, class-driven, emotionally annihilating', 'Paul Marshall–Lola — deeply troubling marriage built on abuse, silence and class-interest', 'Both function as marriages that expose love''s corruption by power, class and self-interest', '{class,gender,justice,morality}'::text[], 'secure', 't'::boolean, '16'::integer, 'Dickens uses the proposal scene (Book One Chapter 15 — Gradgrind''s catechistic delivery of Bounderby''s offer; Louisa''s "What does it matter?") and the marriage''s slow unravelling through Mrs Sparsit''s surveillance staircase (Book Two Chapter 10) — methods that render the marriage as both private failure and public ideology breaking. McEwan uses the Part Four coda''s bureaucratic registration of the Marshall marriage — the brief mention of the baronetcy, the Marshall Foundation, the funding of medical research — and the studied flatness of tone to render this marriage as the system''s structural endorsement of impunity.', 'Dickens: Victorian marriage as economic contract and class consolidation; the doctrine of coverture; the figure of the "respectable" marriage as ideological cover for emotional or economic violence. McEwan: WWII profiteering and post-war respectability (the actual Cadbury/Rowntree families as historical analogues); the 1947 New Year Honours list as historical referent; the post-war legitimation of inter-war wealth through marriage and philanthropy.', 'Both function as marriages that expose love''s corruption by power, class, and self-interest. Dickens uses Louisa''s marriage to Bounderby to dramatise marriage as economic contract — a transaction Louisa enters under paternal pressure that her education denied her the resources to refuse. McEwan uses the Marshall / Lola marriage to dramatise marriage as alibi — a union that legitimises the perpetrator and silences the victim under the cover of social respectability, with the resulting baronetcy as the system''s structural reward for the cover-up.', 'Both writers stage the corrupted marriage as the structural register of social hypocrisy — Louisa''s marriage to Bounderby exposes Victorian capitalism''s reduction of women to property; Marshall''s marriage to Lola exposes the inter-war class system''s protection of the powerful through institutional silence. In both cases the marriage is not the failure of love but the success of the system that prevents love from mattering.', 'Louisa as "victim of repression" whose marriage exposes utilitarianism''s human cost (WP2). Marshall as the satirical target previously discussed (Theme 3) — the unpunished perpetrator whose marriage to Lola transforms his crime into his social capital. Lola as the silenced victim whose silence the novel''s structure makes audible through what is not said about her.', 'Dickens narrates Louisa''s marriage through omniscience that withholds her interiority strategically — the marriage is shown from outside (Mrs Sparsit''s view) until the breaking-point lets us in. McEwan narrates the Marshall marriage through Briony''s late-coda recognition — the marriage is registered, not dramatised, because the novel''s structure makes the silence about Lola the central moral fact.', 'Louisa''s marriage occupies Book Two ("Reaping") — its breakdown is the structural midpoint. The Marshall marriage is the novel''s structural shadow — barely shown, but its existence in the coda is the institutional confirmation of everything Briony has been writing against.', '2020 Q2 (Love) — direct fit, Pair 2. Also: 2022 Q1 (Marriage — both as central cases); 2018 Q1 (Criticising society — both marriages as the structural register of class hypocrisy); 2024 Q1 (Relationships between female characters — Louisa silenced by Bounderby''s authority; Lola silenced by Marshall''s).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.comparative_matrix (id, axis, hard_times, atonement, divergence, themes, level_band, is_active, sort_order, ao2, ao3, ao4, thesis, "character", narrative, structure, exam_fit) VALUES ('cm-marriage-01', 'Marriage', 'Louisa–Bounderby — marriage as economic and social contract; the institution used to enforce class hierarchy', 'Marshall–Lola — marriage covering a crime, cementing social alliances and silencing a victim', 'Both function as marriages that legitimise injustice, showing the institution as a tool of power rather than affection', '{class,gender,justice,morality}'::text[], 'secure', 't'::boolean, '21'::integer, 'Dickens uses proposal dialogue, emotional understatement, and surveillance imagery to present the Louisa-Bounderby marriage as contract rather than union: Gradgrind''s language of calculation, Louisa''s exhausted question "What does it matter?", and Mrs Sparsit''s staircase fantasy all make marriage a structure of social control. McEwan uses compression, tonal flatness, and coda revelation to present the Marshall-Lola marriage as institutional laundering: the baronetcy, philanthropy, and public respectability conceal the crime the narrative has taught us to recognise.', 'Dickens: Victorian marriage as economic alliance, the limited legal and emotional agency of women under coverture, and the social acceptability of age- and wealth-imbalanced marriage. McEwan: inter-war and post-war class consolidation, the ability of wealth to purchase respectability, wartime profiteering, and the legal/social difficulty of naming sexual violence when class power protects the perpetrator.', 'Both function as marriages that legitimise injustice, showing the institution as a tool of power rather than affection. Dickens uses Louisa''s marriage to Bounderby to expose how utilitarian and capitalist logic turns a daughter into exchangeable property. McEwan uses Marshall''s marriage to Lola to expose how class respectability can transform violation into social alliance and public honour.', 'Both writers present marriage not as romantic fulfilment but as the social form through which power protects itself. Louisa''s marriage reveals the moral bankruptcy of a system that calls emotional coercion prudence; Lola''s marriage reveals a more chilling system in which marriage helps erase the crime it follows. Dickens makes marriage oppressive; McEwan makes it evidentially obscene.', 'Louisa is the emotionally under-educated daughter whose consent has been prepared by years of repression; Bounderby is the self-made fraud whose marriage confirms his desire to possess class status and female obedience. Lola remains troublingly silent and socially absorbed, while Marshall becomes the unpunished predator whose later public benevolence intensifies the corruption of the marriage plot.', 'Dickens narrates the marriage through external pressure and delayed interior release: Louisa''s real suffering becomes fully legible only at the crisis with Gradgrind. McEwan narrates Marshall and Lola''s marriage obliquely through Briony''s late knowledge, forcing the reader to infer the violence of what respectable narrative refuses to say directly.', 'Louisa''s marriage is central to Book Two, "Reaping": it is the structural harvest of Gradgrind''s education and Bounderby''s capitalism. Marshall and Lola''s marriage is structurally delayed until the coda, where it retroactively confirms the novel''s deepest social corruption. Dickens places marriage at the centre of collapse; McEwan places it as the final sign of impunity.', '2022 Q1 (Marriage) — direct fit, Pair 1. Also: 2020 Q2 (Love — corrupted love and transactional marriage); 2018 Q1 (Criticising aspects of society — marriage as social hypocrisy); 2024 Q1 (Relationships between female characters — Louisa/Sparsit and Lola/Briony/Cecilia); 2019 Q2 (Changing relationships — marriage breakdown and permanent damage).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.comparative_matrix (id, axis, hard_times, atonement, divergence, themes, level_band, is_active, sort_order, ao2, ao3, ao4, thesis, "character", narrative, structure, exam_fit) VALUES ('cm-marriage-02', 'Marriage', 'Stephen''s existing marriage — legal tie that prevents union with Rachael; law as cage for the innocent', 'The unrealised Robbie–Cecilia marriage — the relationship denied by false testimony and war', 'Both function to show how law and circumstance can deny morally right unions, amplifying the critique of social injustice', '{class,endings,justice,morality}'::text[], 'secure', 't'::boolean, '22'::integer, 'Dickens uses the chapter title "No Way Out", Stephen''s dialect, and the contrast between legal marriage and moral love to make marriage a trap: the law''s abstraction is felt through Stephen''s broken speech and Rachael''s restraint. McEwan presents Robbie and Cecilia''s unrealised marriage through letters, memory, and counterfactual structure: their relationship is given emotional and erotic force, then denied social completion by accusation, imprisonment, and war. In both, absence becomes a method of critique.', 'Dickens: before the 1857 Matrimonial Causes Act, divorce was effectively inaccessible to the working poor, and coverture treated marriage as a legal status rather than an emotional covenant. Stephen''s case exposes the class basis of marital freedom. McEwan: 1930s class prejudice, wartime separation, and the literary tradition of interrupted lovers; marriage is possible in principle but made impossible by social accusation and historical catastrophe.', 'Both function to show how law and circumstance can deny morally right unions, amplifying the critique of social injustice. Dickens makes Stephen legally bound to a destructive marriage while morally bonded to Rachael. McEwan makes Robbie and Cecilia emotionally committed but historically prevented from any legitimate future together.', 'Both texts use blocked marriage to distinguish moral rightness from social permission. Dickens''s tragedy is that the wrong marriage legally exists and the right one cannot; McEwan''s tragedy is that the right union exists only as memory, letter, and Briony''s later fiction. The institution that should formalise love instead reveals the limits of justice.', 'Stephen is the decent man whose marital status makes his virtue painful rather than socially rewarded; Rachael is the moral partner who can be loved but not lawfully possessed. Robbie and Cecilia are presented as lovers who achieve emotional independence from class expectation but are denied any civic future. Their unrealised marriage becomes an index of what Briony''s accusation and war have stolen.', 'Dickens''s narrator treats Stephen and Rachael with solemn restraint, allowing silence and renunciation to carry the moral weight of their bond. McEwan uses shifting focalisation and later authorial exposure: Robbie and Cecilia''s future is narrated first as sustaining hope, then revealed as an artefact of Briony''s compensatory authorship.', 'Stephen''s existing marriage repeatedly blocks forward movement, making the plot circle around impossibility until his death. Robbie and Cecilia''s unrealised marriage is structurally projected rather than enacted: Part One initiates love, Part Two sustains it through memory, Part Three appears to restore it, and Part Four withdraws that restoration. Dickens traps marriage in law; McEwan traps it in fiction.', '2022 Q1 (Marriage) — direct fit, Pair 2. Also: 2020 Q2 (Love — morally right love blocked); 2021 Q1 (Hope — future union imagined against evidence); 2017 Q1 (Difficult circumstances — law/class/war as barriers); 2019 Q2 (Changing relationships — impossible reconciliation and blocked futures).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.comparative_matrix (id, axis, hard_times, atonement, divergence, themes, level_band, is_active, sort_order, ao2, ao3, ao4, thesis, "character", narrative, structure, exam_fit) VALUES ('cm-rolemodel-01', 'Role models', 'Sissy Jupe — compassionate moral model opposed to utilitarianism, offering an alternative to fact-based education and harsh capitalism.', 'Senior nurses / matron — professional, disciplined models shaping Briony''s wartime ethics through enforced humility and practical compassion.', 'Both function as female figures who model responsibility and care, offering alternatives to their societies'' harsher values.', '{childhood,education,gender}'::text[], NULL, 't'::boolean, '13'::integer, 'Dickens uses Sissy''s "girl number twenty" labelling moment, her failure to define a horse (Book One Chapter 2), and the recurrent imagery of warmth and fire associated with her against the cold geometry of the Gradgrind household — methods of characterisation through positional and lexical contrast. McEwan uses sharp imperative dialogue from the matron and senior nurses, procedural detail of bed-making and dressings, and the deliberate erasure of Briony''s individual name in favour of "Nurse Tallis" — methods of institutional levelling that strip her of the authorial self-importance Part One showed.', 'Dickens: Victorian doctrine of female moral influence (Sarah Stickney Ellis''s The Women of England, 1839); the working-class moral exemplum tradition (Hannah More''s tracts); the circus as alternative pedagogical community. McEwan: the inter-war and wartime nursing profession (Florence Nightingale''s influence still operative; Vera Brittain''s Testament of Youth as antecedent); the matron tradition as a class-levelling institution that pre-dates the NHS.', 'Both function as female figures who model responsibility and care, offering alternatives to their societies'' harsher values. Dickens uses Sissy as the stable moral counter-presence to Gradgrindian Fact — her presence in the household is the alternative pedagogy made flesh. McEwan uses the senior nurses and matron as the institutional embodiment of professional ethics that Briony must accept in place of her literary self-fashioning — discipline as moral re-education.', 'Both texts use the alternative-female role model to register a form of moral authority the protagonist''s own class formation has refused them — Sissy''s compassion is what Louisa was educated against; the matron''s discipline is what Briony was indulged out of. In both cases the role model functions less as imitative ideal than as structural correction.', 'Sissy as "Embodiment of imagination/empathy", "Alternative educational/human model" (WP2). The senior nurses and matron as institutional types — no individual character pages, because their function depends on their role rather than their individuality. This is itself a method comparison: Dickens individuates the alternative (Sissy as person); McEwan institutionalises it (the nurses as role).', 'Dickens uses third-person omniscience to grant Sissy explicit moral approval — the narrator endorses her against the system she opposes. McEwan filters the nurses through Briony''s retrospective consciousness — the role models are visible to us only as Briony later judges her younger self for needing them.', 'Sissy is structurally constant — introduced in Book One Chapter 2, present at Stone Lodge in Book the Third''s recovery. The senior nurses occupy Part Three''s nursing arc — structurally bounded by Briony''s wartime training; once Part Four reveals Part Three was authored, their role-model function is itself recast as Briony''s projection.', '2020 Q1 (Role models) — direct fit, Pair 1. Also: 2017 Q2 (Friendship — Sissy/Louisa; the nurses'' bond); 2018 Q2 (Education — Sissy''s alternative pedagogy; the matron tradition as practical re-education); 2024 Q1 (Relationships between female characters — Sissy/Louisa; the nurses as female community).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.comparative_matrix (id, axis, hard_times, atonement, divergence, themes, level_band, is_active, sort_order, ao2, ao3, ao4, thesis, "character", narrative, structure, exam_fit) VALUES ('cm-rolemodel-02', 'Role models', 'Gradgrind (later) — moves from cold rationalist to more self-aware, partly repentant father; models the possibility of belated moral change.', 'Older Briony as writer — attempts to model accountability by confessing through fiction, raising questions about whether authorship can constitute moral repair.', 'Both function as problematic role models who try to correct earlier errors, raising questions about the limits of moral change.', '{guilt,authorship,endings}'::text[], NULL, 't'::boolean, '14'::integer, 'Dickens uses Gradgrind''s late dialogue — chastened diction, the dropping of the abstract-noun lists that characterised his earlier speech, the physical gesture of kneeling beside Louisa (Book the Third Chapter 1) — to mark moral change through linguistic register. McEwan uses Briony''s 1999 first-person coda — the shift to direct authorial voice after three Parts of third-person retrospective — to expose her authorship and force the reader to judge whether her late confession constitutes reparation or self-exoneration.', 'Dickens: Victorian narrative of belated moral conversion (the religious tract tradition; Carlyle''s "natural supernaturalism"); the doctrine of repentance as moral capital. McEwan: post-Holocaust questions about whether literary reparation can ever be adequate (Adorno on poetry after Auschwitz as a structural antecedent); postmodern scepticism about confessional authority; the metafictional novel''s interrogation of its own moral seriousness.', 'Both function as problematic role models who try to correct earlier errors, raising questions about the limits of moral change. Dickens uses Gradgrind''s belated reform to test whether the author of damage can become its remedy — and answers yes, qualifiedly. McEwan uses older Briony''s confession-through-fiction to test the same question and answers, finally, no — the fictional reparation is exposed as part of the moral problem rather than its solution.', 'Both novels stage the role-model arc as a question rather than an answer — whether the author of harm can become its corrective. Dickens''s Gradgrind, kneeling and chastened, suggests qualified yes. McEwan''s older Briony, writing the reunion she never permitted, suggests structured no — and uses the form of the novel itself to deliver that verdict.', 'Gradgrind as "less villain than failed ideologue" (WP2); arc = "Ideological certainty → Moral collapse → Partial reform". Older Briony as the only character in either novel whose authorship is the moral arc — the writer is the character, the writing is the recognition. The A* concept of "the attempt was all": "Briony''s moral worth derives from attempted reparation rather than completed forgiveness."', 'Dickens narrates Gradgrind''s change through intrusive third-person commentary — the narrator validates the reform explicitly. McEwan narrates older Briony''s "reform" through her own first-person voice in the coda — the validation must come from the reader, not the narrator, because the narrator is the one needing judgement.', 'Gradgrind''s reform occupies Book the Third ("Garnering") — structural reward for prior consequence. Older Briony''s "reform" is the structural premise of the entire novel — Parts One through Three are her acts of authorship; Part Four exposes that authorship; the structure is itself the moral question.', '2020 Q1 (Role models) — direct fit, Pair 2. Also: 2017 Q1 (Difficult circumstances — Louisa and older Briony as figures whose inner damage demands moral correction); 2019 Q2 (Changing relationships — Gradgrind/Louisa repaired; Briony/Cecilia not); 2023 Q1 (Important choices — Gradgrind''s choice to reform; Briony''s choice to write).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.comparative_matrix (id, axis, hard_times, atonement, divergence, themes, level_band, is_active, sort_order, ao2, ao3, ao4, thesis, "character", narrative, structure, exam_fit) VALUES ('cm-setting-01', 'Settings', 'Coketown — industrial town where humans are reduced to "Hands" and life is governed by mechanical time', 'Dunkirk and war-ravaged France — landscape of mass suffering, disintegration and industrial-scale death', 'Both function as industrialised spaces of dehumanisation, showing modern systems treating people as expendable', '{class,morality,war}'::text[], 'secure', 't'::boolean, '9'::integer, 'Dickens uses recurrent industrial metaphors — Coketown''s "interminable serpents" of smoke, the "elephants of melancholy madness" (the pistons), the painted-on uniformity of the streets — to render the town as the system''s visible signature. The metaphors are anthropomorphic in reverse: machinery is given monstrous life, workers reduced to "Hands". McEwan uses war-zone naturalism — the leg in the tree, the dismembered child, the bombing-aftermath at Bray Dunes — and free indirect through Robbie''s failing consciousness to render Dunkirk as the same industrial logic at lethal scale.', 'Dickens: 1840s industrial North (Manchester, Preston) as Dickens''s research base (the 1854 Preston strike specifically); the "Condition of England" novel tradition (Gaskell''s North and South, Disraeli''s Sybil); Carlyle''s industrial critique. McEwan: Dunkirk evacuation (Operation Dynamo, 26 May - 4 June 1940); the post-war Dunkirk myth''s class-blind heroism; war-photography aesthetics (the Robert Capa influence McEwan has cited).', 'Both function as industrialised spaces of dehumanisation, showing modern systems treating human beings as expendable. Dickens uses Coketown to dramatise industrial capitalism''s reduction of workers to "Hands"; McEwan uses Dunkirk to dramatise wartime industrialism''s reduction of soldiers to bodies. The two settings share a structural logic: the system requires the human at scale and remains indifferent to the human as such.', 'Both novels use their central setting as the visible signature of the system that destroys their working-class protagonist — Coketown the architecture of Stephen''s destruction, Dunkirk the architecture of Robbie''s — and both writers make the setting itself an active agent rather than passive backdrop.', 'Stephen is constituted by Coketown — his dialect, his power-loom labour, his "muddle" — and destroyed by it. Robbie is destroyed by Dunkirk having been constituted (in Part One) by the Tallis house; the setting-transit (Tallis -> prison -> Dunkirk) is the structural arc of his social destruction.', 'Dickens uses intrusive narratorial commentary on Coketown — the narrator stands above the town and judges it. McEwan uses Robbie''s focalisation through the retreat — the narrator descends into the wounded soldier''s failing consciousness, refusing the elevation Dickens permits himself.', 'Coketown is the constant — Books One, Two, and Three are all set there; the structural unity is geographic, and Stephen''s exit (railway, fall, death) is the structural rupture. Dunkirk is a transit — Robbie passes through it; Part Two ends mid-collapse; the structural rupture is the un-completion of his journey home.', '2019 Q1 (Settings) — direct fit, Pair 1. Also: 2024 Q2 (Settings revisited — explicitly linking setting to whose experience is foregrounded); 2018 Q1 (Criticising society — Coketown and Dunkirk as the spatial registers of the critique); 2021 Q1 (Hope — Coketown''s smoke vs Dunkirk''s evacuation-as-rescue-myth).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.comparative_matrix (id, axis, hard_times, atonement, divergence, themes, level_band, is_active, sort_order, ao2, ao3, ao4, thesis, "character", narrative, structure, exam_fit) VALUES ('cm-setting-02', 'Settings', 'The circus — colourful, fluid community celebrating imagination and human warmth as a counter-world to Coketown', 'The Tallis house (pre-war) — ordered, aesthetic space that stages class hierarchy, desire and social ritual', 'Both function as highly symbolic spaces where alternative values — imagination, romance, class ritual — are dramatised against the novel''s dominant ideology', '{class,family,imagination}'::text[], 'secure', 't'::boolean, '10'::integer, 'Dickens uses the circus through Sleary''s lisping inclusive speech ("we musth"), the troupe''s communal labour, exotic naming (Signor Jupe, Master Kidderminster), and the warmth-vs-fact lexis transferred from circus to Sissy. McEwan uses the Tallis house through the elaborate dinner-scene staging in Part One Chapter 4, the precision of period detail (the 1935 heatwave, the green dress, the Bernini-style fountain), and the country-house novel''s structural inheritance (Austen, Forster, Waugh) deployed self-consciously.', 'Dickens: Astley''s Amphitheatre as real-world referent; the circus as Victorian working-class entertainment culture; Dickens''s own journalism on "The Amusements of the People". McEwan: the country-house novel tradition; pre-war upper-middle-class domesticity (1935 heatwave is historically dated); the inter-war class theatre Briony has been formed by.', 'Both function as highly symbolic spaces where alternative values are dramatised — Dickens uses the circus to stage imagination and communal warmth as alternatives to Coketown utilitarianism; McEwan uses the Tallis house to stage class ritual and aesthetic order as the precise conditions under which Briony''s crime becomes possible. The two settings function inversely: the circus is the moral alternative; the Tallis house is the moral problem.', 'Both Dickens and McEwan use their alternative setting to register what their primary setting suppresses or enables — Dickens uses the circus to register what Coketown excludes (imagination, communal warmth, generic mobility); McEwan uses the Tallis house to register what class ritual conceals (sexual violence, racial assumption, the inheritance of unearned authority).', 'Sleary, Sissy, and the troupe define the circus as alternative community — they exist to be lost from and returned to. The Tallises and their guests (the Quincey twins, Marshall, the police) define the house as the social formation that produces Briony''s misreading.', 'Dickens uses inclusive omniscience to render the circus warmly — the narrator likes Sleary. McEwan uses the multi-focal Part One (chapters from Cecilia''s, Briony''s, Robbie''s, Emily''s points of view) to render the house as the contested epistemic space where the crime happens — every consciousness has partial information, and the house''s order conceals that.', 'The circus is structurally outside the main plot — it''s the place Sissy comes from and where Tom hides; its function is to provide moral refuge for the protagonists. The Tallis house is structurally central to Part One; its dinner-scene chapter is the longest single-event chapter in the novel; Parts Two through Four are structurally the consequences of one Tallis-house evening.', '2019 Q1 (Settings) — direct fit, Pair 2. Also: 2024 Q2 (Settings revisited); 2017 Q2 (Friendship — circus community vs Tallis household as spaces of friendship); 2018 Q1 (Criticising society — both spaces are class-systems made architectural).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.comparative_matrix (id, axis, hard_times, atonement, divergence, themes, level_band, is_active, sort_order, ao2, ao3, ao4, thesis, "character", narrative, structure, exam_fit) VALUES ('cm-society-01', 'Criticising aspects of society', 'Coketown / Bounderby / Gradgrind system — satirise industrial capitalism, utilitarianism and the myth of meritocracy', 'Tallis house / Paul Marshall / tribunal — expose class prejudice, aristocratic entitlement, legal failure and war profiteering', 'Both function as microcosms of unjust social orders, using one household or employer to stand for systemic problems', '{authorship,class,justice,war}'::text[], 'secure', 't'::boolean, '5'::integer, 'Dickens uses caricature naming (Bounderby, Gradgrind, M''Choakumchild, Slackbridge) and accumulated abstract-noun lists ("Fact, fact, fact, everywhere in the material aspect of the town") to render social critique as recognisable type. McEwan uses brand-name realism (the Amo bar as commodified affection and as Marshall''s war-profiteering vehicle); indirect satirical inflection through the Tallis class idiom; the studied neutrality of the legal-bureaucratic prose around Marshall, which is itself the satire.', 'Dickens: 1840s factory-system critique (Engels, The Condition of the Working Class in England, 1845; Carlyle''s Past and Present, 1843); Bentham/Mill utilitarian pedagogy; the schoolroom-as-factory metaphor. McEwan: inter-war country-house ideology (Waugh''s Brideshead Revisited as intertext); WWII profiteering and the class composition of British capitalism (the historical Cadbury/Rowntree families as analogues for Marshall); the 1947 Industrial Charter that legitimised pre-war wealth into post-war respectability.', 'Both function as microcosms of unjust social orders, using one family or employer to stand for systemic problems. Dickens uses the Coketown system (industrial capitalism + utilitarian education + Bounderby''s self-made-man myth) to satirise Victorian capitalism; McEwan uses the Tallis household, Paul Marshall''s war profiteering, and the legal tribunal together to satirise the inter-war class settlement and its post-war respectability.', 'Both Hard Times and Atonement target an entire ideological system rather than any individual antagonist, but Dickens makes that system visible through caricature and external satire while McEwan makes it audible through the very lexicon of the class he is satirising — including the rehabilitated language of post-war respectability that protects Paul Marshall from accountability.', 'Bounderby, Gradgrind, and M''Choakumchild are types representative of the satirised system. The Tallises — Jack, Emily, Briony, Leon — and Marshall are not types but specific characters whose specificity is itself the means of critique. Marshall embodies Atonement''s central moral indictment: the unpunished crime + the legitimised wealth + the eventual baronetcy = the satirised class''s full structural success.', 'Dickens''s intrusive narrator delivers social verdicts directly. McEwan''s narrator — Briony — implicates herself in the social formation she critiques, making narrative authority itself part of the critique. The author''s class proximity to Marshall (Briony as Tallis daughter) is the central moral fact.', 'Coketown''s totalising critique is achieved by Books One-Three''s tripartite biblical structure (Sowing / Reaping / Garnering). The Tallis critique is achieved by Part One''s expansive country-house chapter rhythm, structurally undone by Parts Two-Four''s progressive corrosion of the very voice that constituted Part One. Marshall''s structural function: present at the Part One dinner, central to the Part One crime, absent from Parts Two-Three, returns triumphant in the Part Four coda as Lord and Lady Marshall founding a literary prize.', '2018 Q1 (Criticising aspects of society) — direct fit, Pair 1. Also: 2019 Q1 (Settings — Coketown and the Tallis house as the spatial registers of the critique); 2024 Q2 (Settings revisited — explicitly linking setting to who tells the story and whose experience is foregrounded).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.comparative_matrix (id, axis, hard_times, atonement, divergence, themes, level_band, is_active, sort_order, ao2, ao3, ao4, thesis, "character", narrative, structure, exam_fit) VALUES ('cm-society-02', 'Criticising aspects of society', 'Stephen''s union dilemma — critique of both heartless masters and the rigidity of union politics', 'Robbie''s trial — critique of how class and gender expectations bias any notion of justice', 'Both function as case studies showing that institutions claiming fairness are deeply compromised by ideology', '{authorship,class,justice,morality}'::text[], 'secure', 't'::boolean, '6'::integer, 'Dickens uses dramatic-monologue staging at the union meeting (Slackbridge''s pamphleteering rhetoric against Stephen''s dialect "muddle") and scenic confrontation at the Bounderby interview — Stephen''s exclusion is made audible because both institutions speak in registers he cannot access. McEwan uses bureaucratic prose and the absence of dialogue around the trial — Robbie is convicted in narrative summary, not scene, because the novel''s premise is that his voice cannot be heard.', 'Dickens: Chartist debates of the 1840s; the union-as-tyranny argument (Carlyle); the Wesleyan dissent tradition that gives Stephen his moral-individualist register. McEwan: pre-1907 reforms on juvenile witness evidence (Briony''s testimony as legally suspect by any modern standard); the literary tradition of the wrongful-conviction novel (Rebecca West''s The Return of the Soldier; McEwan''s own The Innocent).', 'Both function as case studies of institutions whose claim to fairness is the precise mechanism by which they destroy the morally decent. Dickens shows Stephen excluded by both masters (Bounderby) and union (Slackbridge); McEwan shows Robbie excluded by the family, the legal tribunal, and the wartime state. In both, every available institution fails the morally decent man in the name of due process.', 'Both Stephen Blackpool and Robbie Turner are destroyed by institutions whose claim to fairness is the precise mechanism of their injustice, and both writers use the dispersal of culpability across multiple institutions to expose how modern systems of justice protect the powerful at the cost of the morally decent.', 'Stephen functions as moral exception within his class — refusing the union, refusing Bounderby, structurally homeless; "virtue crushed by systemic injustice." Robbie functions as moral norm rendered exceptional by class — his decency is the average, his criminalisation the outlier. Two different relationships to the social majority, same structural consequence.', 'Dickens dramatises Stephen''s social isolation through scenic confrontation — the union meeting, the Bounderby interview, the home-leaving. McEwan dramatises Robbie''s social isolation through narrative absence — the trial is summarised, not staged, because the novel''s premise is that Robbie''s voice cannot be heard within the legal system that convicts him.', 'Stephen''s exclusion is staged at three distinct social moments (union, master, wife) across Book the Second — accumulation by repetition. Robbie''s exclusion is structurally compressed into the gap between Part One''s events and Part Two''s wartime aftermath — accumulation by ellipsis. Different structural means; same effect of structural inevitability.', '2018 Q1 (Criticising aspects of society) — direct fit, Pair 2. Also: 2021 Q2 (Conflict — individual vs society; the union meeting and the tribunal are both confrontation scenes); 2023 Q1 (Important choices — Stephen''s refusal to join the union, Robbie''s choice to enlist as a way back to Cecilia).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.comparative_matrix (id, axis, hard_times, atonement, divergence, themes, level_band, is_active, sort_order, ao2, ao3, ao4, thesis, "character", narrative, structure, exam_fit) VALUES ('mock-childhood', 'Childhood', 'Children are ''little pitchers'' to be filled with fact (Ch. 2); Louisa''s emotional malformation and Tom''s corruption are direct products of Gradgrindian pedagogy.', 'Thirteen-year-old Briony''s half-formed grasp of adult sexuality and class produces a catastrophic misreading of the library and fountain scenes that the novel treats as developmental, not exculpatory.', 'Both novelists locate the origin of adult catastrophe in a mis-shaped childhood, but Dickens blames a system while McEwan implicates the child''s own imagination.', '{}'::text[], NULL, 't'::boolean, '104'::integer, 'Dickens''s mechanical imagery of pouring, filling and grinding vs McEwan''s careful free-indirect rendering of adolescent cognition and the gap between perception and meaning.', 'Victorian debates on rote learning, the Lancasterian / monitorial system and Newcastle Commission anxieties about mass schooling vs twentieth-century developmental psychology and the problem of the unreliable child witness.', 'Both novels stage childhood as a site where adult ideologies (utilitarianism, class) inscribe themselves with lifelong consequence.', 'Both novelists locate the origin of adult catastrophe in a mis-shaped childhood, but Dickens blames a system while McEwan implicates the child''s own imagination.', 'Louisa / Tom / Sissy vs Briony / Lola', 'Narratorial pity for the child vs immersive child-focalisation', 'Childhood as ''Sowing'' that determines later ''Reaping'' vs childhood as Part One whose meaning is rewritten by Part Four', 'Use for childhood, education, formation, or innocence prompts.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.comparative_matrix (id, axis, hard_times, atonement, divergence, themes, level_band, is_active, sort_order, ao2, ao3, ao4, thesis, "character", narrative, structure, exam_fit) VALUES ('mock-class', 'Class and power', 'Bounderby''s fraudulent rags-to-riches myth and the Coketown ''Hands'' expose industrial capitalism''s dehumanisation of labour.', 'The Tallis family''s casual assumption of authority over Robbie — the cleaner''s son they ''sponsored'' — shows interwar class hierarchy operating as quiet violence.', 'Each novel exposes how the dominant class narrates itself into innocence, though Dickens satirises this openly while McEwan lets it indict itself in silence.', '{}'::text[], NULL, 't'::boolean, '105'::integer, 'Dickens''s grotesque caricature and industrial similes (''elephants in melancholy madness'') vs McEwan''s understated free indirect register that lets class assumptions speak themselves.', 'Mid-Victorian industrial capitalism, the Factory Acts and post-1834 Poor Law settlement vs the 1930s English class system on the eve of war and imperial decline.', 'Both novels show class as a structure that disguises itself as nature or merit.', 'Each novel exposes how the dominant class narrates itself into innocence, though Dickens satirises this openly while McEwan lets it indict itself in silence.', 'Bounderby / Stephen vs the Tallises / Robbie', 'Satirical caricature vs ironic free indirect style', 'Public confrontation and exposure vs private misreading with public consequences', 'Strong for class, power, hypocrisy, or ''social structures'' questions.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.comparative_matrix (id, axis, hard_times, atonement, divergence, themes, level_band, is_active, sort_order, ao2, ao3, ao4, thesis, "character", narrative, structure, exam_fit) VALUES ('mock-endings', 'Endings and closure', 'The ''Garnering'' final book distributes a measured, moralised closure: Tom dies abroad in remorse, Louisa is denied remarriage and motherhood, Sissy inherits a domestic future — closure is partial and pointedly unequal.', 'The 1999 ''London'' coda detonates closure: the lovers'' reunion is revealed as Briony''s invention, and the novel ends not with resolution but with the dying author''s confession of authorial power.', 'Both novels stage their endings as moral arguments, but where Dickens distributes a chastened justice, McEwan withholds even the consolation of a stable narrative.', '{}'::text[], NULL, 't'::boolean, '109'::integer, 'Dickens''s apostrophic direct address to the reader (''Dear reader! It rests with you and me…'') vs McEwan''s first-person metafictional turn that names itself as fiction.', 'Victorian generic expectation of distributed poetic justice vs late-twentieth-century postmodern suspicion of consoling endings (Kermode, ''The Sense of an Ending'').', 'Both novels use their endings to interrogate what fiction owes its readers — moral instruction in Dickens, honest disclosure of its own limits in McEwan.', 'Both novels stage their endings as moral arguments, but where Dickens distributes a chastened justice, McEwan withholds even the consolation of a stable narrative.', 'Louisa / Tom / Sissy in ''Garnering'' vs Briony as 1999 author-narrator', 'Direct address from a moralising narrator vs first-person revelation that reframes everything prior', 'Tripartite agricultural close vs framed coda that rewrites the whole', 'Essential for endings, closure, form, or ''how the novel resolves'' questions.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.comparative_matrix (id, axis, hard_times, atonement, divergence, themes, level_band, is_active, sort_order, ao2, ao3, ao4, thesis, "character", narrative, structure, exam_fit) VALUES ('mock-family', 'Family failure', 'The Gradgrind household substitutes statistics for affection; Mrs Gradgrind''s deathbed inability to name what is ''missing'' is the novel''s diagnosis.', 'The Tallis family''s absent father, ailing mother and rivalrous siblings produce the conditions for Briony''s accusation and Cecilia''s exile.', 'Both writers root public harm in private familial failure, but where Dickens offers Sissy as a redemptive surrogate, McEwan denies any reparative figure.', '{}'::text[], NULL, 't'::boolean, '107'::integer, 'Dickens''s pathetic, near-comic deathbed scene vs McEwan''s slow accumulation of domestic small-talk that conceals catastrophe.', 'Victorian ideology of the ''angel in the house'' vs interwar erosion of the country-house family.', 'Both novels treat the family as the first and most damaging social institution.', 'Both writers root public harm in private familial failure, but where Dickens offers Sissy as a redemptive surrogate, McEwan denies any reparative figure.', 'The Gradgrinds vs the Tallises', 'Narratorial diagnosis of the family vs immersion within its silences', 'Family as moral microcosm of society vs family as the engine of the plot''s central error', 'Use for family, women, domestic space, or ''the home'' prompts.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.comparative_matrix (id, axis, hard_times, atonement, divergence, themes, level_band, is_active, sort_order, ao2, ao3, ao4, thesis, "character", narrative, structure, exam_fit) VALUES ('mock-guilt', 'Guilt and atonement', 'Gradgrind''s late recognition of Louisa''s ruin and Tom''s crime stages a partial, private repentance the novel both grants and questions: the system that produced him is not undone.', 'Briony''s lifelong novel-writing is framed as her only available ''atonement'' — yet the 1999 coda admits the act of fiction cannot undo what was done and may itself be self-serving.', 'Where Dickens permits a chastened patriarch a measure of grace, McEwan refuses his narrator absolution and exposes atonement as a fiction the guilty tell themselves.', '{}'::text[], NULL, 't'::boolean, '103'::integer, 'Dickens''s tearful tableau and direct narratorial address vs McEwan''s metafictional confession in the coda that retroactively destabilises the reader''s trust in everything prior.', 'Victorian Christian frameworks of repentance and providential justice vs late-twentieth-century secular, psychoanalytic and post-Holocaust models of trauma and reparation.', 'Each novel asks whether private remorse can repair public harm; both refuse the easy ''yes''.', 'Where Dickens permits a chastened patriarch a measure of grace, McEwan refuses his narrator absolution and exposes atonement as a fiction the guilty tell themselves.', 'Gradgrind vs Briony', 'Authoritative narratorial judgement vs self-incriminating authorial confession', 'Moral arc resolved within the narrative vs resolution undone by the coda', 'Central for any guilt, redemption, or ''endings'' question.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.comparative_matrix (id, axis, hard_times, atonement, divergence, themes, level_band, is_active, sort_order, ao2, ao3, ao4, thesis, "character", narrative, structure, exam_fit) VALUES ('mock-imagination', 'Imagination vs rationality', 'Dickens stages Coketown''s utilitarian schoolroom as a moral wasteland: Gradgrind''s ''facts'' starve Louisa and Tom of inner life, and Sissy''s ''fancy'' becomes the novel''s ethical corrective.', 'McEwan dramatises imagination as both gift and weapon: thirteen-year-old Briony''s novelistic mind constructs a ''crime'' from fragments she does not understand, exposing how fiction-making can over-write reality.', 'Whereas Dickens condemns the suppression of imagination as a social violence, McEwan interrogates imagination itself as a morally ambiguous instrument of harm and repair.', '{}'::text[], NULL, 't'::boolean, '101'::integer, 'Set Dickens''s antithetical syntax and accumulative catalogue (''Fact, fact, fact'') against McEwan''s anaphoric free indirect drift through Briony; both weaponise rhythm and voice to expose a worldview.', '1854 Benthamite utilitarianism and the post-1846 debate over rote schooling vs late-twentieth-century scepticism about narrative authority and the reliability of memory and testimony.', 'Both novels dramatise the cost of a single dominant epistemology — empirical fact in Dickens, imaginative inference in McEwan — and route redemption through a different way of knowing.', 'Whereas Dickens condemns the suppression of imagination as a social violence, McEwan interrogates imagination itself as a morally ambiguous instrument of harm and repair.', 'Sissy / Louisa vs Briony / Cecilia', 'Omniscient moralising narrator vs free indirect + retrospective first-person frame', 'Tripartite ''Sowing / Reaping / Garnering'' agricultural arc vs four-part novel-within-a-novel with London 1999 coda', 'Strong for questions on imagination, education, narrative ethics, or ''ways of seeing''.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.comparative_matrix (id, axis, hard_times, atonement, divergence, themes, level_band, is_active, sort_order, ao2, ao3, ao4, thesis, "character", narrative, structure, exam_fit) VALUES ('mock-narrative-truth', 'Narrative truth and unreliability', 'The omniscient narrator polices truth openly, exposing Bounderby''s self-mythology and Harthouse''s seductive cynicism.', 'The London 1999 coda reveals Briony as the author of all that came before, retroactively destabilising every prior ''fact'' the reader has been given.', 'Whereas Dickens uses an authoritative narrator to enforce moral clarity, McEwan uses an unreliable one to expose narrative itself as a form of power.', '{}'::text[], NULL, 't'::boolean, '108'::integer, 'Dickens''s intrusive moralising voice vs McEwan''s framed, recursive metafictional structure that turns the novel against itself.', 'Victorian confidence in the moral narrator vs postmodern scepticism about narrative authority and historical testimony.', 'Both novels are deeply concerned with who has the right to tell the story — but reach opposite conclusions about the narrator''s reliability.', 'Whereas Dickens uses an authoritative narrator to enforce moral clarity, McEwan uses an unreliable one to expose narrative itself as a form of power.', 'Dickens-as-narrator vs Briony-as-author', 'Intrusive Victorian omniscience vs recursive metafictional first-person', 'Linear moral arc vs frame that rewrites the whole', 'Essential for narrative method, truth, or ''storytelling'' questions.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.comparative_matrix (id, axis, hard_times, atonement, divergence, themes, level_band, is_active, sort_order, ao2, ao3, ao4, thesis, "character", narrative, structure, exam_fit) VALUES ('mock-social-responsibility', 'Social responsibility', 'Stephen Blackpool''s ''muddle'' and death indict a society that abandons the labouring poor; Bounderby''s self-mythology exposes the lie of self-help.', 'Robbie Turner — the housekeeper Grace Turner''s son, sponsored through Cambridge by Jack Tallis — is wrongfully convicted of assaulting Lola; class privilege shields the Tallises and Marshall while the working-class outsider absorbs the cost through prison and the Dunkirk retreat.', 'Both writers indict a propertied class that outsources moral responsibility, but Dickens demands reform while McEwan denies even the consolation of justice.', '{}'::text[], NULL, 't'::boolean, '102'::integer, 'Set Dickens''s symbolic naming (''Bounderby'', ''Gradgrind'') and pathos-laden Lancashire dialect against McEwan''s clinical, sensory war prose (''a leg in a tree'') that refuses redemptive closure.', '1840s–50s Condition-of-England debate, Manchester industrialism and factory legislation vs 1935 country-house England, the 1940 Dunkirk evacuation and Britain''s class-stratified army.', 'Both texts trace how institutional structures (factory, courtroom, army) convert private cruelty into public catastrophe.', 'Both writers indict a propertied class that outsources moral responsibility, but Dickens demands reform while McEwan denies even the consolation of justice.', 'Stephen Blackpool / Rachael vs Robbie Turner / Cecilia', 'Sentimental third-person advocacy vs ironised, withheld first-person authorship', 'Public death scene as climactic indictment vs deferred revelation in coda', 'Use for class, justice, suffering, or ''the individual and society'' prompts.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.comparative_matrix (id, axis, hard_times, atonement, divergence, themes, level_band, is_active, sort_order, ao2, ao3, ao4, thesis, "character", narrative, structure, exam_fit) VALUES ('mock-time-memory', 'Time and memory', 'Dickens''s narrator polices time providentially: the ''Sowing / Reaping / Garnering'' arc enforces a causal, almost biblical chronology in which earlier choices determine later harvests.', 'McEwan''s structure is recursive and revisionary: the 1935 events of Part One are continually rewritten by Parts Two, Three and the 1999 coda, so memory becomes the form of the novel itself.', 'Where Dickens uses time as a providential mechanism that exposes moral truth, McEwan uses recursive memory to show that truth itself is rewritten by the act of remembering.', '{}'::text[], NULL, 't'::boolean, '110'::integer, 'Dickens''s seasonal and agricultural metaphor structuring whole sections vs McEwan''s analeptic, palimpsestic narration that overlays remembered, imagined and ''final'' versions.', 'Victorian providential historiography and a faith in legible cause-and-effect vs late-twentieth-century post-Holocaust scepticism about memory, testimony and the historical record.', 'Both novels treat time as moral architecture, but reach opposing conclusions: in Dickens time discloses truth, in McEwan time reveals only further versions of it.', 'Where Dickens uses time as a providential mechanism that exposes moral truth, McEwan uses recursive memory to show that truth itself is rewritten by the act of remembering.', 'Gradgrind across the three books vs Briony across 1935, 1940, 1999', 'Linear, chaptered omniscience vs analepsis, revision and framed retrospection', 'Tripartite providential arc vs four-part recursive structure with coda', 'Use for time, memory, structure, or ''how the form shapes meaning'' questions.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.comparative_matrix (id, axis, hard_times, atonement, divergence, themes, level_band, is_active, sort_order, ao2, ao3, ao4, thesis, "character", narrative, structure, exam_fit) VALUES ('mock-war', 'War and industrial systems', 'Coketown is a war on the body: smoke ''serpents'', mechanical pistons, and the workers reduced to ''Hands'' frame industry as a slow violence.', 'Part Two''s Dunkirk sequence, focalised through Robbie as a private in the BEF, renders modern war as bureaucratic, sensory chaos — bodies in trees, a child''s leg, a parataxis of detail that strips away patriotic myth.', 'Both writers expose the human cost of impersonal systems, but Dickens still believes in moral protest where McEwan registers only survival and witness.', '{}'::text[], NULL, 't'::boolean, '106'::integer, 'Dickens''s animating metaphors that make machines monstrous (''serpents of smoke'', ''elephants in melancholy madness'') vs McEwan''s paratactic, documentary-realist accumulation of detail that resists symbolism.', 'Industrial Revolution and the ''Condition of England'' vs the Second World War, Dunkirk myth, and post-war reckoning.', 'Both treat large-scale systems — factory and army — as machines that grind down individual bodies and meanings.', 'Both writers expose the human cost of impersonal systems, but Dickens still believes in moral protest where McEwan registers only survival and witness.', 'Coketown ''Hands'' vs Robbie and the retreating soldiers', 'Symbolic, moralising panorama vs immersive, fragmented sensory realism', 'Industrial setting as continuous backdrop vs war as discrete, central Part Two', 'Use for setting, violence, systems, or environment-of-the-novel questions.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.character_cards (id, source_text, name, one_line, themes, core_function, complication, structural_role, comparative_link, common_misreading) VALUES ('char-at-briony', 'AT', 'Briony Tallis', 'Aspiring writer whose false testimony destroys two lives and who spends the rest writing towards impossible atonement', '{authorship,childhood,endings,gender,guilt,imagination}'::text[], 'Simultaneously protagonist, unreliable narrator and authorial surrogate; her false testimony drives the entire plot; her writing of the novel is her attempt at atonement — and perhaps a final act of narrative self-possession.', 'Her retrospective honesty remains morally ambiguous — McEwan refuses to settle whether the novel itself is genuine guilt or a last self-serving narrative; the question cannot be resolved.', 'Controlling consciousness whose unreliability is the novel''s central structural and ethical device; her perspective frames every section until the Epilogue strips away its authority.', 'Louisa Gradgrind in Hard Times — both are protagonists shaped by formative environments seeking self-reckoning; but where Louisa is victim of others'' ideology, Briony is perpetrator and self-appointed author.', 'Avoid reading Briony as either wholly guilty or wholly sympathetic — McEwan maintains deliberate ambiguity about the moral weight of her authorship as both confession and appropriation.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.character_cards (id, source_text, name, one_line, themes, core_function, complication, structural_role, comparative_link, common_misreading) VALUES ('char-at-cecilia', 'AT', 'Cecilia Tallis', 'Briony''s older sister whose love for Robbie is destroyed by the false testimony she cannot challenge from within her own family', '{authorship,childhood,class,family,gender}'::text[], 'Her love for Robbie is the emotional centre of the novel; her estrangement from her family shows how one act of false testimony destroys entire networks of relationship.', 'Her death in the Balham bombing, revealed in the Epilogue, retroactively reframes all of Part 3 — even Briony''s imagined reconciliation was fictionalised, denying the reader the consolation McEwan had appeared to offer.', 'Emotional centre whose retrospective loss undoes Briony''s attempted atonement by revealing Part 3 as fiction within fiction — she cannot be restored even in writing.', 'Sissy Jupe in Hard Times — both represent authentic feeling and emotional intelligence against repressive structures, but Cecilia is more complex and ultimately unprotected where Sissy survives.', 'Avoid treating Cecilia as simply a love interest — her intellectual independence, class self-awareness and principled response to Briony''s lie are thematically essential for AO4 comparison.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.character_cards (id, source_text, name, one_line, themes, core_function, complication, structural_role, comparative_link, common_misreading) VALUES ('char-at-lola', 'AT', 'Lola Quincey', 'Briony''s cousin whose complicity in Robbie''s false accusation becomes McEwan''s darkest portrait of class and self-interest silencing truth', '{authorship,class,gender,guilt,justice}'::text[], 'Her complicity — accepting Briony''s identification of Robbie rather than naming Paul — is morally complex; her marriage to her rapist is McEwan''s most damning image of how class protects the guilty and silences the vulnerable.', 'Lola is simultaneously victim (of Marshall''s assault) and perpetrator (of Robbie''s false accusation) — her moral ambiguity is irreducible and McEwan does not resolve it.', 'Structural pivot whose silence enables injustice; her eventual status as Marshall''s wealthy wife is the novel''s sharpest image of class sealing injustice permanently and profitably.', 'Mrs Sparsit in Hard Times (darkly) — both are female characters complicit within class systems, but Lola is a genuinely tragic figure where Sparsit is primarily satiric and relatively harmless.', 'Do not read Lola as simply a secondary victim — her agency in protecting Marshall (and herself) from exposure is morally significant and exam-relevant for AO4 comparison questions.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.character_cards (id, source_text, name, one_line, themes, core_function, complication, structural_role, comparative_link, common_misreading) VALUES ('char-at-marshall', 'AT', 'Paul Marshall', 'Chocolate-fortune heir and Lola''s rapist who escapes all consequences because class privilege insulates him from suspicion', '{authorship,childhood,class,justice,morality}'::text[], 'The novel''s true antagonist — his crime is displaced onto Robbie by Briony''s false testimony; he escapes all consequences because his class position makes his guilt unthinkable to the Tallis household.', 'His Amo bars appearing on the French battlefield remind us that Paul''s power and Robbie''s suffering coexist historically — McEwan makes war profit and personal injustice structurally connected.', 'True villain whose immunity from punishment is the novel''s most systemic critique of class-protected power; his blandness is not shallow characterisation but deliberate — the banal face of privilege.', 'Bounderby in Hard Times — both embody corrupt ideology, exploit the vulnerable, and escape moral consequence; Bounderby is a loud, self-congratulatory fraud, Marshall is quiet and socially polished.', 'Marshall is consistently underweighted in student essays — foregrounding him as the true antagonist and explaining why class conceals him is a powerful A* analytical move.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.character_cards (id, source_text, name, one_line, themes, core_function, complication, structural_role, comparative_link, common_misreading) VALUES ('char-at-robbie', 'AT', 'Robbie Turner', 'Cambridge graduate whose class position leaves him uniquely vulnerable to Briony''s false accusation and its irreversible consequences', '{authorship,childhood,class,justice,morality}'::text[], 'The novel''s moral innocent — destroyed by a child''s misreading and a class system that makes his word unequal to hers; his death in war is the ultimate consequence of Briony''s false testimony.', 'His letters and internal monologue in Part 2 reveal a passionate, articulate inner life that contrasts devastatingly with how the Tallis family reduces and punishes him.', 'Moral victim whose absence from Part 3 (we read Briony''s reconstruction) and death in the Epilogue retroactively undermine all of Briony''s attempted reparation.', 'Stephen Blackpool in Hard Times — both are innocent men destroyed by systems they cannot control; Stephen by class and law, Robbie by class and a child''s misreading of adult sexuality.', 'Do not read Robbie as a purely passive victim — his letter to Cecilia, his agency in France, and his emotional resilience show active moral and psychological life that class tries to erase.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.character_cards (id, source_text, name, one_line, themes, core_function, complication, structural_role, comparative_link, common_misreading) VALUES ('char-ht-bounderby', 'HT', 'Josiah Bounderby', 'Factory owner whose fabricated self-made myth satirises the ideology of meritocracy', '{authorship,class,justice,morality,war}'::text[], 'Satirises the myth of meritocracy; his exposure as a fraud — inventing an abusive childhood he never had — undermines the ideological claim that capitalism rewards virtue and effort.', 'His exposure is narratively satisfying but does not change the conditions he represents — Dickens''s critique goes beyond individual hypocrisy to systemic ideology.', 'Ideological antagonist whose fraudulent self-myth is exposed to discredit the ruling-class narrative of self-improvement; his treatment of workers as "Hands" is the systemic face of the same dehumanisation.', 'Paul Marshall in Atonement — both embody corrupt ideology, exploit the vulnerable, and escape full moral consequence; Bounderby is loud fraud, Marshall is quiet predator.', 'Avoid treating Bounderby as comic relief — his satire carries real ideological critique about industrial capitalism and the myth of self-improvement that Dickens expects the reader to identify.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.character_cards (id, source_text, name, one_line, themes, core_function, complication, structural_role, comparative_link, common_misreading) VALUES ('char-ht-gradgrind', 'HT', 'Thomas Gradgrind', 'Utilitarian school superintendent whose fact-based system deforms his own children', '{childhood,class,education,guilt,morality}'::text[], 'Embodies Dickens''s critique of Utilitarian philosophy; his arc from rigid believer to broken, penitent father is the novel''s central moral argument.', 'His repentance shows the system can be escaped, but only at great cost to those it has already damaged — Dickens does not offer easy redemption.', 'Moral antagonist whose conversion provides the climactic turning point; his ideology creates the conditions for every other character''s suffering.', 'Emily and Jack Tallis in Atonement — authority figures whose ideologies (Utilitarianism vs class snobbery) create conditions for injustice through absence, ideology and negligence.', 'Not simply a villain — his system is sincerely held and his repentance genuine. Reducing him to a caricature loses the ideological depth Dickens requires at A/A*.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.character_cards (id, source_text, name, one_line, themes, core_function, complication, structural_role, comparative_link, common_misreading) VALUES ('char-ht-harthouse', 'HT', 'James Harthouse', 'Idle aristocrat who pursues Louisa not from passion but from boredom, embodying the corruption of the ruling class', '{class,gender,morality}'::text[], 'Represents the idle ruling class — charm without substance, power without responsibility; his pursuit of Louisa is motivated entirely by ennui, making him a different and equally damning indictment to Bounderby.', 'His easy capitulation when confronted by Sissy reveals essential shallowness — unlike Gradgrind or Bounderby, he has no sustaining ideology at all, only indifference.', 'Antagonist whose approach to Louisa reveals the external danger she faces from male social power; his amorality contrasts with Gradgrind''s sincere (if damaging) ideology.', 'Paul Marshall in Atonement — both are socially privileged men who exploit female vulnerability with social impunity; Harthouse operates through charm and ennui, Marshall through active predation.', 'Harthouse is underweighted in many student essays — his cynical amorality is conceptually distinct from Bounderby''s fraudulent ideology and equally revealing about class power.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.character_cards (id, source_text, name, one_line, themes, core_function, complication, structural_role, comparative_link, common_misreading) VALUES ('char-ht-louisa', 'HT', 'Louisa Gradgrind', 'Gradgrind''s eldest daughter whose emotional repression becomes the novel''s central moral tragedy', '{childhood,education,gender,guilt,imagination,morality}'::text[], 'Dramatises the cost of fact-based education on the human heart; her collapse before her father is the novel''s moral turning point and its clearest indictment of Gradgrind''s system.', '"A fire with nothing to burn" — her imagery reveals vitality the system cannot destroy but also cannot channel; she is victim and suppressed moral agent simultaneously.', 'Protagonist whose arc charts the full damage of Gradgrind''s system from suppression to crisis to incomplete recovery — Dickens deliberately refuses a clean resolution.', 'Briony Tallis in Atonement — both are protagonists shaped by formative environments seeking belated self-reckoning; but where Louisa is victim of others'' ideology, Briony is perpetrator of her own imaginative excess.', 'Avoid reducing Louisa to a passive victim — her intelligence, suppressed imagination and final refusal of Harthouse make her active within the constraints Dickens sets.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.character_cards (id, source_text, name, one_line, themes, core_function, complication, structural_role, comparative_link, common_misreading) VALUES ('char-ht-sissy', 'HT', 'Cecilia (Sissy) Jupe', 'Circus girl whose empathy and imagination function as the moral corrective to Gradgrind''s fact-based system', '{childhood,education,family,imagination,morality}'::text[], 'The embodiment of "Fancy"; she saves the Gradgrind family repeatedly, proving that heart and imagination are socially indispensable — and that her education (circus life, her father''s warmth) has produced what Gradgrind''s cannot.', 'Her consistent idealisation limits her as a character — she is more symbol than psychologically realised person, which some critics find aesthetically reductive even if ideologically effective.', 'Moral ideal whose circus background represents the alternative, humanising world that Gradgrind''s system denies; her presence is Dickens''s structural argument for the redemptive power of imagination.', 'Partially Cecilia Tallis in Atonement — both represent authentic feeling against repressive structures, but Sissy is consistently idealised whereas Cecilia is more ambiguous and ultimately unprotected.', 'Sissy is not simply naturally good or lucky — her empathy is the specific product of an alternative upbringing that Gradgrind cannot replicate; this distinction matters for AO3 context analysis.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.character_cards (id, source_text, name, one_line, themes, core_function, complication, structural_role, comparative_link, common_misreading) VALUES ('char-ht-stephen', 'HT', 'Stephen Blackpool', 'Factory worker whose honesty and class vulnerability make him the novel''s working-class moral centre', '{childhood,class,justice,morality,war}'::text[], 'The novel''s working-class moral centre; his death is Dickens''s indictment of a system that destroys its most decent members while protecting the dishonest and powerful.', 'Critics note he is almost saintly to the point of passivity — some argue this softens the political critique and makes the working class a symbolic rather than political force.', 'Innocent victim who cannot escape the triple trap of marriage law, union expulsion, and class stigma; his death converts individual injustice into systemic indictment.', 'Robbie Turner in Atonement — both are innocent men destroyed by systems they cannot control; Stephen by class and law, Robbie by class and a child''s misreading of adult sexuality.', 'Do not read Stephen as merely representing suffering labour — his individual moral seriousness and refusal to betray others is what makes his victimisation so damning.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quotes (id, text, attribution, location, source, word_analysis, a_star_insight, anchor_id, paired_anchor_id, is_verified, ao_tags, theme_tags) VALUES ('164a775b-1153-4cc6-8e3d-6afb4ad4d365'::uuid, 'People mutht be amuthed.', 'Mr Sleary', 'Book III, Ch. 8 — close', 'hard-times', 'The lisped sibilants (''mutht'', ''amuthed'') refuse Gradgrindian propriety; the modal ''must'' delivers a counter-creed.', 'A*: the sentence''s broken phonetics enact what it argues — pleasure exceeds standard form.', 'ht-11', 'at-4', 't'::boolean, '{AO2}'::text[], '{imagination}'::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quotes (id, text, attribution, location, source, word_analysis, a_star_insight, anchor_id, paired_anchor_id, is_verified, ao_tags, theme_tags) VALUES ('1bdae9f3-2814-4e29-b58d-6a17a42676a9'::uuid, 'Girl number twenty', 'M''Choakumchild / Gradgrind (of Sissy Jupe)', 'Book I, Ch. 2', 'hard-times', '''Number'' substitutes a numeral for a name; ''girl'' is a category, not a person.', 'A*: a two-word phrase carries the novel''s whole pedagogical critique.', 'ht-6', 'at-1', 't'::boolean, '{AO2,AO3}'::text[], '{education}'::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quotes (id, text, attribution, location, source, word_analysis, a_star_insight, anchor_id, paired_anchor_id, is_verified, ao_tags, theme_tags) VALUES ('29d2005c-0703-4aa7-9bfd-1b9a09da0518'::uuid, 'The cottage at Bray Dunes — Robbie finds the bodies of two children, the twins, killed by bombing on the road north (Part Two atrocity anchor; verify exact wording before citing).', 'Free indirect (Robbie)', 'Part Two — retreat to Dunkirk', 'atonement', 'Short noun-phrases catalogue the scene without subordination; the children are named only by relation (''twins''), refusing biographical consolation.', 'A*: McEwan refuses elegy — the parataxis is the ethics; pathos would falsify the witness.', 'at-11', 'ht-9', 'f'::boolean, '{AO2,AO3}'::text[], '{war}'::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quotes (id, text, attribution, location, source, word_analysis, a_star_insight, anchor_id, paired_anchor_id, is_verified, ao_tags, theme_tags) VALUES ('45e58547-487f-4a59-b221-0dfa001eb2e7'::uuid, 'Coketown lay shrouded in a haze of its own.', 'Narrator', 'Book II, Ch. 1', 'hard-times', '''Shrouded'' carries funereal weight; ''its own'' makes the haze self-generated, complicit.', 'A* readers connect the haze to Gradgrind''s epistemological fog — fact-worship blinds.', 'ht-5', 'at-5', 'f'::boolean, '{AO2,AO3}'::text[], '{imagination}'::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quotes (id, text, attribution, location, source, word_analysis, a_star_insight, anchor_id, paired_anchor_id, is_verified, ao_tags, theme_tags) VALUES ('4a4533fa-796d-4fc0-9417-22639a64f823'::uuid, 'the piston of the steam-engine worked monotonously up and down, like the head of an elephant in a state of melancholy madness.', 'Narrator', 'Book I, Ch. 5 — Coketown', 'hard-times', '''Monotonously'' enacts the rhythm it describes; ''melancholy madness'' grants the machine an inner life it should not have.', 'A*: Dickens imports madness into the machine to extract it from the worker.', 'ht-9', 'at-5', 't'::boolean, '{AO2}'::text[], '{war}'::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quotes (id, text, attribution, location, source, word_analysis, a_star_insight, anchor_id, paired_anchor_id, is_verified, ao_tags, theme_tags) VALUES ('56ea194f-ee3b-4abd-aaac-35a0e38fc0e1'::uuid, 'What do I know, father, of tastes and fancies; of aspirations and affections; of all that part of my nature in which such light things might have been nourished?', 'Louisa Gradgrind (to her father)', 'Book II, Ch. 12', 'hard-times', 'The triad ''tastes... aspirations... affections'' inventories what was withheld; the conditional ''might have been'' marks the loss as structural.', 'A*: Louisa''s confrontation indicts utilitarian pedagogy in its own register — the system is rebuked by its product.', 'ht-10', 'at-4', 'f'::boolean, '{AO2,AO4}'::text[], '{childhood}'::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quotes (id, text, attribution, location, source, word_analysis, a_star_insight, anchor_id, paired_anchor_id, is_verified, ao_tags, theme_tags) VALUES ('601f9bed-f1f7-455e-8b2e-de4281427292'::uuid, 'interminable serpents of smoke', 'Narrator', 'Book I, Ch. 5 — Coketown', 'hard-times', 'The single noun ''serpents'' loads industrial smoke with Edenic guilt; ''interminable'' refuses temporal escape.', 'A*: the biblical register quietly moralises industrial ecology.', 'ht-8', 'at-5', 't'::boolean, '{AO2,AO3}'::text[], '{war}'::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quotes (id, text, attribution, location, source, word_analysis, a_star_insight, anchor_id, paired_anchor_id, is_verified, ao_tags, theme_tags) VALUES ('61bb01ad-5de7-4edc-b874-7b07e2978bd6'::uuid, 'Now, what I want is, Facts. Teach these boys and girls nothing but Facts.', 'Thomas Gradgrind', 'Book I, Ch. 1 — opening', 'hard-times', 'Capitalising the single word ''Facts'' reifies an abstraction into a creed; the imperative ''Teach'' is monologic.', 'A* readers note Dickens performs the very didacticism he critiques — narrator and Gradgrind share a register.', 'ht-1', 'at-1', 't'::boolean, '{AO1,AO2}'::text[], '{education}'::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quotes (id, text, attribution, location, source, word_analysis, a_star_insight, anchor_id, paired_anchor_id, is_verified, ao_tags, theme_tags) VALUES ('62d0ecd2-596d-4a29-953d-5e5b8ab06457'::uuid, 'The leg in the tree — Robbie encounters a child''s severed leg lodged in a tree on the road to Bray Dunes (Part Two atrocity image; verify exact wording before citing).', 'Free indirect (Robbie)', 'Part Two — road to Bray Dunes', 'atonement', 'The isolated body part — ''leg'' — substitutes for the whole child; quiet noun-phrase syntax displaces moral commentary onto the reader.', 'A*: McEwan''s restraint here is itself a method — synecdoche as ethical refusal of spectacle.', 'at-5', 'ht-5', 'f'::boolean, '{AO2,AO3}'::text[], '{war}'::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quotes (id, text, attribution, location, source, word_analysis, a_star_insight, anchor_id, paired_anchor_id, is_verified, ao_tags, theme_tags) VALUES ('64a10809-f77e-4ed5-81a2-834dd9dcce93'::uuid, 'It was a town of red brick, or of brick that would have been red if the smoke and ashes had allowed it.', 'Narrator', 'Book I, Ch. 5 — Coketown', 'hard-times', 'The counterfactual ''would have been'' suspends the word ''red'' — industry has erased the natural state before it can be named.', 'A* candidates argue Dickens''s grammar enacts erasure — the sentence withdraws the colour it offers.', 'ht-2', 'at-5', 't'::boolean, '{AO2,AO3}'::text[], '{war}'::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quotes (id, text, attribution, location, source, word_analysis, a_star_insight, anchor_id, paired_anchor_id, is_verified, ao_tags, theme_tags) VALUES ('706b507e-7bf0-4424-b902-fa80f86021cf'::uuid, 'Briony''s library scene — she enters, sees Cecilia and Robbie in the half-dark, and reads the encounter as assault (Part One library anchor; verify exact wording before citing).', 'Free indirect (Briony)', 'Part One, Ch. 10', 'atonement', 'The library is staged as proscenium — doorway, low light, two figures — so that Briony reads bodies as tableau; perception is pre-scripted by the genres she already writes in.', 'A*: the misreading is generic, not perceptual — Briony has the wrong literary frame, not bad eyes.', 'at-8', 'ht-10', 'f'::boolean, '{AO2}'::text[], '{memory}'::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quotes (id, text, attribution, location, source, word_analysis, a_star_insight, anchor_id, paired_anchor_id, is_verified, ao_tags, theme_tags) VALUES ('710fd848-387c-46a1-b956-7f82ea8c1469'::uuid, 'Luc Cornet at St Thomas''s — the dying French soldier whom Briony, as student nurse, attends and to whom she gives a name and a promise she cannot keep (Part Three anchor; verify exact wording before citing).', 'Free indirect (Briony) / Luc Cornet', 'Part Three — St Thomas''s Hospital, wartime London', 'atonement', 'The proper name ''Luc'' is offered as the only thing Briony can give; clinical noun-phrases of nursing displace the impossibility of consolation.', 'A*: the scene rehearses the coda''s question — atonement is offered to a substitute because the real addressee has been foreclosed.', 'at-9', 'ht-3', 'f'::boolean, '{AO2}'::text[], '{justice}'::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quotes (id, text, attribution, location, source, word_analysis, a_star_insight, anchor_id, paired_anchor_id, is_verified, ao_tags, theme_tags) VALUES ('79ea51e9-1632-44c0-8031-4151ab7c6dd6'::uuid, 'The cost of oblivious daydreaming was always this moment of return, the realignment with what had been before.', 'Free indirect (Briony)', 'Part One, Ch. 3', 'atonement', 'The nominalised ''realignment'' is clinical and distancing; the word ''cost'' financialises consciousness.', 'A* / critical perspective: trauma theory (associated with Caruth and LaCapra) frames memory as belated, fractured and ethically unstable — useful interpretive nuance for the word ''realignment'', which anticipates the novel''s recursive structure as Briony keeps re-aligning.', 'at-2', NULL, 't'::boolean, '{AO2}'::text[], '{memory}'::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quotes (id, text, attribution, location, source, word_analysis, a_star_insight, anchor_id, paired_anchor_id, is_verified, ao_tags, theme_tags) VALUES ('85f68883-e79a-4ff0-8b9e-51b44ba0114f'::uuid, 'She was one of those children possessed by a desire to have the world just so.', 'Free indirect (Briony)', 'Part One, Ch. 1', 'atonement', 'The single word ''possessed'' is ambivalent — gifted or haunted; ''just so'' fuses aesthetic order with moral control.', 'A* point: McEwan plants the novel''s metafictional thesis in its first character description.', 'at-1', 'ht-1', 't'::boolean, '{AO2}'::text[], '{imagination}'::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quotes (id, text, attribution, location, source, word_analysis, a_star_insight, anchor_id, paired_anchor_id, is_verified, ao_tags, theme_tags) VALUES ('9828f958-cff7-40b4-85d8-972d8bb6f5ac'::uuid, 'The Trials of Arabella — Briony''s homemade play, written, cast and directed by her for her brother Leon''s homecoming (Part One opening anchor; verify exact wording before citing).', 'Free indirect (Briony) / narrator', 'Part One, Ch. 1', 'atonement', 'The mock-archaic title ''Trials'' doubles as judicial test and dramatic ordeal; Arabella''s tidy moral arc previews Briony''s lifelong wish to script consequence.', 'A*: the play is the novel in miniature — Briony is already rehearsing the authorial god-position the coda will indict.', 'at-6', 'ht-1', 'f'::boolean, '{AO2}'::text[], '{imagination}'::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quotes (id, text, attribution, location, source, word_analysis, a_star_insight, anchor_id, paired_anchor_id, is_verified, ao_tags, theme_tags) VALUES ('b5716efb-e9a3-4286-85c2-754d43750c86'::uuid, 'Robbie''s misdelivered letter to Cecilia — the obscene draft sent in error in place of the formal apology (Part One letter-scene anchor; explicit wording withheld; verify before citing).', 'Free indirect (Robbie / Briony as reader)', 'Part One, Ch. 8–10', 'atonement', 'The letter as physical object carries the plot; the collision of registers — Cambridge formality against a single transgressive lexeme — is what Briony reads as evidence.', 'A*: McEwan makes the novel''s catastrophe turn on a textual artefact — the form indicts the act of reading itself.', 'at-7', 'ht-3', 'f'::boolean, '{AO2,AO3}'::text[], '{justice}'::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quotes (id, text, attribution, location, source, word_analysis, a_star_insight, anchor_id, paired_anchor_id, is_verified, ao_tags, theme_tags) VALUES ('b734b12d-3764-4dab-bb30-24fcd279109c'::uuid, 'No little Gradgrind had ever seen a face in the moon...', 'Narrator (of the Gradgrind children)', 'Book I, Ch. 3', 'hard-times', 'The diminutive ''little'' rubs against the surname ''Gradgrind'' — the system has already named the child as its product.', 'A* point: Dickens uses negation to dramatise psychological withdrawal — the absent moon-face stands in for the absent inner life.', 'ht-4', 'at-1', 'f'::boolean, '{AO2,AO4}'::text[], '{childhood}'::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quotes (id, text, attribution, location, source, word_analysis, a_star_insight, anchor_id, paired_anchor_id, is_verified, ao_tags, theme_tags) VALUES ('bf3650b9-df41-406d-8c0e-7ee8ab12dc79'::uuid, 'little pitchers', 'Narrator (of the schoolroom children)', 'Book I, Ch. 2', 'hard-times', '''Pitchers'' figures children as empty vessels to be filled with fact; ''little'' infantilises and objectifies in the same breath.', 'A*: the metaphor exposes utilitarian pedagogy''s category error — minds are not containers.', 'ht-7', 'at-1', 't'::boolean, '{AO2}'::text[], '{childhood}'::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quotes (id, text, attribution, location, source, word_analysis, a_star_insight, anchor_id, paired_anchor_id, is_verified, ao_tags, theme_tags) VALUES ('dc9368f2-da01-4fa3-a387-9127b49ab034'::uuid, 'Anchor: Briony''s final reflection in the 1999 coda that atonement through fiction is an impossible task, and that this impossibility is precisely the ethical point — verify exact wording before citing.', 'Briony (London, 1999)', 'Part Four — coda, London 1999', 'atonement', 'The locator turns on a universalising adverb (''always'') paired with an analytic intensifier (''precisely'') — atonement is redefined as a structural condition, not an event.', 'A*: the sentence is the novel''s thesis in miniature — impossibility is not a failure of atonement but its definition.', 'at-10', 'ht-11', 'f'::boolean, '{AO2,AO4}'::text[], '{justice}'::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quotes (id, text, attribution, location, source, word_analysis, a_star_insight, anchor_id, paired_anchor_id, is_verified, ao_tags, theme_tags) VALUES ('dd779a47-0bfd-45d0-a92b-a651b1818c01'::uuid, '''Tis aw a muddle! Fro'' first to last, a muddle!', 'Stephen Blackpool', 'Book II, Ch. 5/6 — industrial relations chapters', 'hard-times', 'Eye-dialect ''aw'' and ''Fro'''' marks Stephen as outside standard discourse; the epizeuxis on ''muddle'' refuses analytic clarity.', 'Critical perspective: Marxist readings suggest Stephen is denied the diagnostic language of his own oppression, while sentimental critics see saintly martyrdom.', 'ht-3', 'at-3', 't'::boolean, '{AO2}'::text[], '{class}'::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quotes (id, text, attribution, location, source, word_analysis, a_star_insight, anchor_id, paired_anchor_id, is_verified, ao_tags, theme_tags) VALUES ('e18646be-b457-4ca2-b2e5-ddd8fbc977c1'::uuid, 'Briony''s testimony scene — her insistence that she has seen what she has only inferred (Briony''s testimony anchor; verify exact wording before citing).', 'Briony (testimony)', 'Part One, Ch. 13', 'atonement', 'Clipped clauses in the scene perform certainty; the repeated verb ''saw'' fetishises witness over fact.', 'A*: McEwan stages perjury as performative grammar, not lie — language constitutes the wrong.', 'at-3', 'ht-3', 'f'::boolean, '{AO2}'::text[], '{justice}'::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quotes (id, text, attribution, location, source, word_analysis, a_star_insight, anchor_id, paired_anchor_id, is_verified, ao_tags, theme_tags) VALUES ('f941cefd-edb6-4f76-a485-d8ac4c381eae'::uuid, 'How can a novelist achieve atonement when, with her absolute power of deciding outcomes, she is also God?', 'Briony (London, 1999)', 'Part Four — coda', 'atonement', '''Absolute power'' is doubly ironic — fictional omnipotence cannot redeem real harm.', 'A*: the question is unanswerable by design — the novel''s form IS its argument about atonement.', 'at-4', 'ht-1', 't'::boolean, '{AO2}'::text[], '{justice}'::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.theses (id, route_id, theme_family, level, thesis_text, paragraph_job_1_label, paragraph_job_2_label, paragraph_job_3_label) VALUES ('thesis-childhood-a', 'route-imagination', 'childhood', 'strong', 'Both novels present childhood as a formative stage, but Dickens focuses on the damage caused by fact-based education while McEwan explores the danger of imaginative misreading.', 'Dickens''s utilitarian system and its effects on child development (AO1/AO2)', 'McEwan''s imaginative overreading: Briony''s "rehearsal of order" (AO2/AO4)', 'How both authors connect early formation to later moral damage (AO3/AO4)') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.theses (id, route_id, theme_family, level, thesis_text, paragraph_job_1_label, paragraph_job_2_label, paragraph_job_3_label) VALUES ('thesis-childhood-astar', 'route-imagination', 'childhood', 'top_band', 'Both Hard Times and Atonement present childhood less as innocence than as formation, though Dickens attacks ideological systems that train feeling out of the child while McEwan exposes the danger of imaginative authority without ethical maturity, so that both novels connect early formation to later moral damage.', 'The mechanisms of formation: institutional ideology (HT) vs imaginative self-authorisation (AT)', 'The costs of formation: emotional sterility (Louisa) vs interpretive violence (Briony)', 'Whether formation can be escaped or only retrospectively narrated — and what that implies') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.theses (id, route_id, theme_family, level, thesis_text, paragraph_job_1_label, paragraph_job_2_label, paragraph_job_3_label) VALUES ('thesis-childhood-b', 'route-imagination', 'childhood', 'secure', 'Both novels show that childhood is important and that early experiences affect characters later in life.', 'How early education shapes Louisa and Briony', 'What the consequences of formation are in each novel', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.theses (id, route_id, theme_family, level, thesis_text, paragraph_job_1_label, paragraph_job_2_label, paragraph_job_3_label) VALUES ('thesis-class-a', 'route-class', 'class', 'strong', 'Both novels present class as restrictive, but Dickens focuses on industrial division while McEwan focuses on social prejudice and hierarchy.', 'Dickens''s industrial class system: "Hands," Bounderby, Stephen (AO2/AO3)', 'McEwan''s credibility hierarchy: Robbie vs Tallis family; Marshall''s immunity (AO2/AO4)', 'How each novel positions the reader to judge the class system — authorial method compared (AO1/AO4)') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.theses (id, route_id, theme_family, level, thesis_text, paragraph_job_1_label, paragraph_job_2_label, paragraph_job_3_label) VALUES ('thesis-class-astar', 'route-class', 'class', 'top_band', 'Both novels expose class as a structure of exclusion, but Dickens represents it through industrial dehumanisation whereas McEwan presents it through the unequal distribution of credibility, suggesting that hierarchy governs not only social place but who has the authority to define reality.', '"Girl number twenty" and "Maniac": how labelling creates social fact in both novels (AO2)', 'Fabrication as social fact: Bounderby''s myth and Briony''s testimony — parallel mechanisms of false authority (AO2/AO3)', 'The comparative judgement: industrial exclusion vs epistemic exclusion — which is more damaging? (AO4 / thesis quality)') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.theses (id, route_id, theme_family, level, thesis_text, paragraph_job_1_label, paragraph_job_2_label, paragraph_job_3_label) VALUES ('thesis-class-b', 'route-class', 'class', 'secure', 'Both novels show that class affects people''s lives.', 'Class in Hard Times: industrial hierarchy and meritocracy myth', 'Class in Atonement: prejudice and social credibility', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.theses (id, route_id, theme_family, level, thesis_text, paragraph_job_1_label, paragraph_job_2_label, paragraph_job_3_label) VALUES ('thesis-education-astar', 'route-imagination', 'education', 'top_band', 'Both Hard Times and Atonement present education as moral formation rather than neutral instruction: Dickens attacks a utilitarian system that trains children to distrust fancy and feeling, while McEwan shows Briony schooling herself through genre, class assumption and narrative certainty, so that both novels ask whether learning produces ethical perception or disciplined misreading.', 'Gradgrind''s facts-only schooling: how education becomes ideological training rather than humane formation', 'Briony''s literary self-education: how narrative habits turn perception into false certainty', 'Comparative judgement: education as moral re-education, from Dickens''s reformable Gradgrind to McEwan''s belated and incomplete atonement') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.theses (id, route_id, theme_family, level, thesis_text, paragraph_job_1_label, paragraph_job_2_label, paragraph_job_3_label) VALUES ('thesis-guilt-a', 'route-guilt', 'guilt', 'strong', 'Both novels present guilt as powerful, but Dickens uses it to show moral consequence while McEwan shows how guilt continues over time and resists resolution.', 'Dickens: guilt within moral structure — Gradgrind''s repentance; Louisa''s crisis (AO2)', 'McEwan: guilt as retrospective burden — "was not forgiveness"; the fiction of Part 3 (AO2/AO3)', 'Whether either novel allows moral repair — comparative judgement on guilt''s resolution (AO4)') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.theses (id, route_id, theme_family, level, thesis_text, paragraph_job_1_label, paragraph_job_2_label, paragraph_job_3_label) VALUES ('thesis-guilt-astar', 'route-guilt', 'guilt', 'top_band', 'Both novels present guilt as enduring in its consequences, but Dickens places it within a moral structure that links social failure to suffering, whereas McEwan renders it as a retrospective burden that narrative cannot finally erase, thereby questioning whether atonement can ever move beyond imaginative reconstruction.', 'Belated recognition compared: modal uncertainty (Louisa) vs reflective qualification (Briony) — AO2 method', 'Whether revelation has corrective power: "He was not so honest" (Dickens restores clarity) vs "I gave them happiness" (McEwan exposes insufficiency)', 'The larger implication: does either novel believe moral repair is possible? Interpretive nuance applied') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.theses (id, route_id, theme_family, level, thesis_text, paragraph_job_1_label, paragraph_job_2_label, paragraph_job_3_label) VALUES ('thesis-guilt-b', 'route-guilt', 'guilt', 'secure', 'Both novels show guilt and its consequences.', 'Guilt and consequence in Hard Times', 'Guilt and consequence in Atonement', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.theses (id, route_id, theme_family, level, thesis_text, paragraph_job_1_label, paragraph_job_2_label, paragraph_job_3_label) VALUES ('thesis-imagination-a', 'route-imagination', 'imagination', 'strong', 'Both novels explore imagination, but Dickens values it as a humane alternative to fact while McEwan also shows that storytelling can cause harm.', 'Dickens''s defence of "Fancy": circus, Sissy, the corrective power of imagination (AO2)', 'McEwan''s double view: imagination as both the source of the crime and the medium of atonement (AO2/AO4)', 'The comparative pivot: is imagination redemptive, dangerous, or both? (AO4 / argument quality)') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.theses (id, route_id, theme_family, level, thesis_text, paragraph_job_1_label, paragraph_job_2_label, paragraph_job_3_label) VALUES ('thesis-imagination-astar', 'route-imagination', 'imagination', 'top_band', 'Both novels test storytelling against reality, but while Dickens defends imaginative life against utilitarian reduction, McEwan subjects fiction itself to ethical scrutiny, suggesting that narrative may be emotionally necessary while remaining morally compromised.', '"You are never to fancy" vs "a labyrinth of construction": how each novel constructs the danger of imaginative failure or excess (AO2)', 'Performance and spectacle: "people must be amuthed" (Sleary) vs "the scene by the fountain" (Briony) — therapeutic vs distorting (AO2/AO4)', '"How can a novelist achieve atonement?" — McEwan''s metafictional interrogation vs Dickens''s narratorial confidence: what this reveals about each writer''s moral position (critical perspective)') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.theses (id, route_id, theme_family, level, thesis_text, paragraph_job_1_label, paragraph_job_2_label, paragraph_job_3_label) VALUES ('thesis-imagination-b', 'route-imagination', 'imagination', 'secure', 'Both novels show that stories and imagination are important.', 'Imagination in Hard Times: Fancy vs Facts', 'Imagination in Atonement: Briony''s storytelling', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.paragraph_jobs (id, question_family, route_id, job_title, text1_prompt, text2_prompt, divergence_prompt, judgement_prompt) VALUES ('pj-childhood-1a', 'childhood', 'route-imagination', 'Childhood as ideological formation', 'How does Gradgrind''s injunction "You are never to fancy" (absolute prohibition, modal "never") show childhood being shaped by a system that treats imagination as a defect to be drilled out?', 'How does Briony''s "labyrinth of construction" (metaphor of self-trapping architecture) show a child''s mind formed less by external prohibition than by her own elaborating imagination?', 'Dickens locates the damage of childhood in an external system that mutilates imagination; McEwan locates it in an internal faculty whose unchecked elaboration produces false certainty. Is the more dangerous force in childhood the system imposed on the child or the interpretive habit the child generates?', 'Childhood in both novels is presented as formation rather than innocence: Dickens indicts the ideological apparatus that flattens the child, while McEwan indicts the unsupervised imaginative apparatus inside the child, and the top-band reading recognises that both novels treat childhood as the site where adult harm is rehearsed.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.paragraph_jobs (id, question_family, route_id, job_title, text1_prompt, text2_prompt, divergence_prompt, judgement_prompt) VALUES ('pj-class-3a', 'class', 'route-class', 'Labels that create reality', 'How does "Girl number twenty" (numbering, synecdoche) expose institutional power as stripping away name and personhood in Dickens?', 'How does "Maniac" (loaded noun, projection) show language creating guilt through interpretive violence in McEwan?', 'Dickens makes the labelling process bureaucratic and pedagogic; McEwan makes it affective and class-inflected. Which is more insidious?', 'Social power often works first by fixing others in language and only then by treating that language as established fact.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.paragraph_jobs (id, question_family, route_id, job_title, text1_prompt, text2_prompt, divergence_prompt, judgement_prompt) VALUES ('pj-class-3b', 'critique_of_society', 'route-class', 'Fabrication as social fact', 'How does the ironic motif "Ready-to-let lodgings" expose Bounderby''s identity as rented, staged, and publicly rewarded by a capitalist culture?', 'How does Briony''s declarative "I saw him" turn psychologically contaminated perception into legally and socially accepted testimony?', 'Dickens attacks public self-mythologising; McEwan attacks the institutional force of accepted witness. In which novel is the fabrication harder to expose?', 'Falsehood becomes most dangerous when a culture is already primed to believe it — and both novels show why that priming occurs.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.paragraph_jobs (id, question_family, route_id, job_title, text1_prompt, text2_prompt, divergence_prompt, judgement_prompt) VALUES ('pj-education-1a', 'education', 'route-imagination', 'Education as moral formation', 'How does Gradgrind''s opening demand for "Facts" (capitalisation, imperative direct speech, narrowed educational register) present schooling as a system that trains children out of fancy, sympathy and uncertainty?', 'How does Briony''s desire to make experience fit a readable story pattern show an informal education in genre, class assumption and narrative control rather than mature moral perception?', 'Dickens locates educational damage in an external institution that drills the child into utilitarian fact; McEwan locates it in Briony''s internalised literary habits, where imagination becomes a self-taught method of misreading. Which version of education is more dangerous: imposed schooling or self-authorising interpretation?', 'A top-band comparison treats education in both novels as the formation of moral vision: Dickens condemns learning that excludes feeling, while McEwan exposes learning without ethical humility, and both writers make re-education belated, partial and costly.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.paragraph_jobs (id, question_family, route_id, job_title, text1_prompt, text2_prompt, divergence_prompt, judgement_prompt) VALUES ('pj-gender-4a', 'female_relationships', 'route-gender', 'Female interiority under pressure', 'How does "a fire with nothing to burn" (paradoxical metaphor) present Louisa''s inner vitality as intense but without available outlet or language?', 'How does Briony''s play as "her first rehearsal of order" (focalisation, metafiction) present female agency as present but already entangled with the desire to control?', 'Louisa is denied interpretive freedom; Briony wields it too confidently. Does either text suggest a version of female agency that avoids both traps?', 'Female agency in both novels develops under distorted social conditions — either crushed by system or corrupted by imaginative overreach.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.paragraph_jobs (id, question_family, route_id, job_title, text1_prompt, text2_prompt, divergence_prompt, judgement_prompt) VALUES ('pj-gender-4b', 'changing_relationships', 'route-gender', 'Moral self-interrogation', 'How does "Where are the graces of my soul?" (rhetorical question, vocabulary of deprivation) reveal that utilitarian formation has withheld the language needed for inner life?', 'How does "How can a novelist achieve atonement?" (metafictional question, self-interrogation) recast moral crisis as a crisis of authorship and narrative responsibility?', 'Dickens presents deprivation of moral vocabulary as the wound; McEwan presents the insufficiency of narrative as the wound. Which is more resolvable?', 'Both novels show female self-questioning revealing either the poverty of imposed systems or the insufficiency of the self''s own interpretive power.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.paragraph_jobs (id, question_family, route_id, job_title, text1_prompt, text2_prompt, divergence_prompt, judgement_prompt) VALUES ('pj-guilt-5a', 'guilt', 'route-guilt', 'Belated recognition', 'How does Louisa''s "I do not know that I am right" (modal instability) reveal a self whose capacity for judgement has been deformed by Gradgrind''s system?', 'How does Briony''s acknowledgement that writing "was not forgiveness" (reflective qualification) insist that recognition cannot undo the consequences of misreading?', 'Dickens explains failure through formation; McEwan insists on the persistence of debt even after self-awareness. Which is morally harder on its protagonist?', 'Moral consequence outlives interpretive error, whether the origin of that error is social doctrine or individual imagination.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.paragraph_jobs (id, question_family, route_id, job_title, text1_prompt, text2_prompt, divergence_prompt, judgement_prompt) VALUES ('pj-guilt-5b', 'important_choices', 'route-guilt', 'Revelation and its limits', 'How does the narrator''s correction that Bounderby "was not so honest" (blunt narrative correction) restore moral clarity and suggest that exposure has corrective power?', 'How does Briony''s "I gave them happiness" (metafictional admission, the verb "gave") reveal that narrative offers compensatory invention rather than actual repair?', 'Dickens trusts exposure to do moral work; McEwan exposes even honesty as inadequate. Does this make Atonement the more pessimistic novel?', 'Truth may expose damage, but whether that exposure can still do moral work once the damage is done is the sharpest point of divergence between the two texts.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.paragraph_jobs (id, question_family, route_id, job_title, text1_prompt, text2_prompt, divergence_prompt, judgement_prompt) VALUES ('pj-imagination-2a', 'imagination', 'route-imagination', 'Suppressed vs overactive imagination', 'How does the prohibition "You are never to fancy" (absolute prohibition, "never") show imagination as mutilated by rational system?', 'How does "A labyrinth of construction" (metaphor of entrapment) show imagination becoming so elaborate it traps Briony within its own patterns?', 'Dickens shows the damage of banning imagination; McEwan shows the damage of allowing it to dominate evidence. Does either text suggest imagination can be healthy?', 'Imagination is necessary but unstable, becoming either a starved faculty or a tyrannical one depending on the social and psychological conditions around it.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.paragraph_jobs (id, question_family, route_id, job_title, text1_prompt, text2_prompt, divergence_prompt, judgement_prompt) VALUES ('pj-imagination-2b', 'imagination', 'route-imagination', 'Performance as corrective or distortion', 'How does Sleary''s "people must be amuthed" (comic idiolect, counter-voice) present spectacle as emotional truth and corrective to utilitarian dryness?', 'How does "the scene by the fountain" (theatrical framing) show Briony reducing adult complexity to a legible staged plot?', 'Dickens sees spectacle as enlarging; McEwan sees theatricality as one of imagination''s mechanisms for falsifying reality. What does this tell us about each author''s view of art?', 'Performance can either enlarge human truth or collapse it into melodramatic misreading — the difference lies in whether it is received as metaphor or mistaken for reality.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.paragraph_jobs (id, question_family, route_id, job_title, text1_prompt, text2_prompt, divergence_prompt, judgement_prompt) VALUES ('pj-narrative-6a', 'truth', 'route-narrative', 'Who can still tell the truth?', 'How does "the triumph of fact" (deep irony — "triumph" exposing hollow victory) show Dickens using narratorial authority to correct the ideology he critiques?', 'How does "How can a novelist achieve atonement?" (destabilised authorial voice, self-interrogation) make narration part of the apparatus of harm rather than its correction?', 'Dickens trusts irony to restore moral clarity; McEwan exposes irony''s limits by making the narrator the unreliable perpetrator. Which position do you find more honest?', 'Truth may require narrative, yet narrative is itself never innocent — a conclusion neither novel fully escapes.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.paragraph_jobs (id, question_family, route_id, job_title, text1_prompt, text2_prompt, divergence_prompt, judgement_prompt) VALUES ('pj-narrative-6b', 'hope', 'route-narrative', 'Endings as moral judgement', 'How does "No little Gradgrind had ever seen a face in the moon" (retrospective summation) turn imaginative deprivation into the final measure of a whole system, giving the ending moral clarity?', 'How does "The attempt was all" (aphoristic closure, diminished ethics of effort) refuse the confidence of completed moral resolution and close on chastened insufficiency?', 'Dickens closes with indictment; McEwan closes with insufficiency. What does this difference tell us about each author''s confidence in literature''s moral function?', 'Dickens still believes literature can summarise and judge moral failure; McEwan leaves judgement itself ethically unstable — a century of literary history separates and explains both positions.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.paragraph_jobs (id, question_family, route_id, job_title, text1_prompt, text2_prompt, divergence_prompt, judgement_prompt) VALUES ('pj-perception-1a', 'truth', 'route-perception', 'Order imposed on reality', 'How does Dickens use "Now, what I want is, Facts" (imperative, declarative authority) to present reality as something externally imposed and ideologically reduced?', 'How does McEwan use "The play… was her first rehearsal of order" (theatrical framing, metafiction, focalisation) to present reality as something internally arranged by imagination?', 'Dickens attacks a pedagogic system that trains people to read badly; McEwan attacks a psychological urge to convert life into narrative design. In which novel does the distortion feel more preventable?', 'Together the novels imply that the desire to impose order on reality can originate either in institutional power or in imaginative self-assertion — and in both cases falsifies experience.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.paragraph_jobs (id, question_family, route_id, job_title, text1_prompt, text2_prompt, divergence_prompt, judgement_prompt) VALUES ('pj-perception-1b', 'truth', 'route-perception', 'Error before evidence', 'How does "Sissy is not a name" (negation) show Gradgrind''s system narrowing meaning before experience is even considered?', 'How does "Less like seeing, more like knowing" (paradox, free indirect discourse) show Briony''s consciousness mistaking assumption for knowledge?', 'Dickens presents presupposition as institutional dogma; McEwan presents it as psychological overconfidence. Which framing places greater moral blame on the individual?', 'The gravest interpretive mistakes arise not from lack of information alone, but from prior frameworks that decide what reality must mean before it is properly read.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.paragraph_jobs (id, question_family, route_id, job_title, text1_prompt, text2_prompt, divergence_prompt, judgement_prompt) VALUES ('pj-systems-7a', 'difficult_circumstances', 'route-systems', 'Human life under impersonal force', 'How does the "deadly statistical clock" (personified symbol, "deadly" modifier) present industrial order as mechanical, quantified and quietly lethal?', 'How does "There was our life, no longer available to us" (elegiac retrospection, "no longer available") frame loss as historical and irreversible, beyond individual remedy?', 'Dickens critiques industrial abstraction; McEwan critiques historical catastrophe. Do the novels suggest any form of resistance to these forces?', 'Whether crushed by industrial mechanism or by historical catastrophe, the result in both novels is the shrinking of available life — and both authors present this as systemic, not accidental.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.paragraph_jobs (id, question_family, route_id, job_title, text1_prompt, text2_prompt, divergence_prompt, judgement_prompt) VALUES ('pj-systems-7b', 'settings', 'route-systems', 'Settings as systems of harm', 'How does Coketown''s imagery ("unnatural red and black," "serpents of smoke," "deadly statistical clock") construct the industrial environment as actively dehumanising?', 'How does McEwan use the Dunkirk retreat and its sensory detail (the beach, the abandoned equipment, Robbie''s wound) to construct war as industrial-scale human cost?', 'Both settings function as systems of harm, but one is economic in origin and one is historical. How does each setting shape what kind of survival is possible?', 'Both novels span a century of systemic human cost from Victorian capitalism to total war — together they build a continuous historical argument about modernity''s indifference to individual life.') ON CONFLICT (id) DO NOTHING;
